  activeTab: string;
  setActiveTab: (tab: any) => void;
  isAdmin: boolean;
  currentUser: User;
  onLogout: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isAdmin, currentUser, onLogout }) => {
  const menuItems = [
    { id: 'dashboard', label: 'Dashboard', icon: LayoutDashboard },
    { id: 'tasks', label: 'Việc của tôi', icon: ListTodo },
    { id: 'search', label: isAdmin ? 'Tra cứu hệ thống' : 'Tìm kiếm công việc', icon: Search },
    { id: 'delegate', label: 'Giao việc', icon: Send },
    { id: 'profile', label: 'Hồ sơ', icon: UserCircle },
  ];

  if (currentUser.email === 'nhphong.hph@gdt.gov.vn') {
    menuItems.push({ id: 'import', label: 'Import Excel', icon: Upload });
  }

  return (
    <aside className="w-64 bg-white border-r border-slate-200 flex flex-col h-screen sticky top-0">
      <div className="p-6 border-b border-slate-100">
        <div className="flex items-center space-x-3 text-indigo-600">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-bold">T</div>
          <span className="text-xl font-bold tracking-tight text-slate-800">TaskMaster</span>
        </div>
      </div>

      <nav className="flex-1 p-4 space-y-1">
        {menuItems.map((item) => {
          const Icon = item.icon;
          return (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`w-full flex items-center space-x-3 px-4 py-3 rounded-xl transition-all duration-200 ${
                activeTab === item.id 
                  ? 'bg-indigo-50 text-indigo-600 font-medium' 
                  : 'text-slate-500 hover:bg-slate-50 hover:text-slate-800'
              }`}
            >
              <Icon size={20} />
              <span>{item.label}</span>
            </button>
          );
        })}
      </nav>

      <div className="p-4 border-t border-slate-100">
        <button
          onClick={onLogout}
          className="w-full flex items-center space-x-3 px-4 py-3 rounded-xl text-red-500 hover:bg-red-50 transition-all duration-200"
        >
          <LogOut size={20} />
          <span>Đăng xuất</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;

import React, { useMemo } from 'react';
import { User, Task, TaskStatus } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, Cell, PieChart, Pie } from 'recharts';

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const isAdmin = currentUser.notes === 'AD';

  const stats = useMemo(() => {
    const relevantTasks = isAdmin ? tasks : tasks.filter(t => t.unit === currentUser.unit);
    const completed = relevantTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
    const pending = relevantTasks.length - completed;

    const unitCounts: Record<string, { total: number; completed: number }> = {};
    relevantTasks.forEach(t => {
      if (!unitCounts[t.unit]) unitCounts[t.unit] = { total: 0, completed: 0 };
      unitCounts[t.unit].total++;
      if (t.status === TaskStatus.COMPLETED) unitCounts[t.unit].completed++;
    });

    const chartData = Object.entries(unitCounts).map(([name, val]) => ({
      name,
      total: val.total,
      completed: val.completed,
      pending: val.total - val.completed
    }));

    return { total: relevantTasks.length, completed, pending, chartData };
  }, [tasks, isAdmin, currentUser.unit]);

  const COLORS = ['#6366f1', '#10b981', '#f59e0b', '#ef4444'];

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-slate-500 uppercase">Tổng số công việc</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.total}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-emerald-500 uppercase">Đã hoàn thành</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.completed}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-amber-500 uppercase">Đang xử lý</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.pending}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Tiến độ theo Đơn vị</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.chartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip />
                <Bar dataKey="completed" fill="#10b981" radius={[4, 4, 0, 0]} name="Hoàn thành" />
                <Bar dataKey="pending" fill="#6366f1" radius={[4, 4, 0, 0]} name="Đang làm" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Danh sách nhân sự</h3>
          <div className="overflow-x-auto">
            <table className="w-full text-left text-sm">
              <thead>
                <tr className="border-b border-slate-100">
                  <th className="pb-3 font-semibold text-slate-600">Họ tên</th>
                  <th className="pb-3 font-semibold text-slate-600">Chức vụ</th>
                  <th className="pb-3 font-semibold text-slate-600">Đơn vị</th>
                  <th className="pb-3 font-semibold text-slate-600">Thao tác</th>
                </tr>
              </thead>
              <tbody>
                {users.slice(0, 5).map(u => (
                  <tr key={u.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50 transition-colors">
                    <td className="py-4 font-medium">{u.name}</td>
                    <td className="py-4 text-slate-500">{u.position}</td>
                    <td className="py-4 text-slate-500">{u.unit}</td>
                    <td className="py-4">
                      <button 
                        onClick={() => onUserClick(u.id)}
                        className="text-indigo-600 hover:text-indigo-800 font-medium"
                      >
                        Chi tiết
                      </button>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          </div>
          {users.length > 5 && (
            <p className="mt-4 text-center text-slate-400 text-xs italic">Hiển thị 5 nhân sự mới nhất</p>
          )}
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect } from 'react';
import { Task, TaskStatus } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string) => void;
  onToggleStatus: (taskId: string) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onToggleStatus }) => {
  const [newContent, setNewContent] = useState('');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim());
      setNewContent('');
    }
  };

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    const days = Math.floor(hours / 24);

    if (days > 0) return `${days}d ${hours % 24}h`;
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  return (
    <div className="space-y-8">
      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-200">
        <label className="block text-sm font-semibold text-slate-700 mb-2">Bạn đang làm gì?</label>
        <div className="flex space-x-2">
          <input
            type="text"
            value={newContent}
            onChange={(e) => setNewContent(e.target.value)}
            placeholder="Nhập nội dung công việc mới..."
            className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all"
          />
          <button
            type="submit"
            className="bg-indigo-600 text-white px-6 py-3 rounded-xl font-bold hover:bg-indigo-700 transition-colors flex items-center space-x-2"
          >
            <Plus size={20} />
            <span className="hidden sm:inline">Bắt đầu</span>
          </button>
        </div>
      </form>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
        {/* In Progress Section */}
        <section>
          <div className="flex items-center space-x-2 mb-4">
            <PlayCircle className="text-amber-500" />
            <h2 className="text-lg font-bold text-slate-800">Đang thực hiện ({tasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length})</h2>
          </div>
          <div className="space-y-4">
            {tasks.filter(t => t.status === TaskStatus.IN_PROGRESS).map(task => (
              <div key={task.id} className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm group">
                <div className="flex justify-between items-start">
                  <p className="font-medium text-slate-800 leading-relaxed">{task.content}</p>
                  <button 
                    onClick={() => onToggleStatus(task.id)}
                    className="p-2 text-slate-300 hover:text-emerald-500 hover:bg-emerald-50 rounded-lg transition-all"
                    title="Hoàn thành"
                  >
                    <CheckCircle2 size={24} />
                  </button>
                </div>
                <div className="mt-4 flex items-center space-x-4 text-xs font-medium">
                  <div className="flex items-center text-slate-400">
                    <Clock size={14} className="mr-1" />
                    Bắt đầu: {new Date(task.startTime).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}
                  </div>
                  <div className="px-2 py-1 bg-indigo-50 text-indigo-600 rounded-md">
                    Đã xử lý: {formatDuration(now - task.startTime)}
                  </div>
                </div>
              </div>
            ))}
            {tasks.filter(t => t.status === TaskStatus.IN_PROGRESS).length === 0 && (
              <p className="text-slate-400 italic text-sm">Chưa có công việc nào đang chạy.</p>
            )}
          </div>
        </section>

        {/* Completed Section */}
        <section>
          <div className="flex items-center space-x-2 mb-4">
            <CheckCircle2 className="text-emerald-500" />
            <h2 className="text-lg font-bold text-slate-800">Đã hoàn thành ({tasks.filter(t => t.status === TaskStatus.COMPLETED).length})</h2>
          </div>
          <div className="space-y-4">
            {tasks.filter(t => t.status === TaskStatus.COMPLETED).map(task => (
              <div key={task.id} className="bg-slate-50 p-5 rounded-2xl border border-slate-100 opacity-75">
                <div className="flex justify-between items-start">
                  <p className="font-medium text-slate-600 line-through leading-relaxed">{task.content}</p>
                  <button 
                    onClick={() => onToggleStatus(task.id)}
                    className="p-2 text-emerald-500 rounded-lg"
                    title="Mở lại"
                  >
                    <CheckCircle2 size={24} />
                  </button>
                </div>
                <div className="mt-4 flex items-center space-x-4 text-xs font-medium">
                   <div className="flex items-center text-slate-400">
                    <Clock size={14} className="mr-1" />
                    Tổng thời gian: {task.completedTime ? formatDuration(task.completedTime - task.startTime) : '-'}
                  </div>
                </div>
              </div>
            ))}
            {tasks.filter(t => t.status === TaskStatus.COMPLETED).length === 0 && (
              <p className="text-slate-400 italic text-sm">Chưa có công việc hoàn thành.</p>
            )}
          </div>
        </section>
      </div>
    </div>
  );
};

export default TaskBoard;

import React, { useState, useMemo, useEffect } from 'react';
import { User, Task, TaskStatus } from '../types';
import { Search, FileSpreadsheet, Filter, Calendar } from 'lucide-react';

declare const XLSX: any;

interface AdminSearchProps {
  users: User[];
  tasks: Task[];
  isAdmin: boolean;
  initialSelectedUserId?: string | null;
}

const AdminSearch: React.FC<AdminSearchProps> = ({ users, tasks, isAdmin, initialSelectedUserId }) => {
  const [searchName, setSearchName] = useState('');
  const [selectedUnit, setSelectedUnit] = useState('');
  const [selectedUserId, setSelectedUserId] = useState(initialSelectedUserId || '');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  useEffect(() => {
    if (initialSelectedUserId) setSelectedUserId(initialSelectedUserId);
  }, [initialSelectedUserId]);

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);

  const unitEmployees = useMemo(() => {
    if (!selectedUnit) return users;
    return users.filter(u => u.unit === selectedUnit);
  }, [selectedUnit, users]);

  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const user = users.find(u => u.id === task.userId);
      if (!user) return false;

      // Access control: Non-admins can only see their own search results usually,
      // but the requirement says Admin (AD) can view others.
      if (!isAdmin && task.userId !== selectedUserId) return false;

      const matchesUnit = selectedUnit ? user.unit === selectedUnit : true;
      const matchesUser = selectedUserId ? task.userId === selectedUserId : true;
      const matchesName = searchName ? user.name.toLowerCase().includes(searchName.toLowerCase()) : true;

      const taskTime = task.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesUnit && matchesUser && matchesName && matchesStart && matchesEnd;
    });
  }, [tasks, users, selectedUnit, selectedUserId, searchName, startDate, endDate, isAdmin]);

  const exportToExcel = () => {
    const exportData = filteredTasks.map(t => {
      const user = users.find(u => u.id === t.userId);
      return {
        'Họ tên': user?.name || 'N/A',
        'Đơn vị': user?.unit || 'N/A',
        'Nội dung công việc': t.content,
        'Trạng thái': t.status,
        'Ngày bắt đầu': new Date(t.startTime).toLocaleDateString('vi-VN'),
        'Thời gian thực hiện (phút)': t.completedTime 
          ? Math.round((t.completedTime - t.startTime) / 60000) 
          : Math.round((Date.now() - t.startTime) / 60000)
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Báo cáo công việc");
    XLSX.writeFile(workbook, `Bao_cao_cong_viec_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  return (
    <div className="space-y-6">
