import React, { useState, useMemo } from 'react';
import { User, TaskStatus } from '../types';
import { Send, Users, UserPlus } from 'lucide-react';

interface DelegationProps {
  currentUser: User;
  users: User[];
  onAssign: (content: string, leadId: string, collaboratorIds: string[]) => void;
}

const Delegation: React.FC<DelegationProps> = ({ currentUser, users, onAssign }) => {
  const [content, setContent] = useState('');
  const [selectedUnit, setSelectedUnit] = useState(currentUser.unit);
  const [leadId, setLeadId] = useState('');
  const [collaboratorIds, setCollaboratorIds] = useState<string[]>([]);

  const canDelegate = (targetLevel: string) => {
    // Logic: X1 -> X2, X2 -> X3, etc.
    const curr = parseInt(currentUser.delegateLevel.replace('X', ''));
    const target = parseInt(targetLevel.replace('X', ''));
    return target > curr;
  };

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);

  const targetEmployees = useMemo(() => {
    return users.filter(u => u.unit === selectedUnit && canDelegate(u.delegateLevel));
  }, [selectedUnit, users, currentUser.delegateLevel]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || !leadId) {
      alert('Vui lòng nhập nội dung và chọn người chủ trì.');
      return;
    }

    onAssign(content, leadId, collaboratorIds);
    alert(`Đã giao việc thành công cho ${users.find(u => u.id === leadId)?.name}. Thông báo đã được gửi đến email!`);

    // Reset form
    setContent('');
    setLeadId('');
    setCollaboratorIds([]);
  };

  const toggleCollaborator = (id: string) => {
    setCollaboratorIds(prev => 
      prev.includes(id) ? prev.filter(cid => cid !== id) : [...prev, id]
    );
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 bg-indigo-600 text-white">
          <h2 className="text-xl font-bold flex items-center space-x-2">
            <Send size={24} />
            <span>Giao nhiệm vụ công tác</span>
          </h2>
          <p className="text-indigo-100 text-sm mt-1">Cấp bậc của bạn: {currentUser.delegateLevel}. Bạn có thể giao việc cho nhân sự cấp thấp hơn.</p>
        </div>

        <form onSubmit={handleSubmit} className="p-8 space-y-6">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-2">Nội dung công việc</label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Mô tả chi tiết nhiệm vụ..."
              rows={4}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Đơn vị tiếp nhận</label>
              <select
                value={selectedUnit}
                onChange={(e) => { setSelectedUnit(e.target.value); setLeadId(''); setCollaboratorIds([]); }}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                {units.map(u => <option key={u} value={u}>{u}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-2">Người chủ trì</label>
              <select
                value={leadId}
                onChange={(e) => setLeadId(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              >
                <option value="">-- Chọn người chủ trì --</option>
                {targetEmployees.map(u => (
                  <option key={u.id} value={u.id}>{u.name} ({u.position} - {u.delegateLevel})</option>
                ))}
              </select>
            </div>
          </div>

          <div>
            <label className="block text-sm font-bold text-slate-700 mb-3 flex items-center space-x-2">
              <Users size={18} />
              <span>Người phối hợp (nếu có)</span>
            </label>
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-3 max-h-48 overflow-y-auto p-4 bg-slate-50 rounded-xl border border-slate-100">
              {targetEmployees.filter(u => u.id !== leadId).map(u => (
                <button
                  key={u.id}
                  type="button"
                  onClick={() => toggleCollaborator(u.id)}
                  className={`flex items-center space-x-2 px-3 py-2 rounded-lg text-sm border transition-all ${
                    collaboratorIds.includes(u.id)
                      ? 'bg-indigo-600 border-indigo-600 text-white shadow-md'
                      : 'bg-white border-slate-200 text-slate-600 hover:border-indigo-300'
                  }`}
                >
                  <UserPlus size={14} />
                  <span className="truncate">{u.name}</span>
                </button>
              ))}
              {targetEmployees.length <= 1 && (
                <p className="col-span-full text-slate-400 text-center py-4 text-sm italic">Không tìm thấy nhân sự phối hợp phù hợp cấp bậc.</p>
              )}
            </div>
          </div>

          <div className="pt-4">
            <button
              type="submit"
              className="w-full bg-indigo-600 text-white py-4 rounded-xl font-bold text-lg hover:bg-indigo-700 shadow-lg shadow-indigo-100 transition-all flex items-center justify-center space-x-2"
            >
              <Send size={22} />
              <span>Giao việc ngay</span>
            </button>
          </div>
        </form>
      </div>
    </div>
  );
};

export default Delegation;

import React, { useState } from 'react';
import { User, Gender, ADMIN_EMAIL_IMPORT, DEFAULT_PASSWORD } from '../types';
import { Upload, AlertCircle, FileText } from 'lucide-react';

declare const XLSX: any;

interface ImportDataProps {
  currentUser: any;
  onImport: (users: User[]) => void;
}

const ImportData: React.FC<ImportDataProps> = ({ currentUser, onImport }) => {
  const [isUploading, setIsUploading] = useState(false);

  if (currentUser.email !== ADMIN_EMAIL_IMPORT) {
    return (
      <div className="p-10 text-center">
        <AlertCircle size={48} className="mx-auto text-red-500 mb-4" />
        <h2 className="text-xl font-bold text-slate-800">Quyền truy cập bị từ chối</h2>
        <p className="text-slate-500">Chỉ tài khoản hệ thống ({ADMIN_EMAIL_IMPORT}) mới có quyền thực hiện chức năng này.</p>
      </div>
    );
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { header: 'A' });

        // Skip header row if needed. Assumption: Row 1 is header, data starts from Row 2
        // Map columns A-I to User object
        const newUsers: User[] = jsonData.slice(1).map((row: any, index: number) => ({
          id: `u-${Date.now()}-${index}`,
          name: row.A || '',
          position: row.B || '',
          unit: row.C || '',
          gender: (row.D === 'Nữ' ? Gender.FEMALE : Gender.MALE),
          dob: row.E || '',
          phone: row.F || '',
          email: row.G || '',
          password: DEFAULT_PASSWORD,
          delegateLevel: row.H || 'X3',
          notes: row.I || '',
          mustChangePassword: true
        })).filter((u: User) => u.email);

        onImport(newUsers);
      } catch (error) {
        alert('Lỗi khi đọc file Excel. Vui lòng kiểm tra định dạng.');
        console.error(error);
      } finally {
        setIsUploading(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm text-center">
        <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <Upload size={32} />
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Cập nhật cơ sở dữ liệu</h2>
        <p className="text-slate-500 mb-8">Tải lên file Excel mẫu chứa danh sách nhân sự mới. Hệ thống sẽ đồng bộ dựa trên địa chỉ Email (Cột G).</p>

        <div className="border-2 border-dashed border-slate-200 rounded-2xl p-10 hover:border-indigo-400 hover:bg-indigo-50 transition-all cursor-pointer relative">
          <input
            type="file"
            accept=".xlsx, .xls"
            onChange={handleFileUpload}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            disabled={isUploading}
          />
          <div className="space-y-4">
            <FileText size={48} className="mx-auto text-slate-300" />
            <p className="text-sm font-medium text-slate-600">
              {isUploading ? 'Đang xử lý...' : 'Kéo thả hoặc nhấp để chọn file Excel'}
            </p>
            <p className="text-xs text-slate-400">Định dạng hỗ trợ: .xlsx, .xls</p>
          </div>
        </div>

        <div className="mt-8 text-left bg-slate-50 p-6 rounded-xl border border-slate-100">
          <h3 className="text-sm font-bold text-slate-700 mb-3 uppercase tracking-wider">Cấu trúc cột yêu cầu:</h3>
          <ul className="grid grid-cols-2 gap-2 text-xs text-slate-500 font-medium">
            <li>• Cột A: Họ tên</li>
            <li>• Cột B: Chức vụ</li>
            <li>• Cột C: Đơn vị</li>
            <li>• Cột D: Giới tính</li>
            <li>• Cột E: Ngày sinh</li>
            <li>• Cột F: Số ĐT</li>
            <li>• Cột G: Email (Khóa chính)</li>
            <li>• Cột H: Cấp giao việc (X1,X2...)</li>
            <li>• Cột I: Ghi chú (AD cho Admin)</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default ImportData;

