export default UserProfile;

import React, { useState } from 'react';
// Fix: Import ADMIN_EMAIL_IMPORT and DEFAULT_PASSWORD from constants instead of types
import { User, Gender } from '../types';
import { ADMIN_EMAIL_IMPORT, DEFAULT_PASSWORD } from '../constants';
import { Upload, AlertCircle, FileText } from 'lucide-react';

declare const XLSX: any;

interface ImportDataProps {
  currentUser: any;
  onImport: (users: User[]) => void;
}

const ImportData: React.FC<ImportDataProps> = ({ currentUser, onImport }) => {
  const [isUploading, setIsUploading] = useState(false);

  if (currentUser.email !== ADMIN_EMAIL_IMPORT) {
    return (
      <div className="p-10 text-center">
        <AlertCircle size={48} className="mx-auto text-red-500 mb-4" />
        <h2 className="text-xl font-bold text-slate-800">Quyền truy cập bị từ chối</h2>
        <p className="text-slate-500">Chỉ tài khoản hệ thống ({ADMIN_EMAIL_IMPORT}) mới có quyền thực hiện chức năng này.</p>
      </div>
    );
  }

  const handleFileUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setIsUploading(true);
    const reader = new FileReader();
    reader.onload = (event) => {
      try {
        const data = new Uint8Array(event.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const sheetName = workbook.SheetNames[0];
        const sheet = workbook.Sheets[sheetName];
        const jsonData = XLSX.utils.sheet_to_json(sheet, { header: 'A' });

        // Skip header row if needed. Assumption: Row 1 is header, data starts from Row 2
        // Map columns A-I to User object
        const newUsers: User[] = jsonData.slice(1).map((row: any, index: number) => ({
          id: `u-${Date.now()}-${index}`,
          name: row.A || '',
          position: row.B || '',
          unit: row.C || '',
          gender: (row.D === 'Nữ' ? Gender.FEMALE : Gender.MALE),
          dob: row.E || '',
          phone: row.F || '',
          email: row.G || '',
          password: DEFAULT_PASSWORD,
          delegateLevel: row.H || 'X3',
          notes: row.I || '',
          mustChangePassword: true
        })).filter((u: User) => u.email);

        onImport(newUsers);
      } catch (error) {
        alert('Lỗi khi đọc file Excel. Vui lòng kiểm tra định dạng.');
        console.error(error);
      } finally {
        setIsUploading(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  return (
    <div className="max-w-2xl mx-auto">
      <div className="bg-white p-8 rounded-2xl border border-slate-200 shadow-sm text-center">
        <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-full flex items-center justify-center mx-auto mb-6">
          <Upload size={32} />
        </div>
        <h2 className="text-2xl font-bold text-slate-800 mb-2">Cập nhật cơ sở dữ liệu</h2>
        <p className="text-slate-500 mb-8">Tải lên file Excel mẫu chứa danh sách nhân sự mới. Hệ thống sẽ đồng bộ dựa trên địa chỉ Email (Cột G).</p>

        <div className="border-2 border-dashed border-slate-200 rounded-2xl p-10 hover:border-indigo-400 hover:bg-indigo-50 transition-all cursor-pointer relative">
          <input
            type="file"
            accept=".xlsx, .xls"
            onChange={handleFileUpload}
            className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            disabled={isUploading}
          />
          <div className="space-y-4">
            <FileText size={48} className="mx-auto text-slate-300" />
            <p className="text-sm font-medium text-slate-600">
              {isUploading ? 'Đang xử lý...' : 'Kéo thả hoặc nhấp để chọn file Excel'}
            </p>
            <p className="text-xs text-slate-400">Định dạng hỗ trợ: .xlsx, .xls</p>
          </div>
        </div>

        <div className="mt-8 text-left bg-slate-50 p-6 rounded-xl border border-slate-100">
          <h3 className="text-sm font-bold text-slate-700 mb-3 uppercase tracking-wider">Cấu trúc cột yêu cầu:</h3>
          <ul className="grid grid-cols-2 gap-2 text-xs text-slate-500 font-medium">
            <li>• Cột A: Họ tên</li>
            <li>• Cột B: Chức vụ</li>
            <li>• Cột C: Đơn vị</li>
            <li>• Cột D: Giới tính</li>
            <li>• Cột E: Ngày sinh</li>
            <li>• Cột F: Số ĐT</li>
            <li>• Cột G: Email (Khóa chính)</li>
            <li>• Cột H: Cấp giao việc (X1,X2...)</li>
            <li>• Cột I: Ghi chú (AD cho Admin)</li>
          </ul>
        </div>
      </div>
    </div>
  );
};

export default ImportData;

export enum TaskStatus {
  TO_DO = 'Cần làm',
  IN_PROGRESS = 'Đang làm',
  COMPLETED = 'Đã hoàn thành'
}

export enum TaskComplexity {
  MEDIUM = 'Trung bình',
  GOOD = 'Khá',
  COMPLEX = 'Phức tạp',
  VERY_COMPLEX = 'Rất phức tạp'
}

export enum Gender {
  MALE = 'Nam',
  FEMALE = 'Nữ'
}

export interface User {
  id: string;
  name: string;        // Cột A
  position: string;    // Cột B
  unit: string;        // Cột C
  gender: Gender;      // Cột D
  dob: string;         // Cột E
  phone: string;       // Cột F
  email: string;       // Cột G
  password: string;    
  delegateLevel: string; // Cột H (X1, X2, X3...)
  notes: string;       // Cột I (AD = Admin)
  mustChangePassword: boolean;
}

export interface Task {
  id: string;
  userId: string;
  content: string;
  startTime: number;
  completedTime?: number;
  status: TaskStatus;
  complexity: TaskComplexity;
  leadId: string;
  collaboratorIds: string[];
  unit: string;
}

export interface DashboardStats {
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  tasksByUnit: Record<string, number>;
}

import React, { useState, useEffect, useCallback } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from './types';
import { INITIAL_USERS, INITIAL_TASKS } from './constants';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import ImportData from './components/ImportData';
import UserProfile from './components/UserProfile';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('tm_users');
    return saved ? JSON.parse(saved) : INITIAL_USERS;
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('tm_tasks');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('tm_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('tm_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('tm_tasks', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('tm_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('tm_current_user');
    }
  }, [currentUser]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (!user.mustChangePassword) {
      setActiveTab('dashboard');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
    setViewedUserId(null);
  };

  const handleChangePassword = (newPass: string) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, password: newPass, mustChangePassword: false };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
  };

  const addTask = (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[]) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, // Always starts as TO_DO
      complexity: complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit
    };
    setTasks(prev => [newTask, ...prev]);
  };

  const updateTaskStatus = (taskId: string, newStatus: TaskStatus) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        return {
          ...t,
          status: newStatus,
          completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : t.completedTime,
          startTime: newStatus === TaskStatus.IN_PROGRESS && t.status === TaskStatus.TO_DO ? Date.now() : t.startTime
        };
      }
      return t;
    }));
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
  };

  const deleteTask = (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setTasks(prev => prev.filter(t => t.id !== taskId));
    }
  };

  const handleImport = (newUsers: User[]) => {
    setUsers(newUsers);
    alert('Dữ liệu đã được cập nhật thành công!');
  };

  if (!currentUser) {
    return <Login users={users} onLogin={handleLogin} />;
  }

  if (currentUser.mustChangePassword) {
    return <ChangePassword onComplete={handleChangePassword} />;
  }

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Tổng quan công việc'}
              {activeTab === 'tasks' && 'Công việc của tôi'}
              {activeTab === 'search' && 'Tra cứu & Báo cáo'}
              {activeTab === 'delegate' && 'Giao việc cho cấp dưới'}
              {activeTab === 'import' && 'Cập nhật hệ thống'}
              {activeTab === 'profile' && 'Thông tin cá nhân'}
            </h1>
            <p className="text-slate-500 text-sm">Xin chào, {currentUser.name} ({currentUser.position})</p>
          </div>
          <div className="flex items-center space-x-3">
             <div className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-semibold">
                {currentUser.unit}
             </div>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => {
            setViewedUserId(uid);
            setActiveTab('search');
          }} />
        )}

        {activeTab === 'tasks' && (
          <TaskBoard 
            tasks={tasks.filter(t => t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id))} 
            onAddTask={addTask}
            onUpdateStatus={updateTaskStatus}
            onUpdateTask={updateTask}
            onDeleteTask={deleteTask}
          />
        )}

        {activeTab === 'search' && (
          <AdminSearch 
            users={users} 
            tasks={tasks} 
            isAdmin={isAdmin}
            currentUser={currentUser}
            onUpdateTask={updateTask}
            initialSelectedUserId={viewedUserId}
          />
        )}

        {activeTab === 'delegate' && (
          <Delegation 
            currentUser={currentUser} 
            users={users} 
            onAssign={addTask}
          />
        )}

        {activeTab === 'import' && (
          <ImportData currentUser={currentUser} onImport={handleImport} />
        )}

        {activeTab === 'profile' && (
          <UserProfile user={currentUser} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { Task, TaskStatus, TaskComplexity } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, ListTodo, MoreVertical, X, Check } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity);
      setNewContent('');
      setNewComplexity(TaskComplexity.MEDIUM);
    }
  };

  const handleStartEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setEditContent(task.content);
    setEditComplexity(task.complexity);
  };

  const handleSaveEdit = () => {
    if (editingTaskId) {
      onUpdateTask(editingTaskId, { content: editContent, complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.GOOD: return 'bg-emerald-100 text-emerald-700';
      case TaskComplexity.COMPLEX: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_COMPLEX: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const TaskCard = ({ task }: { task: Task }) => {
    const isEditing = editingTaskId === task.id;

    if (isEditing) {
      return (
        <div className="bg-white p-4 rounded-2xl border-2 border-indigo-500 shadow-md space-y-3">
          <input
            type="text"
            value={editContent}
            onChange={(e) => setEditContent(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500"
          />
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="flex-1 bg-indigo-600 text-white py-2 rounded-lg text-sm font-bold flex items-center justify-center">
              <Check size={16} className="mr-1" /> Lưu
            </button>
            <button onClick={() => setEditingTaskId(null)} className="flex-1 bg-slate-200 text-slate-600 py-2 rounded-lg text-sm font-bold flex items-center justify-center">
              <X size={16} className="mr-1" /> Hủy
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm group hover:shadow-md transition-all">
        <div className="flex justify-between items-start mb-2">
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider ${getComplexityColor(task.complexity)}`}>
            {task.complexity}
          </span>
          <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => handleStartEdit(task)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Sửa">
              <Edit2 size={14} />
            </button>
            <button onClick={() => onDeleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg" title="Xóa">
              <Trash2 size={14} />
            </button>
          </div>
        </div>
        <p className="font-medium text-slate-800 leading-snug mb-3">{task.content}</p>

        <div className="flex items-center justify-between mt-auto pt-3 border-t border-slate-50">
          <div className="flex items-center text-[11px] text-slate-400">
            <Clock size={12} className="mr-1" />
            {task.status === TaskStatus.IN_PROGRESS 
              ? formatDuration(now - task.startTime)
              : task.status === TaskStatus.COMPLETED 
                ? formatDuration((task.completedTime || 0) - task.startTime)
                : 'Chưa bắt đầu'}
          </div>

          <div className="flex space-x-1">
            {task.status === TaskStatus.TO_DO && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
                className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center"
              >
                <PlayCircle size={12} className="mr-1" /> Bắt đầu
              </button>
            )}
            {task.status === TaskStatus.IN_PROGRESS && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)}
                className="bg-emerald-50 text-emerald-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-emerald-600 hover:text-white transition-all flex items-center"
              >
                <CheckCircle2 size={12} className="mr-1" /> Hoàn thành
              </button>
            )}
            {task.status === TaskStatus.COMPLETED && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
                className="text-slate-400 px-2 py-1 rounded-lg text-[11px] font-bold hover:text-indigo-600"
              >
                Mở lại
              </button>
            )}
          </div>
        </div>
      </div>
    );
  };

  const Column = ({ title, status, icon: Icon, colorClass }: { title: string, status: TaskStatus, icon: any, colorClass: string }) => {
    const filtered = tasks.filter(t => t.status === status);
    return (
      <div className="flex flex-col h-full bg-slate-100/50 rounded-3xl p-4 border border-slate-200">
        <div className="flex items-center justify-between mb-4 px-2">
          <div className="flex items-center space-x-2">
            <div className={`p-1.5 rounded-lg text-white ${colorClass}`}>
              <Icon size={16} />
            </div>
            <h3 className="font-bold text-slate-700">{title}</h3>
          </div>
          <span className="bg-white border border-slate-200 text-slate-400 text-xs px-2 py-0.5 rounded-full font-bold">
            {filtered.length}
          </span>
        </div>
        <div className="space-y-4 overflow-y-auto max-h-[calc(100vh-400px)] scrollbar-hide">
          {filtered.map(task => <TaskCard key={task.id} task={task} />)}
          {filtered.length === 0 && (
            <div className="text-center py-10 opacity-30">
              <Icon size={32} className="mx-auto mb-2" />
              <p className="text-xs font-medium">Trống</p>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-8">
      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <label className="block text-sm font-bold text-slate-700 mb-3">Thêm nhiệm vụ mới</label>
        <div className="flex flex-col sm:flex-row space-y-3 sm:space-y-0 sm:space-x-3">
          <input
            type="text"
            value={newContent}
            onChange={(e) => setNewContent(e.target.value)}
            placeholder="Bạn cần thực hiện công việc gì?"
            className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all shadow-inner"
          />
          <div className="flex space-x-2">
            <select
              value={newComplexity}
