import React, { useState, useMemo, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { Search, FileSpreadsheet, Filter, Calendar, BarChart3, Edit3 } from 'lucide-react';

declare const XLSX: any;

interface AdminSearchProps {
  users: User[];
  tasks: Task[];
  isAdmin: boolean;
  currentUser: User;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  initialSelectedUserId?: string | null;
}

const AdminSearch: React.FC<AdminSearchProps> = ({ users, tasks, isAdmin, currentUser, onUpdateTask, initialSelectedUserId }) => {
  const [searchName, setSearchName] = useState('');
  const [selectedUnit, setSelectedUnit] = useState('');
  const [selectedUserId, setSelectedUserId] = useState(initialSelectedUserId || '');
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedComplexity, setSelectedComplexity] = useState<string>('');

  useEffect(() => {
    if (initialSelectedUserId) setSelectedUserId(initialSelectedUserId);
  }, [initialSelectedUserId]);

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);
  const isChief = currentUser.position === 'Trưởng phòng';

  const unitEmployees = useMemo(() => {
    if (!selectedUnit) return users;
    return users.filter(u => u.unit === selectedUnit);
  }, [selectedUnit, users]);

  const filteredTasks = useMemo(() => {
    return tasks.filter(task => {
      const user = users.find(u => u.id === task.userId);
      if (!user) return false;

      // Access control: Non-admins can only see their own search results usually,
      // but AD and chiefs within their unit have more visibility
      const canSeeOther = isAdmin || (isChief && user.unit === currentUser.unit);
      if (!canSeeOther && task.userId !== currentUser.id) return false;

      const matchesUnit = selectedUnit ? user.unit === selectedUnit : true;
      const matchesUser = selectedUserId ? task.userId === selectedUserId : true;
      const matchesName = searchName ? user.name.toLowerCase().includes(searchName.toLowerCase()) : true;
      const matchesComplexity = selectedComplexity ? task.complexity === selectedComplexity : true;

      const taskTime = task.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesUnit && matchesUser && matchesName && matchesStart && matchesEnd && matchesComplexity;
    });
  }, [tasks, users, selectedUnit, selectedUserId, searchName, startDate, endDate, selectedComplexity, isAdmin, isChief, currentUser]);

  const exportToExcel = () => {
    const exportData = filteredTasks.map(t => {
      const user = users.find(u => u.id === t.userId);
      return {
        'Họ tên': user?.name || 'N/A',
        'Đơn vị': user?.unit || 'N/A',
        'Nội dung công việc': t.content,
        'Mức độ': t.complexity,
        'Trạng thái': t.status,
        'Ngày bắt đầu': new Date(t.startTime).toLocaleDateString('vi-VN'),
        'Thời gian thực hiện (phút)': t.completedTime 
          ? Math.round((t.completedTime - t.startTime) / 60000) 
          : Math.round((Date.now() - t.startTime) / 60000)
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Báo cáo công việc");
    XLSX.writeFile(workbook, `Bao_cao_cong_viec_${new Date().toISOString().split('T')[0]}.xlsx`);
  };

  const getComplexityBadge = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.GOOD: return 'bg-emerald-100 text-emerald-700';
      case TaskComplexity.COMPLEX: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_COMPLEX: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const handleUpdateComplexity = (taskId: string, newComplexity: TaskComplexity) => {
    onUpdateTask(taskId, { complexity: newComplexity });
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
        <div className="flex items-center space-x-2 mb-6">
          <Filter className="text-indigo-600" size={20} />
          <h2 className="text-lg font-bold text-slate-800">Bộ lọc tra cứu</h2>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6">
          {(isAdmin || isChief) && (
            <>
              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Đơn vị công tác</label>
                <select
                  value={selectedUnit}
                  onChange={(e) => { setSelectedUnit(e.target.value); setSelectedUserId(''); }}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                >
                  <option value="">Tất cả đơn vị</option>
                  {units.map(u => <option key={u} value={u}>{u}</option>)}
                </select>
              </div>

              <div>
                <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Nhân viên</label>
                <select
                  value={selectedUserId}
                  onChange={(e) => setSelectedUserId(e.target.value)}
                  className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
                >
                  <option value="">Tất cả nhân viên</option>
                  {unitEmployees.map(u => <option key={u.id} value={u.id}>{u.name}</option>)}
                </select>
              </div>
            </>
          )}

          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Mức độ phức tạp</label>
            <select
              value={selectedComplexity}
              onChange={(e) => setSelectedComplexity(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            >
              <option value="">Tất cả mức độ</option>
              {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
            </select>
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Tìm theo tên</label>
            <div className="relative">
              <input
                type="text"
                placeholder="Nhập tên..."
                value={searchName}
                onChange={(e) => setSearchName(e.target.value)}
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-10 pr-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
              />
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
            </div>
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Từ ngày</label>
            <input
              type="date"
              value={startDate}
              onChange={(e) => setStartDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            />
          </div>

          <div>
            <label className="block text-xs font-bold text-slate-500 uppercase mb-2 tracking-wider">Đến ngày</label>
            <input
              type="date"
              value={endDate}
              onChange={(e) => setEndDate(e.target.value)}
              className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none focus:ring-2 focus:ring-indigo-500 transition-all"
            />
          </div>

          <div className="flex items-end lg:col-span-2 xl:col-span-1">
            <button
              onClick={exportToExcel}
              className="w-full bg-emerald-600 text-white px-6 py-2.5 rounded-xl font-bold hover:bg-emerald-700 transition-colors flex items-center justify-center space-x-2"
            >
              <FileSpreadsheet size={20} />
              <span>Xuất Báo cáo Excel</span>
            </button>
          </div>
        </div>
      </div>

      <div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-6 border-b border-slate-100 flex justify-between items-center">
          <h3 className="font-bold text-slate-800">Kết quả tìm kiếm ({filteredTasks.length})</h3>
        </div>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead className="bg-slate-50">
              <tr>
                <th className="px-6 py-4 font-semibold text-slate-600">Nhân sự</th>
                <th className="px-6 py-4 font-semibold text-slate-600">Nội dung</th>
                <th className="px-6 py-4 font-semibold text-slate-600">Mức độ</th>
                <th className="px-6 py-4 font-semibold text-slate-600">Trạng thái</th>
                <th className="px-6 py-4 font-semibold text-slate-600">Thời gian</th>
              </tr>
            </thead>
            <tbody>
              {filteredTasks.map(task => {
                const user = users.find(u => u.id === task.userId);
                return (
                  <tr key={task.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50 transition-colors">
                    <td className="px-6 py-4">
                      <div className="font-medium text-slate-800">{user?.name}</div>
                      <div className="text-xs text-slate-400">{user?.unit}</div>
                    </td>
                    <td className="px-6 py-4 max-w-md">
                      <p className="text-slate-600 line-clamp-2">{task.content}</p>
                    </td>
                    <td className="px-6 py-4">
                      {isChief ? (
                        <select 
                          value={task.complexity}
                          onChange={(e) => handleUpdateComplexity(task.id, e.target.value as TaskComplexity)}
                          className={`px-2 py-1 rounded-lg text-xs font-bold border-none outline-none cursor-pointer ${getComplexityBadge(task.complexity)}`}
                        >
                          {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
                        </select>
                      ) : (
                        <span className={`px-2 py-1 rounded-full text-xs font-bold ${getComplexityBadge(task.complexity)}`}>
                          {task.complexity}
                        </span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-1 rounded-full text-xs font-bold ${
                        task.status === TaskStatus.COMPLETED 
                          ? 'bg-emerald-100 text-emerald-700' 
                          : task.status === TaskStatus.IN_PROGRESS
