import React, { useState, useEffect, useMemo } from 'react';
import { Task, TaskStatus, TaskComplexity } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, ListTodo, Search, X, Check, Filter } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterComplexity, setFilterComplexity] = useState<string>('All');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchesSearch = t.content.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesComplexity = filterComplexity === 'All' || t.complexity === filterComplexity;
      return matchesSearch && matchesComplexity;
    });
  }, [tasks, searchTerm, filterComplexity]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity);
      setNewContent('');
      setNewComplexity(TaskComplexity.MEDIUM);
    }
  };

  const handleStartEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setEditContent(task.content);
    setEditComplexity(task.complexity);
  };

  const handleSaveEdit = () => {
    if (editingTaskId) {
      onUpdateTask(editingTaskId, { content: editContent, complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.GOOD: return 'bg-emerald-100 text-emerald-700';
      case TaskComplexity.COMPLEX: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_COMPLEX: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const TaskCard: React.FC<{ task: Task }> = ({ task }) => {
    const isEditing = editingTaskId === task.id;

    if (isEditing) {
      return (
        <div className="bg-white p-4 rounded-2xl border-2 border-indigo-500 shadow-md space-y-3">
          <textarea
            value={editContent}
            onChange={(e) => setEditContent(e.target.value)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px]"
          />
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="flex-1 bg-indigo-600 text-white py-2 rounded-lg text-sm font-bold flex items-center justify-center">
              <Check size={16} className="mr-1" /> Lưu
            </button>
            <button onClick={() => setEditingTaskId(null)} className="flex-1 bg-slate-200 text-slate-600 py-2 rounded-lg text-sm font-bold flex items-center justify-center">
              <X size={16} className="mr-1" /> Hủy
            </button>
          </div>
        </div>
      );
    }

    return (
      <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm group hover:shadow-md transition-all border-l-4" 
           style={{ borderLeftColor: task.complexity === TaskComplexity.VERY_COMPLEX ? '#ef4444' : task.complexity === TaskComplexity.COMPLEX ? '#f59e0b' : '#6366f1' }}>
        <div className="flex justify-between items-start mb-2">
          <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider ${getComplexityColor(task.complexity)}`}>
            {task.complexity}
          </span>
          <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
            <button onClick={() => handleStartEdit(task)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Sửa">
              <Edit2 size={14} />
            </button>
            <button onClick={() => onDeleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg" title="Xóa">
              <Trash2 size={14} />
            </button>
          </div>
        </div>
        <p className="font-medium text-slate-800 leading-snug mb-3 break-words">{task.content}</p>

        <div className="flex items-center justify-between mt-auto pt-3 border-t border-slate-50">
          <div className="flex items-center text-[11px] text-slate-400">
            <Clock size={12} className="mr-1" />
            {task.status === TaskStatus.IN_PROGRESS 
              ? formatDuration(now - task.startTime)
              : task.status === TaskStatus.COMPLETED 
                ? formatDuration((task.completedTime || 0) - task.startTime)
                : 'Chưa bắt đầu'}
          </div>

          <div className="flex space-x-1">
            {task.status === TaskStatus.TO_DO && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
                className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center"
              >
                <PlayCircle size={12} className="mr-1" /> Bắt đầu
              </button>
            )}
            {task.status === TaskStatus.IN_PROGRESS && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)}
                className="bg-emerald-50 text-emerald-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-emerald-600 hover:text-white transition-all flex items-center"
              >
                <CheckCircle2 size={12} className="mr-1" /> Xong
              </button>
            )}
            {task.status === TaskStatus.COMPLETED && (
              <button 
                onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
                className="text-slate-400 px-2 py-1 rounded-lg text-[11px] font-bold hover:text-indigo-600"
              >
                Làm lại
              </button>
            )}
          </div>
        </div>
      </div>
    );
  };

  const Column: React.FC<{ title: string, status: TaskStatus, icon: any, colorClass: string }> = ({ title, status, icon: Icon, colorClass }) => {
    const list = filteredTasks.filter(t => t.status === status);
    return (
      <div className="flex flex-col h-[calc(100vh-280px)] bg-slate-100/50 rounded-3xl p-4 border border-slate-200">
        <div className="flex items-center justify-between mb-4 px-2">
          <div className="flex items-center space-x-2">
            <div className={`p-1.5 rounded-lg text-white ${colorClass}`}>
              <Icon size={16} />
            </div>
            <h3 className="font-bold text-slate-700">{title}</h3>
          </div>
          <span className="bg-white border border-slate-200 text-slate-400 text-xs px-2 py-0.5 rounded-full font-bold">
            {list.length}
          </span>
        </div>
        <div className="space-y-4 overflow-y-auto pr-1 custom-scrollbar">
          {list.map(task => <TaskCard key={task.id} task={task} />)}
          {list.length === 0 && (
            <div className="text-center py-10 opacity-20">
              <Icon size={48} className="mx-auto mb-2" />
              <p className="text-sm font-medium">Không có dữ liệu</p>
            </div>
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          <div className="lg:col-span-7">
            <label className="block text-sm font-bold text-slate-700 mb-2">Công việc mới</label>
            <div className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-2">
              <input
                type="text"
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Nội dung cần làm..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all shadow-inner"
              />
              <select
                value={newComplexity}
                onChange={(e) => setNewComplexity(e.target.value as TaskComplexity)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
              <button
                onClick={handleSubmit}
                className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-indigo-700 transition-all flex items-center justify-center space-x-2"
              >
                <Plus size={20} />
                <span>Thêm</span>
              </button>
            </div>
          </div>
          <div className="lg:col-span-5 border-l border-slate-100 pl-4">
            <label className="block text-sm font-bold text-slate-700 mb-2">Tìm kiếm & Lọc</label>
            <div className="flex space-x-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Tìm nội dung..."
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <select
                value={filterComplexity}
                onChange={(e) => setFilterComplexity(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-3 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
              >
                <option value="All">Tất cả</option>
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
        <Column title="Cần làm" status={TaskStatus.TO_DO} icon={ListTodo} colorClass="bg-slate-400" />
        <Column title="Đang làm" status={TaskStatus.IN_PROGRESS} icon={PlayCircle} colorClass="bg-amber-500" />
        <Column title="Đã hoàn thành" status={TaskStatus.COMPLETED} icon={CheckCircle2} colorClass="bg-emerald-500" />
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
      `}</style>
    </div>
  );
};

export default TaskBoard;

import React, { useState, useMemo } from 'react';
import { User, TaskStatus, TaskComplexity } from '../types';
import { Send, Users, UserPlus, AlertCircle, ShieldAlert } from 'lucide-react';

interface DelegationProps {
  currentUser: User;
  users: User[];
  onAssign: (content: string, complexity: TaskComplexity, leadId: string, collaboratorIds: string[]) => void;
}

const Delegation: React.FC<DelegationProps> = ({ currentUser, users, onAssign }) => {
  const [content, setContent] = useState('');
  const [complexity, setComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [selectedUnit, setSelectedUnit] = useState(currentUser.unit);
  const [leadId, setLeadId] = useState('');
  const [collaboratorIds, setCollaboratorIds] = useState<string[]>([]);

  // Logic: X1 (Rank 1) là cao nhất. X2 (Rank 2) là trung bình. X3 (Rank 3) là thấp nhất.
  // Rank thấp hơn (số lớn hơn) mới có thể được giao việc từ Rank cao hơn (số nhỏ hơn).
  const canDelegateTo = (targetLevel: string) => {
    const currRank = parseInt(currentUser.delegateLevel.replace(/\D/g, '')) || 99;
    const targetRank = parseInt(targetLevel.replace(/\D/g, '')) || 99;
    // Chỉ cho phép giao việc cho người có Rank thấp hơn (Số Rank lớn hơn)
    return targetRank > currRank;
  };

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);

  const targetEmployees = useMemo(() => {
    return users.filter(u => u.unit === selectedUnit && canDelegateTo(u.delegateLevel));
  }, [selectedUnit, users, currentUser.delegateLevel]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || !leadId) {
      alert('Vui lòng nhập đầy đủ nội dung và chọn người chủ trì.');
      return;
    }

    onAssign(content, complexity, leadId, collaboratorIds);
    alert(`Đã giao việc thành công cho ${users.find(u => u.id === leadId)?.name}. Hệ thống đã ghi nhận nhiệm vụ.`);

    // Reset form
    setContent('');
    setComplexity(TaskComplexity.MEDIUM);
    setLeadId('');
    setCollaboratorIds([]);
  };

  const toggleCollaborator = (id: string) => {
    setCollaboratorIds(prev => 
      prev.includes(id) ? prev.filter(cid => cid !== id) : [...prev, id]
    );
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-indigo-600 text-white relative overflow-hidden">
          <div className="relative z-10">
            <h2 className="text-2xl font-bold flex items-center space-x-3">
              <Send size={28} />
              <span>Giao nhiệm vụ công tác</span>
            </h2>
            <div className="flex items-center space-x-4 mt-3">
              <span className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm">
                Cấp bậc hiện tại: {currentUser.delegateLevel}
              </span>
              <p className="text-indigo-100 text-sm flex items-center">
                <AlertCircle size={14} className="mr-1" />
                Nguyên tắc: Chỉ giao việc cho cấp thấp hơn.
              </p>
            </div>
          </div>
          <div className="absolute -right-4 -bottom-4 text-white/10 rotate-12">
            <Send size={160} />
          </div>
        </div>

        <form onSubmit={handleSubmit} className="p-10 space-y-8">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-3">Nội dung công việc</label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Nhập mô tả chi tiết nhiệm vụ..."
              rows={4}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-2 focus:ring-indigo-500 focus:bg-white transition-all shadow-inner"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
             <div>
              <label className="block text-sm font-bold text-slate-700 mb-3">Mức độ phức tạp</label>
              <select
                value={complexity}
                onChange={(e) => setComplexity(e.target.value as TaskComplexity)}
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-semibold"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>

            <div>
              <label className="block text-sm font-bold text-slate-700 mb-3">Đơn vị tiếp nhận</label>
              <select
                value={selectedUnit}
                onChange={(e) => { setSelectedUnit(e.target.value); setLeadId(''); setCollaboratorIds([]); }}
