import React, { useState, useEffect, useMemo } from 'react';
import { Task, TaskStatus, TaskComplexity } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, ListTodo, Search, X, Check } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

// Định nghĩa TaskCard bên ngoài component chính để tránh re-mount làm mất vị trí cuộn
const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus 
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.GOOD: return 'bg-emerald-100 text-emerald-700';
      case TaskComplexity.COMPLEX: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_COMPLEX: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-2xl border-2 border-indigo-500 shadow-md space-y-3">
        <textarea
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px]"
        />
        <select
          value={editComplexity}
          onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
          className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none"
        >
          {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <div className="flex space-x-2">
          <button onClick={handleSaveEdit} className="flex-1 bg-indigo-600 text-white py-2 rounded-lg text-sm font-bold flex items-center justify-center">
            <Check size={16} className="mr-1" /> Lưu
          </button>
          <button onClick={() => setEditingTaskId(null)} className="flex-1 bg-slate-200 text-slate-600 py-2 rounded-lg text-sm font-bold flex items-center justify-center">
            <X size={16} className="mr-1" /> Hủy
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm group hover:shadow-md transition-all border-l-4" 
         style={{ borderLeftColor: task.complexity === TaskComplexity.VERY_COMPLEX ? '#ef4444' : task.complexity === TaskComplexity.COMPLEX ? '#f59e0b' : '#6366f1' }}>
      <div className="flex justify-between items-start mb-2">
        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider ${getComplexityColor(task.complexity)}`}>
          {task.complexity}
        </span>
        <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={() => handleStartEdit(task)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Sửa">
            <Edit2 size={14} />
          </button>
          <button onClick={() => onDeleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg" title="Xóa">
            <Trash2 size={14} />
          </button>
        </div>
      </div>
      <p className="font-medium text-slate-800 leading-snug mb-3 break-words">{task.content}</p>

      <div className="flex items-center justify-between mt-auto pt-3 border-t border-slate-50">
        <div className="flex items-center text-[11px] text-slate-400">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.IN_PROGRESS 
            ? formatDuration(now - task.startTime)
            : task.status === TaskStatus.COMPLETED 
              ? formatDuration((task.completedTime || 0) - task.startTime)
              : 'Chưa bắt đầu'}
        </div>

        <div className="flex space-x-1">
          {task.status === TaskStatus.TO_DO && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
              className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center"
            >
              <PlayCircle size={12} className="mr-1" /> Bắt đầu
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)}
              className="bg-emerald-50 text-emerald-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-emerald-600 hover:text-white transition-all flex items-center"
            >
              <CheckCircle2 size={12} className="mr-1" /> Xong
            </button>
          )}
          {task.status === TaskStatus.COMPLETED && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
              className="text-slate-400 px-2 py-1 rounded-lg text-[11px] font-bold hover:text-indigo-600"
            >
              Làm lại
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterComplexity, setFilterComplexity] = useState<string>('All');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchesSearch = t.content.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesComplexity = filterComplexity === 'All' || t.complexity === filterComplexity;
      return matchesSearch && matchesComplexity;
    });
  }, [tasks, searchTerm, filterComplexity]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity);
      setNewContent('');
      setNewComplexity(TaskComplexity.MEDIUM);
    }
  };

  const handleStartEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setEditContent(task.content);
    setEditComplexity(task.complexity);
  };

  const handleSaveEdit = () => {
    if (editingTaskId) {
      onUpdateTask(editingTaskId, { content: editContent, complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-4">
          <div className="lg:col-span-7">
            <label className="block text-sm font-bold text-slate-700 mb-2">Công việc mới</label>
            <div className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-2">
              <input
                type="text"
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Nội dung cần làm..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all shadow-inner"
              />
              <select
                value={newComplexity}
                onChange={(e) => setNewComplexity(e.target.value as TaskComplexity)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
              <button
                onClick={handleSubmit}
                className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-indigo-700 transition-all flex items-center justify-center space-x-2"
              >
                <Plus size={20} />
                <span>Thêm</span>
              </button>
            </div>
          </div>
          <div className="lg:col-span-5 border-l border-slate-100 pl-4">
            <label className="block text-sm font-bold text-slate-700 mb-2">Tìm kiếm & Lọc</label>
            <div className="flex space-x-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Tìm nội dung..."
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <select
                value={filterComplexity}
                onChange={(e) => setFilterComplexity(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-3 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
              >
                <option value="All">Tất cả</option>
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-3 gap-6 items-start">
        {[
          { title: "Cần làm", status: TaskStatus.TO_DO, icon: ListTodo, colorClass: "bg-slate-400" },
          { title: "Đang làm", status: TaskStatus.IN_PROGRESS, icon: PlayCircle, colorClass: "bg-amber-500" },
          { title: "Đã hoàn thành", status: TaskStatus.COMPLETED, icon: CheckCircle2, colorClass: "bg-emerald-500" }
        ].map(col => (
          <div key={col.status} className="flex flex-col h-[calc(100vh-280px)] bg-slate-100/50 rounded-3xl p-4 border border-slate-200">
            <div className="flex items-center justify-between mb-4 px-2">
              <div className="flex items-center space-x-2">
                <div className={`p-1.5 rounded-lg text-white ${col.colorClass}`}>
                  <col.icon size={16} />
                </div>
                <h3 className="font-bold text-slate-700">{col.title}</h3>
              </div>
              <span className="bg-white border border-slate-200 text-slate-400 text-xs px-2 py-0.5 rounded-full font-bold">
                {filteredTasks.filter(t => t.status === col.status).length}
              </span>
            </div>
            <div className="space-y-4 overflow-y-auto pr-1 custom-scrollbar">
              {filteredTasks.filter(t => t.status === col.status).map(task => (
                <TaskCard 
                  key={task.id} 
                  task={task} 
                  now={now}
                  editingTaskId={editingTaskId}
                  editContent={editContent}
                  editComplexity={editComplexity}
                  setEditContent={setEditContent}
                  setEditComplexity={setEditComplexity}
                  handleSaveEdit={handleSaveEdit}
                  setEditingTaskId={setEditingTaskId}
                  handleStartEdit={handleStartEdit}
                  onDeleteTask={onDeleteTask}
                  onUpdateStatus={onUpdateStatus}
                />
              ))}
              {filteredTasks.filter(t => t.status === col.status).length === 0 && (
                <div className="text-center py-10 opacity-20">
                  <col.icon size={48} className="mx-auto mb-2" />
                  <p className="text-sm font-medium">Không có dữ liệu</p>
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar {
          width: 5px;
        }
        .custom-scrollbar::-webkit-scrollbar-track {
          background: transparent;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb {
          background: #cbd5e1;
          border-radius: 10px;
        }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover {
          background: #94a3b8;
        }
      `}</style>
    </div>
  );
};

export default TaskBoard;

import React, { useMemo } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const isAdmin = currentUser.notes === 'AD';

  const stats = useMemo(() => {
    const relevantTasks = isAdmin ? tasks : tasks.filter(t => t.unit === currentUser.unit);
    const completed = relevantTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
    const pending = relevantTasks.length - completed;

    const unitCounts: Record<string, { total: number; completed: number }> = {};
    const complexityCounts: Record<string, number> = {
      [TaskComplexity.MEDIUM]: 0,
      [TaskComplexity.GOOD]: 0,
      [TaskComplexity.COMPLEX]: 0,
      [TaskComplexity.VERY_COMPLEX]: 0
    };

    relevantTasks.forEach(t => {
      // Unit stats
      if (!unitCounts[t.unit]) unitCounts[t.unit] = { total: 0, completed: 0 };
      unitCounts[t.unit].total++;
      if (t.status === TaskStatus.COMPLETED) unitCounts[t.unit].completed++;

      // Complexity stats
      if (t.complexity) {
        complexityCounts[t.complexity] = (complexityCounts[t.complexity] || 0) + 1;
      }
    });

    const unitChartData = Object.entries(unitCounts).map(([name, val]) => ({
      name,
      total: val.total,
      completed: val.completed,
      pending: val.total - val.completed
    }));

    const complexityChartData = Object.entries(complexityCounts).map(([name, value]) => ({
      name,
      value
    }));

    return { total: relevantTasks.length, completed, pending, unitChartData, complexityChartData };
  }, [tasks, isAdmin, currentUser.unit]);

  const COMPLEXITY_COLORS: Record<string, string> = {
    [TaskComplexity.MEDIUM]: '#6366f1',
    [TaskComplexity.GOOD]: '#10b981',
    [TaskComplexity.COMPLEX]: '#f59e0b',
    [TaskComplexity.VERY_COMPLEX]: '#ef4444'
  };

  return (
    <div className="space-y-6">
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-slate-500 uppercase">Tổng số công việc</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.total}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-emerald-500 uppercase">Đã hoàn thành</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.completed}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <p className="text-sm font-medium text-amber-500 uppercase">Đang xử lý</p>
          <p className="text-3xl font-bold text-slate-800 mt-1">{stats.pending}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Mức độ phức tạp</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stats.complexityChartData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={80}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {stats.complexityChartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COMPLEXITY_COLORS[entry.name]} />
                  ))}
                </Pie>
                <Tooltip />
                <Legend />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Tiến độ theo Đơn vị</h3>
          <div className="h-64">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.unitChartData}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} />
                <XAxis dataKey="name" axisLine={false} tickLine={false} />
                <YAxis axisLine={false} tickLine={false} />
                <Tooltip />
                <Bar dataKey="completed" fill="#10b981" radius={[4, 4, 0, 0]} name="Hoàn thành" />
                <Bar dataKey="pending" fill="#6366f1" radius={[4, 4, 0, 0]} name="Đang làm" />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <h3 className="text-lg font-bold text-slate-800 mb-6">Danh sách nhân sự mới nhất</h3>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-slate-100">
                <th className="pb-3 font-semibold text-slate-600">Họ tên</th>
                <th className="pb-3 font-semibold text-slate-600">Chức vụ</th>
                <th className="pb-3 font-semibold text-slate-600">Đơn vị</th>
                <th className="pb-3 font-semibold text-slate-600">Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {users.slice(0, 5).map(u => (
                <tr key={u.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50 transition-colors">
                  <td className="py-4 font-medium">{u.name}</td>
                  <td className="py-4 text-slate-500">{u.position}</td>
                  <td className="py-4 text-slate-500">{u.unit}</td>
                  <td className="py-4">
                    <button 
                      onClick={() => onUserClick(u.id)}
                      className="text-indigo-600 hover:text-indigo-800 font-medium"
                    >
                      Chi tiết
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

export default Dashboard;

import React, { useState, useEffect, useMemo } from 'react';
import { Task, TaskStatus, TaskComplexity } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, ListTodo, Search, X, Check } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

// TaskCard được định nghĩa bên ngoài để tránh re-mount làm mất vị trí cuộn
const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus 
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.GOOD: return 'bg-emerald-100 text-emerald-700';
      case TaskComplexity.COMPLEX: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_COMPLEX: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
    }
  };

  const getBorderColor = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return '#6366f1';
      case TaskComplexity.GOOD: return '#10b981';
      case TaskComplexity.COMPLEX: return '#f59e0b';
      case TaskComplexity.VERY_COMPLEX: return '#ef4444';
      default: return '#cbd5e1';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-2xl border-2 border-indigo-500 shadow-md space-y-3 mb-4">
        <textarea
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px] text-sm"
        />
        <select
          value={editComplexity}
          onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
          className="w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 outline-none text-sm"
        >
          {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <div className="flex space-x-2">
          <button onClick={handleSaveEdit} className="flex-1 bg-indigo-600 text-white py-2 rounded-lg text-sm font-bold flex items-center justify-center">
            <Check size={16} className="mr-1" /> Lưu
          </button>
          <button onClick={() => setEditingTaskId(null)} className="flex-1 bg-slate-200 text-slate-600 py-2 rounded-lg text-sm font-bold flex items-center justify-center">
            <X size={16} className="mr-1" /> Hủy
          </button>
        </div>
      </div>
    );
  }

  return (
    <div className="bg-white p-4 rounded-2xl border border-slate-200 shadow-sm group hover:shadow-md transition-all border-l-4 mb-4" 
         style={{ borderLeftColor: getBorderColor(task.complexity) }}>
      <div className="flex justify-between items-start mb-2">
        <span className={`text-[10px] font-bold px-2 py-0.5 rounded-full uppercase tracking-wider ${getComplexityColor(task.complexity)}`}>
          {task.complexity}
        </span>
        <div className="flex space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={() => handleStartEdit(task)} className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg" title="Sửa">
            <Edit2 size={14} />
          </button>
          <button onClick={() => onDeleteTask(task.id)} className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg" title="Xóa">
            <Trash2 size={14} />
          </button>
        </div>
      </div>
      <p className="font-medium text-slate-800 leading-snug mb-3 break-words text-sm">{task.content}</p>

      <div className="flex items-center justify-between mt-auto pt-3 border-t border-slate-50">
        <div className="flex items-center text-[11px] text-slate-400">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.IN_PROGRESS 
            ? formatDuration(now - task.startTime)
            : task.status === TaskStatus.COMPLETED 
              ? formatDuration((task.completedTime || 0) - task.startTime)
              : 'Chưa bắt đầu'}
        </div>

        <div className="flex space-x-1">
          {task.status === TaskStatus.TO_DO && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
              className="bg-indigo-50 text-indigo-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center"
            >
              <PlayCircle size={12} className="mr-1" /> Bắt đầu
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)}
              className="bg-emerald-50 text-emerald-600 px-3 py-1 rounded-lg text-[11px] font-bold hover:bg-emerald-600 hover:text-white transition-all flex items-center"
            >
              <CheckCircle2 size={12} className="mr-1" /> Xong
            </button>
          )}
          {task.status === TaskStatus.COMPLETED && (
            <button 
              onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)}
              className="text-slate-400 px-2 py-1 rounded-lg text-[11px] font-bold hover:text-indigo-600"
            >
              Mở lại
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [searchTerm, setSearchTerm] = useState('');
  const [filterComplexity, setFilterComplexity] = useState<string>('All');
  const [now, setNow] = useState(Date.now());

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredTasks = useMemo(() => {
    return tasks.filter(t => {
      const matchesSearch = t.content.toLowerCase().includes(searchTerm.toLowerCase());
      const matchesComplexity = filterComplexity === 'All' || t.complexity === filterComplexity;
      return matchesSearch && matchesComplexity;
    });
  }, [tasks, searchTerm, filterComplexity]);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity);
      setNewContent('');
      setNewComplexity(TaskComplexity.MEDIUM);
    }
  };

  const handleStartEdit = (task: Task) => {
    setEditingTaskId(task.id);
    setEditContent(task.content);
    setEditComplexity(task.complexity);
  };

  const handleSaveEdit = () => {
    if (editingTaskId) {
      onUpdateTask(editingTaskId, { content: editContent, complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  return (
    <div className="h-full flex flex-col space-y-6">
      {/* Header Form & Filter */}
      <div className="bg-white p-6 rounded-3xl shadow-sm border border-slate-200">
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-6">
          <div className="lg:col-span-7">
            <label className="block text-sm font-bold text-slate-700 mb-2">Thêm công việc</label>
            <form onSubmit={handleSubmit} className="flex flex-col sm:flex-row space-y-2 sm:space-y-0 sm:space-x-2">
              <input
                type="text"
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Bạn muốn làm gì?"
                className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 focus:ring-2 focus:ring-indigo-500 focus:bg-white outline-none transition-all shadow-inner"
              />
              <div className="flex space-x-2">
                <select
                  value={newComplexity}
                  onChange={(e) => setNewComplexity(e.target.value as TaskComplexity)}
                  className="bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
                >
                  {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
                </select>
                <button
                  type="submit"
                  className="bg-indigo-600 text-white px-6 py-3 rounded-2xl font-bold hover:bg-indigo-700 transition-all flex items-center justify-center space-x-2"
                >
                  <Plus size={20} />
                  <span>Thêm</span>
                </button>
              </div>
            </form>
          </div>
          <div className="lg:col-span-5 border-l border-slate-100 pl-4">
            <label className="block text-sm font-bold text-slate-700 mb-2">Tìm kiếm & Lọc</label>
            <div className="flex space-x-2">
              <div className="relative flex-1">
                <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
                <input
                  type="text"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                  placeholder="Tìm nội dung..."
                  className="w-full bg-slate-50 border border-slate-200 rounded-2xl pl-10 pr-4 py-3 focus:ring-2 focus:ring-indigo-500 outline-none transition-all"
                />
              </div>
              <select
                value={filterComplexity}
                onChange={(e) => setFilterComplexity(e.target.value)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-3 py-3 focus:ring-2 focus:ring-indigo-500 outline-none text-sm font-semibold"
              >
                <option value="All">Tất cả</option>
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
          </div>
        </div>
      </div>

      {/* Kanban Board */}
      <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 overflow-hidden min-h-0">
        {[
          { title: "Cần làm", status: TaskStatus.TO_DO, icon: ListTodo, colorClass: "bg-slate-400" },
          { title: "Đang làm", status: TaskStatus.IN_PROGRESS, icon: PlayCircle, colorClass: "bg-amber-500" },
          { title: "Đã hoàn thành", status: TaskStatus.COMPLETED, icon: CheckCircle2, colorClass: "bg-emerald-500" }
        ].map(col => {
          const columnTasks = filteredTasks.filter(t => t.status === col.status);
          return (
            <div key={col.status} className="flex flex-col h-[600px] bg-slate-100/50 rounded-3xl p-4 border border-slate-200">
              <div className="flex items-center justify-between mb-4 px-2 shrink-0">
                <div className="flex items-center space-x-2">
                  <div className={`p-1.5 rounded-lg text-white ${col.colorClass}`}>
                    <col.icon size={16} />
                  </div>
                  <h3 className="font-bold text-slate-700">{col.title}</h3>
                </div>
                <span className="bg-white border border-slate-200 text-slate-400 text-xs px-2 py-0.5 rounded-full font-bold">
                  {columnTasks.length}
