import React, { useState, useEffect, useMemo } from 'react';
import { Task, TaskStatus, TaskComplexity } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, ListTodo, Search, X, Check, GripVertical } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

/**
 * TaskCard được định nghĩa bên ngoài component chính TaskBoard 
 * để tránh việc React re-mount toàn bộ thẻ mỗi khi state thay đổi, 
 * giúp giải quyết lỗi tự động cuộn lên đầu trang (Scroll Bug).
 */
const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus 
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getStickyClass = (status: TaskStatus) => {
    switch (status) {
      case TaskStatus.TO_DO: return 'bg-[#fff9c4] border-[#fbc02d] rotate-[0.5deg]';
      case TaskStatus.IN_PROGRESS: return 'bg-[#e3f2fd] border-[#64b5f6] -rotate-[0.5deg]';
      case TaskStatus.COMPLETED: return 'bg-[#fce4ec] border-[#f06292] rotate-0';
      default: return 'bg-white';
    }
  };

  const getComplexityBadge = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.VERY_COMPLEX: return 'bg-red-500 text-white';
      case TaskComplexity.COMPLEX: return 'bg-orange-500 text-white';
      case TaskComplexity.GOOD: return 'bg-green-500 text-white';
      default: return 'bg-blue-500 text-white';
    }
  };

  const handleDragStart = (e: React.DragEvent) => {
    e.dataTransfer.setData('taskId', task.id);
    e.dataTransfer.setData('sourceStatus', task.status);
    e.dataTransfer.effectAllowed = 'move';
    const target = e.currentTarget as HTMLElement;
    setTimeout(() => target.style.opacity = '0.4', 0);
  };

  const handleDragEnd = (e: React.DragEvent) => {
    const target = e.currentTarget as HTMLElement;
    target.style.opacity = '1';
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-lg shadow-2xl border-2 border-indigo-600 mb-4 z-50">
        <textarea
          autoFocus
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded px-2 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px] text-sm font-medium"
        />
        <div className="mt-3 flex items-center justify-between">
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="bg-slate-50 border border-slate-200 rounded px-2 py-1 outline-none text-xs font-bold"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-1">
            <button onClick={handleSaveEdit} className="bg-indigo-600 text-white p-1.5 rounded hover:bg-indigo-700">
              <Check size={14} />
            </button>
            <button onClick={() => setEditingTaskId(null)} className="bg-slate-200 text-slate-600 p-1.5 rounded">
              <X size={14} />
            </button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      draggable
      onDragStart={handleDragStart}
      onDragEnd={handleDragEnd}
      className={`relative p-5 shadow-sm border rounded-sm cursor-grab active:cursor-grabbing transition-all hover:shadow-lg hover:-translate-y-1 mb-5 group ${getStickyClass(task.status)}`}
    >
      {/* Ghim giấy ảo */}
      <div className="absolute -top-2 left-1/2 -translate-x-1/2 w-4 h-4 rounded-full bg-red-400 shadow-inner opacity-40 group-hover:opacity-100 transition-opacity"></div>

      <div className="flex justify-between items-start mb-2">
        <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${getComplexityBadge(task.complexity)}`}>
          {task.complexity}
        </span>
        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button onClick={() => handleStartEdit(task)} className="p-1 text-slate-400 hover:text-indigo-600">
            <Edit2 size={12} />
          </button>
          <button onClick={() => onDeleteTask(task.id)} className="p-1 text-slate-400 hover:text-rose-600">
            <Trash2 size={12} />
          </button>
        </div>
      </div>

      <p className="font-semibold text-slate-800 leading-tight mb-4 min-h-[40px] text-sm whitespace-pre-wrap">
        {task.content}
      </p>

      <div className="flex items-center justify-between pt-2 border-t border-black/5">
        <div className="flex items-center text-[10px] font-bold text-slate-500">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.IN_PROGRESS 
            ? formatDuration(now - task.startTime)
            : task.status === TaskStatus.COMPLETED 
              ? formatDuration((task.completedTime || 0) - task.startTime)
              : 'Chờ'}
        </div>

        <div className="flex space-x-1">
          {task.status === TaskStatus.TO_DO && (
            <button onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)} className="text-indigo-600" title="Bắt đầu">
              <PlayCircle size={18} />
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)} className="text-emerald-600" title="Hoàn thành">
              <CheckCircle2 size={18} />
            </button>
          )}
        </div>
      </div>

      <div className="absolute bottom-1 right-1 opacity-10 group-hover:opacity-30">
        <GripVertical size={14} />
      </div>
    </div>
  );
};

