        ].map(col => {
          const colTasks = filteredTasks.filter(t => t.status === col.status);
          return (
            <div 
              key={col.status} 
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, col.status)}
              className="flex flex-col h-[calc(100vh-280px)] bg-white/40 backdrop-blur-sm rounded-[32px] p-5 border border-white shadow-sm"
            >
              <div className="flex items-center justify-between mb-6 px-2">
                <h3 className={`text-2xl font-black tracking-tighter uppercase ${col.color}`}>{col.title}</h3>
                <span className="bg-white px-2 py-0.5 rounded-lg text-xs font-bold text-slate-400 border border-slate-100">
                  {colTasks.length}
                </span>
              </div>

              <div className="flex-1 overflow-y-auto px-1 custom-scrollbar">
                {colTasks.map(task => (
                  <TaskCard 
                    key={task.id} 
                    task={task} 
                    now={now}
                    editingTaskId={editingTaskId}
                    editContent={editContent}
                    editComplexity={editComplexity}
                    setEditContent={setEditContent}
                    setEditComplexity={setEditComplexity}
                    handleSaveEdit={handleSaveEdit}
                    setEditingTaskId={setEditingTaskId}
                    handleStartEdit={handleStartEdit}
                    onDeleteTask={onDeleteTask}
                    onUpdateStatus={onUpdateStatus}
                  />
                ))}

                {colTasks.length === 0 && (
                  <div className="h-full flex items-center justify-center border-2 border-dashed border-slate-200 rounded-3xl opacity-20">
                    <p className="text-[10px] font-black uppercase tracking-widest text-slate-400">Trống</p>
                  </div>
                )}
              </div>
            </div>
          );
        })}
      </div>

      <style>{`
        .custom-scrollbar::-webkit-scrollbar { width: 4px; }
        .custom-scrollbar::-webkit-scrollbar-track { background: transparent; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #cbd5e1; border-radius: 10px; }
        .custom-scrollbar::-webkit-scrollbar-thumb:hover { background: #94a3b8; }
      `}</style>
    </div>
  );
};

