import React, { useMemo } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const isAdmin = currentUser.notes === 'AD';

  const stats = useMemo(() => {
    const relevantTasks = isAdmin ? tasks : tasks.filter(t => t.unit === currentUser.unit);
    const completed = relevantTasks.filter(t => t.status === TaskStatus.COMPLETED).length;
    const pending = relevantTasks.length - completed;

    const unitCounts: Record<string, { total: number; completed: number }> = {};
    const complexityCounts: Record<string, number> = {
      [TaskComplexity.MEDIUM]: 0,
      [TaskComplexity.GOOD]: 0,
      [TaskComplexity.COMPLEX]: 0,
      [TaskComplexity.VERY_COMPLEX]: 0
    };

    relevantTasks.forEach(t => {
      // Unit stats
      if (!unitCounts[t.unit]) unitCounts[t.unit] = { total: 0, completed: 0 };
      unitCounts[t.unit].total++;
      if (t.status === TaskStatus.COMPLETED) unitCounts[t.unit].completed++;

      // Complexity stats
      if (t.complexity) {
        complexityCounts[t.complexity] = (complexityCounts[t.complexity] || 0) + 1;
      }
    });

    const unitChartData = Object.entries(unitCounts).map(([name, val]) => ({
      name,
      total: val.total,
      completed: val.completed,
      pending: val.total - val.completed
    }));

    const complexityChartData = Object.entries(complexityCounts).map(([name, value]) => ({
      name,
      value
    }));

    return { total: relevantTasks.length, completed, pending, unitChartData, complexityChartData };
  }, [tasks, isAdmin, currentUser.unit]);

  const COMPLEXITY_COLORS: Record<string, string> = {
    [TaskComplexity.MEDIUM]: '#6366f1', // Indigo
    [TaskComplexity.GOOD]: '#10b981',   // Emerald
    [TaskComplexity.COMPLEX]: '#f59e0b', // Amber
    [TaskComplexity.VERY_COMPLEX]: '#ef4444' // Rose
  };

  return (
    <div className="space-y-6">
      {/* Overview Cards */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
          <p className="text-sm font-medium text-slate-500 uppercase tracking-wider">Tổng số công việc</p>
          <p className="text-4xl font-extrabold text-slate-800 mt-2">{stats.total}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
          <p className="text-sm font-medium text-emerald-500 uppercase tracking-wider">Đã hoàn thành</p>
          <p className="text-4xl font-extrabold text-slate-800 mt-2">{stats.completed}</p>
        </div>
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm flex flex-col items-center justify-center text-center">
          <p className="text-sm font-medium text-amber-500 uppercase tracking-wider">Đang xử lý</p>
          <p className="text-4xl font-extrabold text-slate-800 mt-2">{stats.pending}</p>
        </div>
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Complexity Distribution */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6 flex items-center">
            Phân bổ theo mức độ phức tạp
          </h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie
                  data={stats.complexityChartData}
                  cx="50%"
                  cy="50%"
                  innerRadius={60}
                  outerRadius={100}
                  paddingAngle={5}
                  dataKey="value"
                >
                  {stats.complexityChartData.map((entry, index) => (
                    <Cell key={`cell-${index}`} fill={COMPLEXITY_COLORS[entry.name]} />
                  ))}
                </Pie>
                <Tooltip 
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Legend iconType="circle" wrapperStyle={{ paddingTop: '20px' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Units Progress */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-lg font-bold text-slate-800 mb-6">Tiến độ theo Đơn vị</h3>
          <div className="h-[300px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.unitChartData} margin={{ top: 10, right: 10, left: -20, bottom: 0 }}>
                <CartesianGrid strokeDasharray="3 3" vertical={false} stroke="#f1f5f9" />
                <XAxis 
                  dataKey="name" 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }} 
                />
                <YAxis 
                  axisLine={false} 
                  tickLine={false} 
                  tick={{ fill: '#94a3b8', fontSize: 12 }} 
                />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 4px 6px -1px rgb(0 0 0 / 0.1)' }}
                />
                <Bar dataKey="completed" fill="#10b981" radius={[4, 4, 0, 0]} name="Hoàn thành" barSize={30} />
                <Bar dataKey="pending" fill="#6366f1" radius={[4, 4, 0, 0]} name="Đang làm" barSize={30} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Staff Table Summary */}
      <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm overflow-hidden">
        <h3 className="text-lg font-bold text-slate-800 mb-6">Nhân sự tiêu biểu</h3>
        <div className="overflow-x-auto">
          <table className="w-full text-left text-sm">
            <thead>
              <tr className="border-b border-slate-100">
                <th className="pb-3 font-semibold text-slate-600">Họ tên</th>
                <th className="pb-3 font-semibold text-slate-600">Chức vụ</th>
                <th className="pb-3 font-semibold text-slate-600">Đơn vị</th>
                <th className="pb-3 font-semibold text-slate-600 text-right">Thao tác</th>
              </tr>
            </thead>
            <tbody>
              {users.slice(0, 5).map(u => (
                <tr key={u.id} className="border-b border-slate-50 last:border-0 hover:bg-slate-50 transition-colors">
                  <td className="py-4 font-medium text-slate-800">{u.name}</td>
                  <td className="py-4 text-slate-500">{u.position}</td>
                  <td className="py-4 text-slate-500">{u.unit}</td>
                  <td className="py-4 text-right">
                    <button 
                      onClick={() => onUserClick(u.id)}
                      className="text-indigo-600 hover:text-indigo-800 font-bold"
                    >
                      Chi tiết
                    </button>
                  </td>
                </tr>
              ))}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
};

