                className="bg-slate-50 border border-slate-200 rounded-xl px-3 py-2.5 text-sm font-semibold outline-none"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
              <button onClick={handleSubmit} className="bg-indigo-600 text-white p-2.5 rounded-xl hover:bg-indigo-700 transition-all">
                <Plus size={24} />
              </button>
            </div>
          </div>
          <div className="w-full lg:w-72">
            <label className="block text-xs font-bold text-slate-400 mb-2 uppercase tracking-widest">Tìm kiếm nhanh</label>
            <div className="relative">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
              <input
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Lọc công việc..."
                className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-9 pr-4 py-2.5 focus:ring-2 focus:ring-indigo-500 outline-none text-sm"
              />
            </div>
          </div>
        </div>
      </div>

      <div className="flex-1 grid grid-cols-1 lg:grid-cols-3 gap-6 overflow-hidden min-h-0">
        {[
          { title: "Cần làm", status: TaskStatus.TO_DO, color: "text-slate-600" },
          { title: "Đang làm", status: TaskStatus.IN_PROGRESS, color: "text-blue-600" },
          { title: "Hoàn thành", status: TaskStatus.COMPLETED, color: "text-pink-600" }
        ].map(col => {
          const colTasks = filteredTasks.filter(t => t.status === col.status);
          return (
            <div 
              key={col.status} 
              onDragOver={handleDragOver}
              onDrop={(e) => handleDrop(e, col.status)}
              className="flex flex-col h-[calc(100vh-280px)] bg-white/40 backdrop-blur-sm rounded-[32px] p-5 border border-white shadow-sm"
            >
              <div className="flex items-center justify-between mb-6 px-2">
                <h3 className={`text-2xl font-black tracking-tighter uppercase ${col.color}`}>{col.title}</h3>
                <span className="bg-white px-2 py-0.5 rounded-lg text-xs font-bold text-slate-400 border border-slate-100">{colTasks.length}</span>
              </div>
              <div className="flex-1 overflow-y-auto px-1 custom-scrollbar">
                {colTasks.map(task => (
                  <TaskCard 
                    key={task.id} task={task} now={now}
                    editingTaskId={editingTaskId} editContent={editContent} editComplexity={editComplexity}
                    setEditContent={setEditContent} setEditComplexity={setEditComplexity}
                    handleSaveEdit={handleSaveEdit} setEditingTaskId={setEditingTaskId}
                    handleStartEdit={handleStartEdit} onDeleteTask={onDeleteTask} onUpdateStatus={onUpdateStatus}
                  />
