  }, [tasks, users, selectedUnit, selectedUserId, searchName, startDate, endDate, selectedComplexity, isAdmin, isChief, currentUser]);

  const formatFullDateTime = (timestamp: number | undefined) => {
    if (!timestamp) return '-';
    return new Date(timestamp).toLocaleString('vi-VN', {
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
      day: '2-digit',
      month: '2-digit',
      year: 'numeric'
    });
