        'Trạng thái': t.status,
        'Thời điểm bắt đầu': formatFullDateTime(t.startTime),
        'Thời điểm hoàn thành': t.completedTime ? formatFullDateTime(t.completedTime) : 'Chưa hoàn thành',
        'Tổng thời gian thực hiện': formatDurationDetailed(durationMs)
      };
    });

    const worksheet = XLSX.utils.json_to_sheet(exportData);
    const workbook = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(workbook, worksheet, "Báo cáo công việc");
    XLSX.writeFile(workbook, `Bao_cao_cong_viec_${new Date().getTime()}.xlsx`);
  };

  const getComplexityBadge = (c: TaskComplexity) => {
    switch (c) {
      case TaskComplexity.MEDIUM: return 'bg-blue-100 text-blue-700';
      case TaskComplexity.HARD: return 'bg-amber-100 text-amber-700';
      case TaskComplexity.VERY_HARD: return 'bg-rose-100 text-rose-700';
      default: return 'bg-slate-100 text-slate-700';
