                            : 'bg-slate-100 text-slate-700'
                      }`}>
                        {task.status}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-[11px] text-slate-500 font-mono">
                      <div className="flex items-center">
                        <Clock size={12} className="mr-1.5 text-slate-300" />
                        {formatFullDateTime(task.startTime)}
                      </div>
                    </td>
                    <td className="px-6 py-4 text-[11px] text-slate-500 font-mono">
                      <div className="flex items-center">
                        <CheckCircle size={12} className={`mr-1.5 ${task.completedTime ? 'text-emerald-400' : 'text-slate-200'}`} />
