import React, { useMemo, useState, useRef, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Calendar, Users, List, X, Info, Trophy, Target, Clock, CheckCircle2 } from 'lucide-react';

// Tái sử dụng logic SmartDateInput cho Dashboard
const SmartDateInput: React.FC<{
  label: string;
  value: string;
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');
  const dateInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) {
      setDisplayText('');
    }
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, '');
    if (raw.length > 8) raw = raw.slice(0, 8);
    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    } else if (raw.length >= 5) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    }
    setDisplayText(formatted);
    if (raw.length === 8) {
      const d = raw.slice(0, 2);
      const m = raw.slice(2, 4);
      const y = raw.slice(4, 8);
      const dateObj = new Date(`${y}-${m}-${d}`);
      if (!isNaN(dateObj.getTime())) onChange(`${y}-${m}-${d}`);
    }
  };

  return (
    <div className="flex-1">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input
          type="text"
          value={displayText}
          onChange={handleTextChange}
          placeholder="DD/MM/YYYY"
          className="w-full bg-white border border-slate-200 rounded-xl pl-4 pr-10 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center pointer-events-none">
          <Calendar size={16} className="text-slate-300 group-hover:text-indigo-500 transition-colors" />
        </div>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        />
      </div>
    </div>
  );
};

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; tasks: Task[] }>({
    isOpen: false,
    title: '',
    tasks: []
  });

  const isAdmin = currentUser.notes === 'AD' || currentUser.position === 'Quản trị hệ thống';
  const isHead = currentUser.position === 'Trưởng phòng';

  // Danh sách nhân viên trong phòng để lọc
  const unitUsers = useMemo(() => {
    return users.filter(u => isAdmin || u.unit === currentUser.unit);
  }, [users, currentUser.unit, isAdmin]);

  const getPoints = (complexity: TaskComplexity) => {
    switch (complexity) {
      case TaskComplexity.MEDIUM: return 1;
      case TaskComplexity.HARD: return 3;
      case TaskComplexity.VERY_HARD: return 5;
      default: return 0;
    }
  };

  const stats = useMemo(() => {
    const filtered = tasks.filter(t => {
      const user = users.find(u => u.id === t.userId);
      if (!user) return false;

      // Lọc theo quyền xem (Admin xem hết, Trưởng phòng xem đơn vị)
      const canSee = isAdmin || (user.unit === currentUser.unit);
      if (!canSee) return false;

      // Lọc theo nhân viên được chọn
      const matchesStaff = selectedStaffId ? t.userId === selectedStaffId : true;

      // Lọc theo thời gian
      const matchesStart = startDate ? t.startTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? t.startTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesStaff && matchesStart && matchesEnd;
    });

    const todoTasks = filtered.filter(t => t.status === TaskStatus.TO_DO);
    const inProgressTasks = filtered.filter(t => t.status === TaskStatus.IN_PROGRESS);
    const completedTasks = filtered.filter(t => t.status === TaskStatus.COMPLETED);

    // Tính điểm hiệu suất cho từng người
    const performanceData = unitUsers.map(u => {
      const userTasks = filtered.filter(t => t.userId === u.id);
      const totalScore = userTasks.reduce((acc, t) => acc + getPoints(t.complexity), 0);
      return {
        name: u.name,
        score: totalScore,
        count: userTasks.length
      };
    }).sort((a, b) => b.score - a.score);

    const complexityChartData = [
      { name: TaskComplexity.MEDIUM, value: filtered.filter(t => t.complexity === TaskComplexity.MEDIUM).length },
      { name: TaskComplexity.HARD, value: filtered.filter(t => t.complexity === TaskComplexity.HARD).length },
      { name: TaskComplexity.VERY_HARD, value: filtered.filter(t => t.complexity === TaskComplexity.VERY_HARD).length },
    ];

    return {
      total: filtered,
      todo: todoTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      complexityChartData,
      performanceData
    };
  }, [tasks, users, currentUser, isAdmin, startDate, endDate, selectedStaffId, unitUsers]);

  const COLORS = ['#6366f1', '#f59e0b', '#ef4444'];

  const openDetails = (title: string, taskList: Task[]) => {
    setDetailModal({ isOpen: true, title, tasks: taskList });
  };

  return (
    <div className="space-y-6 pb-20">
      {/* Bộ lọc Dashboard */}
      <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row items-end gap-4">
        <div className="flex-1 w-full">
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Lọc theo nhân sự</label>
          <div className="relative">
            <Users className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
            <select
              value={selectedStaffId}
              onChange={(e) => setSelectedStaffId(e.target.value)}
              className="w-full bg-white border border-slate-200 rounded-xl pl-9 pr-4 py-2 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium appearance-none"
            >
              <option value="">Tất cả nhân viên {isAdmin ? '' : 'trong phòng'}</option>
              {unitUsers.map(u => <option key={u.id} value={u.id}>{u.name} ({u.position})</option>)}
            </select>
          </div>
        </div>

        <div className="flex flex-row gap-4 w-full md:w-auto md:min-w-[400px]">
          <SmartDateInput label="Từ ngày" value={startDate} onChange={setStartDate} />
          <SmartDateInput label="Đến ngày" value={endDate} onChange={setEndDate} />
        </div>

        <button 
          onClick={() => { setStartDate(''); setEndDate(''); setSelectedStaffId(''); }}
          className="bg-slate-100 text-slate-500 px-4 py-2.5 rounded-xl hover:bg-slate-200 transition-colors text-xs font-bold uppercase tracking-widest"
        >
          Xóa lọc
        </button>
      </div>

      {/* Thống kê thẻ số lượng */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Tổng số công việc', count: stats.total.length, icon: List, color: 'indigo', list: stats.total },
          { label: 'Công việc cần làm', count: stats.todo.length, icon: Target, color: 'slate', list: stats.todo },
          { label: 'Đang xử lý', count: stats.inProgress.length, icon: Clock, color: 'amber', list: stats.inProgress },
          { label: 'Đã hoàn thành', count: stats.completed.length, icon: CheckCircle2, color: 'emerald', list: stats.completed },
        ].map((item, idx) => {
          const Icon = item.icon;
          return (
            <button
              key={idx}
              onClick={() => openDetails(item.label, item.list)}
              className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all group text-left relative overflow-hidden"
            >
              <div className={`absolute -right-2 -top-2 w-16 h-16 bg-${item.color}-50 rounded-full opacity-50 group-hover:scale-150 transition-transform`}></div>
              <div className="flex items-center justify-between relative z-10">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{item.label}</p>
                  <p className="text-3xl font-black text-slate-800 tracking-tighter">{item.count}</p>
                </div>
                <div className={`w-12 h-12 bg-${item.color}-50 text-${item.color}-600 rounded-xl flex items-center justify-center`}>
                  <Icon size={24} />
                </div>
              </div>
              <div className="mt-4 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-tight relative z-10">
                <Info size={12} className="mr-1" />
                Click để xem chi tiết
              </div>
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 lg:grid-cols-2 gap-6">
        {/* Biểu đồ điểm hiệu suất */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <div className="flex items-center justify-between mb-8">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
              <Trophy className="mr-2 text-amber-500" size={18} />
              Bảng điểm hiệu suất (1-3-5)
            </h3>
            <div className="flex space-x-2 text-[8px] font-bold uppercase text-slate-400">
              <span className="flex items-center"><div className="w-2 h-2 bg-indigo-500 rounded-full mr-1"></div> Điểm quy đổi</span>
            </div>
          </div>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.performanceData} layout="vertical" margin={{ left: 20, right: 40 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={120} fontSize={11} fontWeight="700" />
                <Tooltip 
                  cursor={{ fill: '#f8fafc' }}
                  content={({ active, payload }) => {
                    if (active && payload && payload.length) {
                      const data = payload[0].payload;
                      return (
                        <div className="bg-slate-900 text-white p-3 rounded-xl text-xs shadow-xl border border-white/10">
                          <p className="font-bold border-b border-white/10 pb-1 mb-1">{data.name}</p>
                          <p className="text-indigo-300">Tổng điểm: <span className="font-black">{data.score}</span></p>
                          <p className="text-slate-400">Số lượng việc: {data.count}</p>
                        </div>
                      );
                    }
                    return null;
                  }}
                />
                <Bar dataKey="score" fill="#6366f1" radius={[0, 8, 8, 0]} barSize={24} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        {/* Biểu đồ mức độ phức tạp */}
        <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center">
            <Target className="mr-2 text-indigo-500" size={18} />
            Phân bổ mức độ công việc
          </h3>
          <div className="h-[350px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={stats.complexityChartData} 
                  cx="50%" 
                  cy="50%" 
                  innerRadius={70} 
                  outerRadius={110} 
                  paddingAngle={8} 
                  dataKey="value"
                  stroke="none"
                >
                  {stats.complexityChartData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
                <Legend iconType="circle" verticalAlign="bottom" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold', textTransform: 'uppercase' }} />
              </PieChart>
            </ResponsiveContainer>
