                              {user?.name}
                            </span>
                            <span className={`text-[10px] font-black uppercase px-2 py-0.5 rounded ${
                              task.complexity === TaskComplexity.VERY_HARD ? 'bg-red-100 text-red-600' : 
                              task.complexity === TaskComplexity.HARD ? 'bg-amber-100 text-amber-600' : 'bg-blue-100 text-blue-600'
