            <div className="p-6 bg-slate-50 border-t border-slate-100 text-center">
              <button 
                onClick={() => setDetailModal({ ...detailModal, isOpen: false })}
                className="bg-slate-800 text-white px-8 py-3 rounded-2xl font-bold text-sm uppercase tracking-widest hover:bg-slate-900 transition-all"
              >
                Đóng cửa sổ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

