                            <p className="text-sm font-mono font-black text-slate-600">
                              {new Date(task.startTime).toLocaleDateString('vi-VN')}
                            </p>
                          </div>
                          <div className="hidden md:block">
                            <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">ID</p>
                            <p className="text-[10px] font-mono text-slate-300">#{task.id.slice(0, 8)}</p>
                          </div>
                        </div>
                      </div>
                    );
                  })}
                </div>
              ) : (
                <div className="py-20 text-center text-slate-300">
                  <List size={64} className="mx-auto mb-4 opacity-20" />
                  <p className="text-xl font-bold uppercase tracking-widest">Không có dữ liệu</p>
                </div>
              )}
            </div>

            <div className="p-6 bg-slate-50 border-t border-slate-200 text-center">
              <button 
                onClick={() => setDetailModal({ ...detailModal, isOpen: false })}
                className="bg-slate-800 text-white px-10 py-3.5 rounded-2xl font-black text-sm uppercase tracking-[0.2em] hover:bg-slate-900 transition-all shadow-lg shadow-slate-200"
              >
                Đóng cửa sổ
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

