import React, { useState, useRef, useEffect, useMemo } from 'react';
import { Search, ChevronDown, X } from 'lucide-react';

interface Option {
  id: string;
  label: string;
  subLabel?: string;
}

interface SearchableSelectProps {
  options: Option[];
  value: string;
  onChange: (value: string) => void;
  placeholder: string;
  emptyMessage?: string;
  label?: string;
}

const SearchableSelect: React.FC<SearchableSelectProps> = ({ 
  options, 
  value, 
  onChange, 
  placeholder, 
  emptyMessage = "Không tìm thấy kết quả",
  label
}) => {
  const [isOpen, setIsOpen] = useState(false);
  const [searchTerm, setSearchTerm] = useState('');
  const containerRef = useRef<HTMLDivElement>(null);

  const selectedOption = useMemo(() => options.find(opt => opt.id === value), [options, value]);

  const filteredOptions = useMemo(() => {
    if (!searchTerm) return options;
    const term = searchTerm.toLowerCase();
    return options.filter(opt => 
      opt.label.toLowerCase().includes(term) || 
      (opt.subLabel && opt.subLabel.toLowerCase().includes(term))
    );
  }, [options, searchTerm]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (containerRef.current && !containerRef.current.contains(event.target as Node)) {
        setIsOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSelect = (id: string) => {
    onChange(id);
    setIsOpen(false);
    setSearchTerm('');
  };

  return (
    <div className="flex-1 w-full" ref={containerRef}>
      {label && <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>}
      <div className="relative">
        <button
          type="button"
          onClick={() => setIsOpen(!isOpen)}
          className={`w-full bg-white border ${isOpen ? 'border-indigo-500 ring-2 ring-indigo-100' : 'border-slate-200'} rounded-xl px-4 py-2.5 text-sm flex items-center justify-between transition-all outline-none font-medium`}
        >
          <span className={selectedOption ? 'text-slate-800' : 'text-slate-400'}>
            {selectedOption ? selectedOption.label : placeholder}
          </span>
          <ChevronDown size={16} className={`text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        </button>

        {isOpen && (
          <div className="absolute z-[110] w-full mt-2 bg-white border border-slate-200 rounded-2xl shadow-2xl overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
            <div className="p-2 border-b border-slate-50 flex items-center bg-slate-50/50">
              <Search size={14} className="text-slate-400 ml-2" />
              <input
                autoFocus
                type="text"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
                placeholder="Tìm tên nhân viên..."
                className="w-full bg-transparent border-none px-3 py-2 text-sm outline-none focus:ring-0 font-medium"
              />
              {searchTerm && (
                <button onClick={() => setSearchTerm('')} className="p-1 hover:bg-slate-200 rounded-full text-slate-400">
                  <X size={14} />
                </button>
              )}
            </div>
            <div className="max-h-60 overflow-y-auto py-1">
              {filteredOptions.length > 0 ? (
                filteredOptions.map((opt) => (
                  <button
                    key={opt.id}
                    type="button"
                    onClick={() => handleSelect(opt.id)}
                    className={`w-full text-left px-4 py-2.5 text-sm hover:bg-indigo-50 transition-colors flex flex-col ${value === opt.id ? 'bg-indigo-50 border-l-4 border-indigo-500' : ''}`}
                  >
                    <span className={`font-bold ${value === opt.id ? 'text-indigo-600' : 'text-slate-800'}`}>{opt.label}</span>
                    {opt.subLabel && <span className="text-[10px] font-black text-slate-400 uppercase tracking-tighter">{opt.subLabel}</span>}
                  </button>
                ))
              ) : (
                <div className="px-4 py-6 text-center text-slate-400 text-xs font-medium italic">
                  {emptyMessage}
                </div>
              )}
            </div>
          </div>
        )}
      </div>
    </div>
  );
};

export default SearchableSelect;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Calendar, Users, List, X, Info, Trophy, Target, Clock, CheckCircle2, FileText } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

// Thành phần nhập liệu ngày thông minh đồng bộ với AdminSearch
const SmartDateInput: React.FC<{
  label: string;
  value: string; // YYYY-MM-DD
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');
  const dateInputRef = useRef<HTMLInputElement>(null);

  // Đồng bộ từ giá trị thực (YYYY-MM-DD) sang hiển thị (DD/MM/YYYY)
  useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) {
      setDisplayText('');
    }
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, ''); // Chỉ lấy số
    if (raw.length > 8) raw = raw.slice(0, 8);

    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    } else if (raw.length >= 5) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    }

    setDisplayText(formatted);

    // Nếu đã đủ 8 số (DDMMYYYY), chuyển đổi sang YYYY-MM-DD để lọc
    if (raw.length === 8) {
      const d = raw.slice(0, 2);
      const m = raw.slice(2, 4);
      const y = raw.slice(4, 8);
      const dateObj = new Date(`${y}-${m}-${d}`);
      if (!isNaN(dateObj.getTime())) {
        onChange(`${y}-${m}-${d}`);
      }
    }
  };

  return (
    <div className="flex-1">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input
          type="text"
          value={displayText}
          onChange={handleTextChange}
          placeholder="DD/MM/YYYY"
          className="w-full bg-white border border-slate-200 rounded-xl pl-4 pr-10 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center pointer-events-none">
          <Calendar size={16} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
        </div>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        />
      </div>
    </div>
  );
};

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; tasks: Task[] }>({
    isOpen: false,
    title: '',
    tasks: []
  });

  // Kiểm tra tài khoản AD (Cột I)
  const isGlobalAdmin = currentUser.notes === 'AD';

  // Phạm vi người dùng: AD thấy tất cả, người khác thấy người cùng đơn vị
  const accessibleUsers = useMemo(() => {
    if (isGlobalAdmin) return users;
    return users.filter(u => u.unit === currentUser.unit);
  }, [users, currentUser.unit, isGlobalAdmin]);

  const getPoints = (complexity: TaskComplexity) => {
    switch (complexity) {
      case TaskComplexity.MEDIUM: return 1;
      case TaskComplexity.HARD: return 3;
      case TaskComplexity.VERY_HARD: return 5;
      default: return 0;
    }
  };

  const staffOptions = useMemo(() => {
    const opts = users.map(u => ({
      id: u.id,
      label: u.name,
      subLabel: u.unit
    }));
    return [{ id: '', label: 'Tất cả nhân sự' }, ...opts];
  }, [users]);

  const stats = useMemo(() => {
    const filtered = tasks.filter(t => {
      const user = users.find(u => u.id === t.userId);
      if (!user) return false;

      // Quyền xem
      const canSee = isGlobalAdmin || (user.unit === currentUser.unit);
      if (!canSee) return false;

      // Lọc nhân viên (Chỉ áp dụng nếu AD chọn, hoặc nếu không chọn thì lấy hết trong scope)
      const matchesStaff = selectedStaffId ? t.userId === selectedStaffId : true;

      // Lọc thời gian
      const taskTime = t.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesStaff && matchesStart && matchesEnd;
    });

    const todoTasks = filtered.filter(t => t.status === TaskStatus.TO_DO);
    const inProgressTasks = filtered.filter(t => t.status === TaskStatus.IN_PROGRESS);
    const completedTasks = filtered.filter(t => t.status === TaskStatus.COMPLETED);

    // Tính điểm hiệu suất cho tất cả nhân viên trong phạm vi truy cập
    const performanceData = accessibleUsers.map(u => {
      const userTasks = filtered.filter(t => t.userId === u.id);
      const totalScore = userTasks.reduce((acc, t) => acc + getPoints(t.complexity), 0);
      return {
        name: u.name,
        score: totalScore,
        count: userTasks.length
      };
    })
    // Sắp xếp điểm số giảm dần
    .sort((a, b) => b.score - a.score);

    const complexityChartData = [
      { name: TaskComplexity.MEDIUM, value: filtered.filter(t => t.complexity === TaskComplexity.MEDIUM).length },
      { name: TaskComplexity.HARD, value: filtered.filter(t => t.complexity === TaskComplexity.HARD).length },
      { name: TaskComplexity.VERY_HARD, value: filtered.filter(t => t.complexity === TaskComplexity.VERY_HARD).length },
    ];

    return {
      total: filtered,
      todo: todoTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      complexityChartData,
      performanceData
    };
  }, [tasks, users, currentUser, isGlobalAdmin, startDate, endDate, selectedStaffId, accessibleUsers]);

  const COLORS = ['#6366f1', '#f59e0b', '#ef4444'];

  const openDetails = (title: string, taskList: Task[]) => {
    setDetailModal({ isOpen: true, title, tasks: taskList });
  };

  return (
    <div className="space-y-6 pb-20">
      {/* Bộ lọc Dashboard */}
      <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row items-end gap-4">
        {/* Bộ lọc nhân viên chỉ hiển thị cho AD */}
        {isGlobalAdmin && (
          <SearchableSelect
            label="Lọc theo nhân sự (Chỉ AD)"
            options={staffOptions}
            value={selectedStaffId}
            onChange={setSelectedStaffId}
            placeholder="Tất cả nhân sự"
          />
        )}

        <div className={`flex flex-row gap-4 w-full md:w-auto ${isGlobalAdmin ? 'md:min-w-[400px]' : 'flex-1'}`}>
          <SmartDateInput label="Từ ngày" value={startDate} onChange={setStartDate} />
          <SmartDateInput label="Đến ngày" value={endDate} onChange={setEndDate} />
        </div>

        <button 
          onClick={() => { setStartDate(''); setEndDate(''); setSelectedStaffId(''); }}
          className="bg-slate-100 text-slate-500 px-4 py-2.5 rounded-xl hover:bg-slate-200 transition-colors text-xs font-bold uppercase tracking-widest"
        >
          Xóa lọc
        </button>
      </div>

      {/* Thống kê thẻ số lượng */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Tổng số công việc', count: stats.total.length, icon: List, color: 'indigo', list: stats.total },
          { label: 'Công việc cần làm', count: stats.todo.length, icon: Target, color: 'slate', list: stats.todo },
          { label: 'Đang xử lý', count: stats.inProgress.length, icon: Clock, color: 'amber', list: stats.inProgress },
          { label: 'Đã hoàn thành', count: stats.completed.length, icon: CheckCircle2, color: 'emerald', list: stats.completed },
        ].map((item, idx) => {
          const Icon = item.icon;
          return (
            <button
              key={idx}
              onClick={() => openDetails(item.label, item.list)}
              className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all group text-left relative overflow-hidden"
            >
              <div className={`absolute -right-2 -top-2 w-16 h-16 bg-${item.color}-50 rounded-full opacity-50 group-hover:scale-150 transition-transform`}></div>
              <div className="flex items-center justify-between relative z-10">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{item.label}</p>
                  <p className="text-3xl font-black text-slate-800 tracking-tighter">{item.count}</p>
                </div>
                <div className={`w-12 h-12 bg-${item.color}-50 text-${item.color}-600 rounded-xl flex items-center justify-center`}>
                  <Icon size={24} />
                </div>
              </div>
              <div className="mt-4 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-tight relative z-10">
                <Info size={12} className="mr-1" />
                Click xem chi tiết
              </div>
            </button>
          );
        })}
      </div>

      <div className={`grid grid-cols-1 ${isGlobalAdmin ? 'lg:grid-cols-2' : 'lg:grid-cols-1'} gap-6`}>
        {/* Bảng so sánh điểm hiệu suất chỉ xuất hiện đối với AD */}
        {isGlobalAdmin && (
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <div className="flex items-center justify-between mb-8">
              <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest flex items-center">
