import React, { useState, useEffect, useCallback } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from './types';
import { INITIAL_USERS, INITIAL_TASKS, DEFAULT_PASSWORD } from './constants';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import ImportData from './components/ImportData';
import UserProfile from './components/UserProfile';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(() => {
    const saved = localStorage.getItem('tm_users');
    return saved ? JSON.parse(saved) : INITIAL_USERS;
  });

  const [tasks, setTasks] = useState<Task[]>(() => {
    const saved = localStorage.getItem('tm_tasks');
    return saved ? JSON.parse(saved) : INITIAL_TASKS;
  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('tm_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);

  useEffect(() => {
    localStorage.setItem('tm_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('tm_tasks', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('tm_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('tm_current_user');
    }
  }, [currentUser]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (!user.mustChangePassword) {
      setActiveTab('dashboard');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
    setViewedUserId(null);
  };

  const handleChangePassword = (newPass: string) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, password: newPass, mustChangePassword: false };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
  };

  const handleResetPassword = (email: string, newPass: string) => {
    setUsers(prev => prev.map(u => u.email.toLowerCase() === email.toLowerCase() ? { ...u, password: newPass, mustChangePassword: false } : u));
  };

  const addTask = (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[]) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, 
      complexity: complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit
    };
    setTasks(prev => [newTask, ...prev]);
  };

  const updateTaskStatus = (taskId: string, newStatus: TaskStatus) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        return {
          ...t,
          status: newStatus,
          completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : t.completedTime,
          startTime: newStatus === TaskStatus.IN_PROGRESS && t.status === TaskStatus.TO_DO ? Date.now() : t.startTime
        };
      }
      return t;
    }));
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
  };

  const deleteTask = (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setTasks(prev => prev.filter(t => t.id !== taskId));
    }
  };

  const handleImport = (newUsers: User[]) => {
    setUsers(newUsers);
    alert('Dữ liệu đã được cập nhật thành công!');
  };

  if (!currentUser) {
    return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  }

  if (currentUser.mustChangePassword) {
    return <ChangePassword onComplete={handleChangePassword} />;
  }

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={setActiveTab} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
      />

      <main className="flex-1 p-6 md:p-10 overflow-auto">
        <header className="mb-8 flex justify-between items-center">
          <div>
            <h1 className="text-2xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Tổng quan công việc'}
              {activeTab === 'tasks' && 'Công việc của tôi'}
              {activeTab === 'search' && 'Tra cứu & Báo cáo'}
              {activeTab === 'delegate' && 'Giao việc cho cấp dưới'}
              {activeTab === 'import' && 'Cập nhật hệ thống'}
              {activeTab === 'profile' && 'Thông tin cá nhân'}
            </h1>
            <p className="text-slate-500 text-sm">Xin chào, {currentUser.name} ({currentUser.position})</p>
          </div>
          <div className="flex items-center space-x-3">
             <div className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-xs font-semibold">
                {currentUser.unit}
             </div>
          </div>
        </header>

        {activeTab === 'dashboard' && (
          <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => {
            setViewedUserId(uid);
            setActiveTab('search');
          }} />
        )}

        {activeTab === 'tasks' && (
          <TaskBoard 
            tasks={tasks.filter(t => t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id))} 
            onAddTask={addTask}
            onUpdateStatus={updateTaskStatus}
            onUpdateTask={updateTask}
            onDeleteTask={deleteTask}
          />
        )}

        {activeTab === 'search' && (
          <AdminSearch 
            users={users} 
            tasks={tasks} 
            isAdmin={isAdmin}
            currentUser={currentUser}
            onUpdateTask={updateTask}
            onResetUserPassword={handleResetPassword}
            initialSelectedUserId={viewedUserId}
          />
        )}

        {activeTab === 'delegate' && (
          <Delegation 
            currentUser={currentUser} 
            users={users} 
            onAssign={addTask}
          />
        )}

        {activeTab === 'import' && (
          <ImportData currentUser={currentUser} onImport={handleImport} />
        )}

        {activeTab === 'profile' && (
          <UserProfile user={currentUser} />
        )}
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useRef, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Calendar, Users, List, X, Info, Trophy, Target, Clock, CheckCircle2, FileText, UserPlus, UserCheck } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

const SmartDateInput: React.FC<{
  label: string;
  value: string; 
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');

  useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) {
      setDisplayText('');
    }
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, ''); 
    if (raw.length > 8) raw = raw.slice(0, 8);

    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    } else if (raw.length >= 5) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    }

    setDisplayText(formatted);

    if (raw.length === 8) {
      const d = raw.slice(0, 2);
      const m = raw.slice(2, 4);
      const y = raw.slice(4, 8);
      const dateObj = new Date(`${y}-${m}-${d}`);
      if (!isNaN(dateObj.getTime())) {
        onChange(`${y}-${m}-${d}`);
      }
    }
  };

  return (
    <div className="flex-1">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input
          type="text"
          value={displayText}
          onChange={handleTextChange}
          placeholder="DD/MM/YYYY"
          className="w-full bg-white border border-slate-200 rounded-xl pl-4 pr-10 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center pointer-events-none">
          <Calendar size={16} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
        </div>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        />
      </div>
    </div>
  );
};

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; tasks: Task[] }>({
    isOpen: false,
    title: '',
    tasks: []
  });

  const isGlobalAdmin = currentUser.notes === 'AD';

  const accessibleUsers = useMemo(() => {
    if (isGlobalAdmin) return users;
    return users.filter(u => u.unit === currentUser.unit);
  }, [users, currentUser.unit, isGlobalAdmin]);

  const getPoints = (complexity: TaskComplexity) => {
    switch (complexity) {
      case TaskComplexity.MEDIUM: return 1;
      case TaskComplexity.HARD: return 3;
      case TaskComplexity.VERY_HARD: return 5;
      default: return 0;
    }
  };

  const staffOptions = useMemo(() => {
    const opts = users.map(u => ({
      id: u.id,
      label: u.name,
      subLabel: u.unit
    }));
    return [{ id: '', label: 'Tất cả nhân sự' }, ...opts];
  }, [users]);

  const stats = useMemo(() => {
    const filtered = tasks.filter(t => {
      const creator = users.find(u => u.id === t.userId);
      const lead = users.find(u => u.id === t.leadId);
      if (!creator && !lead) return false;

      // Quyền xem: AD thấy hết, user thường thấy việc thuộc đơn vị mình (dựa vào đơn vị của task)
      const canSee = isGlobalAdmin || (t.unit === currentUser.unit);
      if (!canSee) return false;

      // Lọc nhân viên: Kiểm tra nếu user là người giao, người chủ trì hoặc người phối hợp
      const matchesStaff = selectedStaffId 
        ? (t.userId === selectedStaffId || t.leadId === selectedStaffId || t.collaboratorIds.includes(selectedStaffId)) 
        : true;

      const taskTime = t.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesStaff && matchesStart && matchesEnd;
    });

    const todoTasks = filtered.filter(t => t.status === TaskStatus.TO_DO);
    const inProgressTasks = filtered.filter(t => t.status === TaskStatus.IN_PROGRESS);
    const completedTasks = filtered.filter(t => t.status === TaskStatus.COMPLETED);

    // Tính điểm hiệu suất:
    // 1. Chỉ dành cho nhân viên (không bao gồm Trưởng/Phó phòng)
    // 2. Người giao (userId) nhận 1 điểm/việc
    // 3. Người làm (leadId + collaborators) nhận điểm theo độ phức tạp khi Hoàn thành
    const performanceData = accessibleUsers
      .filter(u => !u.position.toLowerCase().includes('trưởng phòng') && !u.position.toLowerCase().includes('phó trưởng phòng'))
      .map(u => {
        // Điểm giao việc
        const assignedCount = filtered.filter(t => t.userId === u.id).length;
        const assignPoints = assignedCount * 1;

        // Điểm thực hiện (Chỉ khi hoàn thành)
        const leadTasks = filtered.filter(t => t.leadId === u.id && t.status === TaskStatus.COMPLETED);
        const collabTasks = filtered.filter(t => t.collaboratorIds.includes(u.id) && t.status === TaskStatus.COMPLETED);

        const completionPoints = [...leadTasks, ...collabTasks].reduce((acc, t) => acc + getPoints(t.complexity), 0);

        return {
          name: u.name,
          score: assignPoints + completionPoints,
          count: assignedCount + leadTasks.length + collabTasks.length
        };
      })
      .sort((a, b) => b.score - a.score);

    const complexityChartData = [
      { name: TaskComplexity.MEDIUM, value: filtered.filter(t => t.complexity === TaskComplexity.MEDIUM).length },
      { name: TaskComplexity.HARD, value: filtered.filter(t => t.complexity === TaskComplexity.HARD).length },
      { name: TaskComplexity.VERY_HARD, value: filtered.filter(t => t.complexity === TaskComplexity.VERY_HARD).length },
    ];

    return {
      total: filtered,
      todo: todoTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      complexityChartData,
      performanceData
    };
  }, [tasks, users, currentUser, isGlobalAdmin, startDate, endDate, selectedStaffId, accessibleUsers]);

  const COLORS = ['#6366f1', '#f59e0b', '#ef4444'];

  const openDetails = (title: string, taskList: Task[]) => {
    setDetailModal({ isOpen: true, title, tasks: taskList });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-5 rounded-2xl border border-slate-200 shadow-sm flex flex-col md:flex-row items-end gap-4">
        {isGlobalAdmin && (
          <SearchableSelect
            label="Lọc theo nhân sự (Chỉ AD)"
            options={staffOptions}
            value={selectedStaffId}
            onChange={setSelectedStaffId}
            placeholder="Tất cả nhân sự"
          />
        )}

        <div className={`flex flex-row gap-4 w-full md:w-auto ${isGlobalAdmin ? 'md:min-w-[400px]' : 'flex-1'}`}>
          <SmartDateInput label="Từ ngày" value={startDate} onChange={setStartDate} />
          <SmartDateInput label="Đến ngày" value={endDate} onChange={setEndDate} />
        </div>

        <button 
          onClick={() => { setStartDate(''); setEndDate(''); setSelectedStaffId(''); }}
          className="bg-slate-100 text-slate-500 px-4 py-2.5 rounded-xl hover:bg-slate-200 transition-colors text-xs font-bold uppercase tracking-widest"
        >
          Xóa lọc
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Tổng số công việc', count: stats.total.length, icon: List, color: 'indigo', list: stats.total },
          { label: 'Công việc cần làm', count: stats.todo.length, icon: Target, color: 'slate', list: stats.todo },
          { label: 'Đang xử lý', count: stats.inProgress.length, icon: Clock, color: 'amber', list: stats.inProgress },
          { label: 'Đã hoàn thành', count: stats.completed.length, icon: CheckCircle2, color: 'emerald', list: stats.completed },
        ].map((item, idx) => {
          const Icon = item.icon;
          return (
            <button
              key={idx}
              onClick={() => openDetails(item.label, item.list)}
              className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all group text-left relative overflow-hidden"
            >
              <div className={`absolute -right-2 -top-2 w-16 h-16 bg-${item.color}-50 rounded-full opacity-50 group-hover:scale-150 transition-transform`}></div>
              <div className="flex items-center justify-between relative z-10">
                <div>
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{item.label}</p>
                  <p className="text-3xl font-black text-slate-800 tracking-tighter">{item.count}</p>
                </div>
                <div className={`w-12 h-12 bg-${item.color}-50 text-${item.color}-600 rounded-xl flex items-center justify-center`}>
                  <Icon size={24} />
                </div>
              </div>
            </button>
          );
        })}
      </div>

      <div className={`grid grid-cols-1 ${isGlobalAdmin ? 'lg:grid-cols-2' : 'lg:grid-cols-1'} gap-6`}>
        {isGlobalAdmin && (
          <div className="bg-white p-6 rounded-2xl border border-slate-200 shadow-sm">
            <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-8 flex items-center">
              <Trophy className="mr-2 text-amber-500" size={18} />
              So sánh điểm nhân viên (Loại trừ lãnh đạo)
            </h3>
            <div className="h-[400px]">
              <ResponsiveContainer width="100%" height="100%">
