  });

  const [currentUser, setCurrentUser] = useState<User | null>(() => {
    const saved = localStorage.getItem('tm_current_user');
    return saved ? JSON.parse(saved) : null;
  });

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    localStorage.setItem('tm_users', JSON.stringify(users));
  }, [users]);

  useEffect(() => {
    localStorage.setItem('tm_tasks', JSON.stringify(tasks));
  }, [tasks]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('tm_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('tm_current_user');
    }
  }, [currentUser]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (!user.mustChangePassword) {
      setActiveTab('dashboard');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
    setViewedUserId(null);
  };

  const handleChangePassword = (newPass: string) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, password: newPass, mustChangePassword: false };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
  };

  const handleResetPassword = (email: string, newPass: string) => {
    setUsers(prev => prev.map(u => u.email.toLowerCase() === email.toLowerCase() ? { ...u, password: newPass, mustChangePassword: false } : u));
  };

  const addTask = (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[]) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, 
      complexity: complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit
    };
    setTasks(prev => [newTask, ...prev]);
  };

  const updateTaskStatus = (taskId: string, newStatus: TaskStatus) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        return {
          ...t,
          status: newStatus,
          completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : t.completedTime,
          startTime: newStatus === TaskStatus.IN_PROGRESS && t.status === TaskStatus.TO_DO ? Date.now() : t.startTime
        };
      }
      return t;
    }));
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
  };

  const deleteTask = (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setTasks(prev => prev.filter(t => t.id !== taskId));
    }
  };

  const handleImport = (newUsers: User[]) => {
    setUsers(newUsers);
    alert('Dữ liệu đã được cập nhật thành công!');
  };

  if (!currentUser) {
    return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  }

  if (currentUser.mustChangePassword) {
    return <ChangePassword onComplete={handleChangePassword} />;
  }

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row">
      {/* Sidebar - Cả bản Desktop và Mobile Drawer */}
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
          setActiveTab(tab);
          setIsSidebarOpen(false); // Đóng sidebar sau khi chọn trên mobile
        }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      {/* Mobile Header */}
      <div className="md:hidden flex items-center justify-between px-6 py-4 bg-white border-b border-slate-200 sticky top-0 z-40">
        <div className="flex items-center space-x-2 text-indigo-600">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-black text-lg">Q</div>
          <span className="font-black text-slate-800 uppercase tracking-tight text-sm">Quản trị</span>
        </div>
        <button 
          onClick={() => setIsSidebarOpen(true)}
          className="p-2 text-slate-500 hover:bg-slate-100 rounded-lg"
        >
          <Menu size={24} />
        </button>
      </div>

      <main className="flex-1 p-4 md:p-10 overflow-x-hidden">
        <header className="mb-6 md:mb-8 flex flex-col sm:flex-row sm:justify-between sm:items-center gap-4">
          <div>
            <h1 className="text-xl md:text-2xl font-bold text-slate-800">
              {activeTab === 'dashboard' && 'Tổng quan công việc'}
              {activeTab === 'tasks' && 'Công việc của tôi'}
              {activeTab === 'search' && 'Tra cứu & Báo cáo'}
              {activeTab === 'delegate' && 'Giao việc cho cấp dưới'}
              {activeTab === 'import' && 'Cập nhật hệ thống'}
              {activeTab === 'profile' && 'Thông tin cá nhân'}
            </h1>
            <p className="text-slate-500 text-xs md:text-sm">Xin chào, {currentUser.name} ({currentUser.position})</p>
          </div>
          <div className="flex items-center space-x-3 self-start sm:self-auto">
             <div className="bg-indigo-100 text-indigo-700 px-3 py-1 rounded-full text-[10px] md:text-xs font-semibold">
                {currentUser.unit}
             </div>
          </div>
        </header>

        <div className="w-full">
          {activeTab === 'dashboard' && (
            <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => {
              setViewedUserId(uid);
              setActiveTab('search');
            }} />
          )}

          {activeTab === 'tasks' && (
            <TaskBoard 
              tasks={tasks.filter(t => t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id))} 
              onAddTask={addTask}
              onUpdateStatus={updateTaskStatus}
              onUpdateTask={updateTask}
              onDeleteTask={deleteTask}
            />
          )}

          {activeTab === 'search' && (
            <AdminSearch 
              users={users} 
              tasks={tasks} 
              isAdmin={isAdmin}
              currentUser={currentUser}
              onUpdateTask={updateTask}
              onResetUserPassword={handleResetPassword}
              initialSelectedUserId={viewedUserId}
            />
          )}

          {activeTab === 'delegate' && (
            <Delegation 
              currentUser={currentUser} 
              users={users} 
              onAssign={addTask}
            />
          )}

          {activeTab === 'import' && (
            <ImportData currentUser={currentUser} onImport={handleImport} />
          )}

          {activeTab === 'profile' && (
            <UserProfile user={currentUser} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

