          <div className="flex-1">
            <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">Việc mới</label>
            <div className="flex space-x-2">
              <input
                type="text"
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Nội dung..."
                className="flex-1 bg-slate-50 border border-slate-200 rounded-xl px-4 py-2.5 outline-none text-sm"
              />
              <button onClick={handleSubmit} className="bg-indigo-600 text-white px-4 rounded-xl hover:bg-indigo-700 transition-all">
                <Plus size={20} />
              </button>
            </div>
          </div>
          <div className="w-full lg:w-64">
            <label className="block text-[10px] font-black text-slate-400 mb-2 uppercase tracking-widest">Lọc</label>
