            { title: "Cần làm", status: TaskStatus.TO_DO, color: "text-slate-500", bg: "bg-slate-100" },
            { title: "Đang làm", status: TaskStatus.IN_PROGRESS, color: "text-blue-600", bg: "bg-blue-50" },
            { title: "Hoàn thành", status: TaskStatus.COMPLETED, color: "text-pink-600", bg: "bg-pink-50" }
          ].map(col => (
            <div 
              key={col.status} 
              onDragOver={(e) => e.preventDefault()}
              onDrop={(e) => {
                const id = e.dataTransfer.getData('taskId');
                onUpdateStatus(id, col.status);
              }}
              className="w-[85vw] md:w-1/3 flex flex-col snap-start shrink-0 h-[calc(100vh-320px)] md:h-[calc(100vh-280px)] bg-white/50 backdrop-blur-sm rounded-[2rem] p-4 md:p-5 border border-white shadow-sm overflow-hidden"
            >
              <div className="flex items-center justify-between mb-4 px-2 shrink-0">
                <h3 className={`text-lg md:text-xl font-black uppercase ${col.color}`}>{col.title}</h3>
                <span className="bg-white px-2 py-0.5 rounded-lg text-[10px] font-bold text-slate-400 border border-slate-100">
                  {filteredTasks.filter(t => t.status === col.status).length}
                </span>
              </div>
              <div className="flex-1 overflow-y-auto px-1 custom-scrollbar">
                {filteredTasks.filter(t => t.status === col.status).map(task => (
                  <TaskCard 
                    key={task.id} task={task} now={now}
                    editingTaskId={editingTaskId} editContent={editContent} editComplexity={editComplexity}
                    setEditContent={setEditContent} setEditComplexity={setEditComplexity}
                    handleSaveEdit={handleSaveEdit} setEditingTaskId={setEditingTaskId}
                    handleStartEdit={(t) => { setEditingTaskId(t.id); setEditContent(t.content); setEditComplexity(t.complexity); }}
                    onDeleteTask={onDeleteTask} onUpdateStatus={onUpdateStatus}
                  />
                ))}
              </div>
            </div>
          ))}
        </div>
      </div>
      <style>{`
        .hide-scrollbar::-webkit-scrollbar { display: none; }
        .hide-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }
        .custom-scrollbar::-webkit-scrollbar { width: 3px; }
        .custom-scrollbar::-webkit-scrollbar-thumb { background: #e2e8f0; border-radius: 10px; }
      `}</style>
    </div>
  );
};

