import React, { useMemo, useState, useRef, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Calendar, Users, List, X, Info, Trophy, Target, Clock, CheckCircle2, FileText, UserPlus, UserCheck } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

const SmartDateInput: React.FC<{
  label: string;
  value: string; 
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');

  useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) {
      setDisplayText('');
    }
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, ''); 
    if (raw.length > 8) raw = raw.slice(0, 8);

    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    } else if (raw.length >= 5) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    }

    setDisplayText(formatted);

    if (raw.length === 8) {
      const d = raw.slice(0, 2);
      const m = raw.slice(2, 4);
      const y = raw.slice(4, 8);
      const dateObj = new Date(`${y}-${m}-${d}`);
      if (!isNaN(dateObj.getTime())) {
        onChange(`${y}-${m}-${d}`);
      }
    }
  };

  return (
    <div className="flex-1 w-full sm:w-auto">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input
          type="text"
          value={displayText}
          onChange={handleTextChange}
          placeholder="DD/MM/YYYY"
          className="w-full bg-white border border-slate-200 rounded-xl pl-4 pr-10 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center pointer-events-none">
          <Calendar size={16} className="text-slate-400 group-hover:text-indigo-500 transition-colors" />
        </div>
        <input
          type="date"
          value={value}
          onChange={(e) => onChange(e.target.value)}
          className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
        />
      </div>
    </div>
  );
};

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; tasks: Task[] }>({
    isOpen: false,
    title: '',
    tasks: []
  });

  const isGlobalAdmin = currentUser.notes === 'AD';

  const accessibleUsers = useMemo(() => {
    if (isGlobalAdmin) return users;
    return users.filter(u => u.unit === currentUser.unit);
  }, [users, currentUser.unit, isGlobalAdmin]);

  const getPoints = (complexity: TaskComplexity) => {
    switch (complexity) {
      case TaskComplexity.MEDIUM: return 1;
      case TaskComplexity.HARD: return 3;
      case TaskComplexity.VERY_HARD: return 5;
      default: return 0;
    }
  };

  const staffOptions = useMemo(() => {
    const opts = users.map(u => ({
      id: u.id,
      label: u.name,
      subLabel: u.unit
    }));
    return [{ id: '', label: 'Tất cả nhân sự' }, ...opts];
  }, [users]);

  const stats = useMemo(() => {
    const filtered = tasks.filter(t => {
      const creator = users.find(u => u.id === t.userId);
      const lead = users.find(u => u.id === t.leadId);
      if (!creator && !lead) return false;

      const canSee = isGlobalAdmin || (t.unit === currentUser.unit);
      if (!canSee) return false;

      const matchesStaff = selectedStaffId 
        ? (t.userId === selectedStaffId || t.leadId === selectedStaffId || t.collaboratorIds.includes(selectedStaffId)) 
        : true;

      const taskTime = t.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesStaff && matchesStart && matchesEnd;
    });

    const todoTasks = filtered.filter(t => t.status === TaskStatus.TO_DO);
    const inProgressTasks = filtered.filter(t => t.status === TaskStatus.IN_PROGRESS);
    const completedTasks = filtered.filter(t => t.status === TaskStatus.COMPLETED);

    const performanceData = accessibleUsers
      .filter(u => !u.position.toLowerCase().includes('trưởng phòng') && !u.position.toLowerCase().includes('phó trưởng phòng'))
      .map(u => {
        const assignedCount = filtered.filter(t => t.userId === u.id).length;
        const assignPoints = assignedCount * 1;
        const leadTasks = filtered.filter(t => t.leadId === u.id && t.status === TaskStatus.COMPLETED);
        const collabTasks = filtered.filter(t => t.collaboratorIds.includes(u.id) && t.status === TaskStatus.COMPLETED);
        const completionPoints = [...leadTasks, ...collabTasks].reduce((acc, t) => acc + getPoints(t.complexity), 0);

        return {
          name: u.name,
          score: assignPoints + completionPoints,
          count: assignedCount + leadTasks.length + collabTasks.length
        };
      })
      .sort((a, b) => b.score - a.score);

    const complexityChartData = [
      { name: TaskComplexity.MEDIUM, value: filtered.filter(t => t.complexity === TaskComplexity.MEDIUM).length },
      { name: TaskComplexity.HARD, value: filtered.filter(t => t.complexity === TaskComplexity.HARD).length },
      { name: TaskComplexity.VERY_HARD, value: filtered.filter(t => t.complexity === TaskComplexity.VERY_HARD).length },
    ];

    return {
      total: filtered,
      todo: todoTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      complexityChartData,
      performanceData
    };
  }, [tasks, users, currentUser, isGlobalAdmin, startDate, endDate, selectedStaffId, accessibleUsers]);

  const COLORS = ['#6366f1', '#f59e0b', '#ef4444'];

  const openDetails = (title: string, taskList: Task[]) => {
    setDetailModal({ isOpen: true, title, tasks: taskList });
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="bg-white p-4 md:p-5 rounded-[2rem] border border-slate-200 shadow-sm flex flex-col md:flex-row items-end gap-4">
        {isGlobalAdmin && (
          <div className="w-full md:w-64">
             <SearchableSelect
              label="Lọc theo nhân sự"
              options={staffOptions}
              value={selectedStaffId}
              onChange={setSelectedStaffId}
              placeholder="Tất cả nhân sự"
            />
          </div>
        )}

        <div className={`flex flex-col sm:flex-row gap-3 w-full ${isGlobalAdmin ? 'md:max-w-md' : 'flex-1'}`}>
          <SmartDateInput label="Từ ngày" value={startDate} onChange={setStartDate} />
          <SmartDateInput label="Đến ngày" value={endDate} onChange={setEndDate} />
        </div>

        <button 
          onClick={() => { setStartDate(''); setEndDate(''); setSelectedStaffId(''); }}
          className="w-full md:w-auto bg-slate-50 text-slate-500 px-6 py-2.5 rounded-xl hover:bg-slate-100 transition-colors text-xs font-black uppercase tracking-widest border border-slate-200"
        >
          Xóa lọc
        </button>
      </div>

      <div className="grid grid-cols-2 lg:grid-cols-4 gap-4">
        {[
          { label: 'Tổng số', count: stats.total.length, icon: List, color: 'indigo', list: stats.total },
          { label: 'Cần làm', count: stats.todo.length, icon: Target, color: 'slate', list: stats.todo },
          { label: 'Đang xử lý', count: stats.inProgress.length, icon: Clock, color: 'amber', list: stats.inProgress },
          { label: 'Hoàn thành', count: stats.completed.length, icon: CheckCircle2, color: 'emerald', list: stats.completed },
        ].map((item, idx) => {
          const Icon = item.icon;
          return (
            <button
              key={idx}
              onClick={() => openDetails(item.label, item.list)}
              className="bg-white p-4 md:p-6 rounded-2xl md:rounded-3xl border border-slate-200 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all group text-left relative overflow-hidden"
            >
              <div className="flex flex-col md:flex-row md:items-center justify-between relative z-10 gap-2">
                <div>
                  <p className="text-[9px] md:text-[10px] font-black text-slate-400 uppercase tracking-widest mb-1">{item.label}</p>
                  <p className="text-xl md:text-3xl font-black text-slate-800 tracking-tighter leading-none">{item.count}</p>
                </div>
                <div className={`w-8 h-8 md:w-12 md:h-12 bg-${item.color}-50 text-${item.color}-600 rounded-lg md:rounded-xl flex items-center justify-center shrink-0`}>
                  <Icon size={window.innerWidth < 768 ? 16 : 24} />
                </div>
              </div>
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        {isGlobalAdmin && (
          <div className="bg-white p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
            <h3 className="text-xs md:text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center">
              <Trophy className="mr-2 text-amber-500" size={18} />
              Bảng xếp hạng hiệu suất
            </h3>
            <div className="h-[300px] md:h-[400px]">
              <ResponsiveContainer width="100%" height="100%">
                <BarChart data={stats.performanceData} layout="vertical" margin={{ left: 0, right: 30, top: 0, bottom: 20 }}>
                  <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                  <XAxis type="number" hide />
                  <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={70} fontSize={10} fontWeight="700" />
                  <Tooltip 
                    cursor={{ fill: '#f8fafc' }}
                    content={({ active, payload }) => {
                      if (active && payload && payload.length) {
                        const data = payload[0].payload;
                        return (
