                            <p className="font-bold border-b border-white/10 pb-1 mb-1">{data.name}</p>
                            <p className="text-indigo-300 font-bold">Điểm tổng: {data.score}</p>
                          </div>
                        );
                      }
                      return null;
                    }}
                  />
                  <Bar dataKey="score" fill="#6366f1" radius={[0, 8, 8, 0]} barSize={window.innerWidth < 768 ? 16 : 24} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </div>
        )}

        <div className="bg-white p-5 md:p-6 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-xs md:text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center">
            <Target className="mr-2 text-indigo-500" size={18} />
            Độ phức tạp công việc
          </h3>
          <div className="h-[300px] md:h-[400px]">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie 
                  data={stats.complexityChartData} 
                  cx="50%" 
                  cy="50%" 
                  innerRadius={window.innerWidth < 768 ? 55 : 80} 
                  outerRadius={window.innerWidth < 768 ? 85 : 120} 
                  paddingAngle={8} 
                  dataKey="value"
                  stroke="none"
                >
                  {stats.complexityChartData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
                <Legend iconType="circle" verticalAlign="bottom" wrapperStyle={{ fontSize: '10px', fontWeight: 'bold', paddingTop: '10px', textTransform: 'uppercase' }} />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {/* Detail Modal - Mobile Bottom Sheet Optimized */}
      {detailModal.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-end md:items-center justify-center p-0 md:p-4 animate-in fade-in duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDetailModal({ ...detailModal, isOpen: false })}></div>
          <div className="bg-white w-full max-w-4xl rounded-t-[2.5rem] md:rounded-[3rem] shadow-2xl relative z-10 overflow-hidden flex flex-col h-[85vh] md:h-auto md:max-h-[85vh] animate-in slide-in-from-bottom duration-500">
            {/* Mobile Handle */}
            <div className="md:hidden flex justify-center py-4 bg-slate-50 border-b border-slate-100 shrink-0">
               <div className="w-12 h-1.5 bg-slate-300 rounded-full"></div>
            </div>

            <div className="p-6 md:p-8 border-b border-slate-100 flex items-center justify-between bg-slate-50 sticky top-0 z-20">
              <div className="pr-4">
                <h2 className="text-xl md:text-2xl font-black text-slate-800 uppercase tracking-tighter truncate leading-tight">{detailModal.title}</h2>
                <p className="text-slate-500 text-xs font-bold uppercase tracking-widest mt-0.5">{detailModal.tasks.length} nhiệm vụ</p>
