  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus 
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getStickyClass = (status: TaskStatus) => {
    switch (status) {
      case TaskStatus.TO_DO: return 'bg-[#fff9c4] border-[#fbc02d]';
      case TaskStatus.IN_PROGRESS: return 'bg-[#e3f2fd] border-[#64b5f6]';
      case TaskStatus.COMPLETED: return 'bg-[#fce4ec] border-[#f06292]';
      default: return 'bg-white';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-xl shadow-2xl border-2 border-indigo-600 mb-4 z-50">
        <textarea
          autoFocus
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px] text-sm font-medium"
        />
        <div className="mt-3 flex items-center justify-between">
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 outline-none text-xs font-bold"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="bg-indigo-600 text-white p-2 rounded-lg"><Check size={16} /></button>
            <button onClick={() => setEditingTaskId(null)} className="bg-slate-100 text-slate-400 p-2 rounded-lg"><X size={16} /></button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      draggable
      onDragStart={(e) => {
        e.dataTransfer.setData('taskId', task.id);
        e.dataTransfer.setData('sourceStatus', task.status);
      }}
      className={`relative p-4 md:p-5 shadow-sm border rounded-xl mb-4 group transition-all hover:shadow-md ${getStickyClass(task.status)}`}
    >
      <div className="flex justify-between items-start mb-2">
        <span className={`text-[8px] font-black px-1.5 py-0.5 rounded uppercase ${
          task.complexity === TaskComplexity.VERY_HARD ? 'bg-red-500 text-white' : 'bg-indigo-500 text-white'
        }`}>{task.complexity}</span>
        <div className="flex items-center space-x-2 opacity-100 sm:opacity-0 sm:group-hover:opacity-100 transition-opacity">
          <button onClick={() => handleStartEdit(task)} className="p-1 text-slate-400 hover:text-indigo-600"><Edit2 size={14} /></button>
          <button onClick={() => onDeleteTask(task.id)} className="p-1 text-slate-400 hover:text-rose-600"><Trash2 size={14} /></button>
        </div>
      </div>
      <p className="font-semibold text-slate-800 leading-tight mb-4 text-sm break-words">{task.content}</p>
      <div className="flex items-center justify-between pt-2 border-t border-black/5">
        <div className="flex items-center text-[10px] font-bold text-slate-500 uppercase">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.COMPLETED ? formatDuration((task.completedTime || 0) - task.startTime) : formatDuration(now - task.startTime)}
        </div>
        <div className="flex space-x-2">
          {task.status === TaskStatus.TO_DO && <button onClick={() => onUpdateStatus(task.id, TaskStatus.IN_PROGRESS)} className="text-indigo-600"><PlayCircle size={20} /></button>}
          {task.status === TaskStatus.IN_PROGRESS && <button onClick={() => onUpdateStatus(task.id, TaskStatus.COMPLETED)} className="text-emerald-600"><CheckCircle2 size={20} /></button>}
        </div>
      </div>
    </div>
  );
};

