const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
  onViewAttachment: (att: Attachment) => void;
  onDragStart: (e: React.DragEvent, taskId: string) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus, onViewAttachment,
  onDragStart
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (comp: TaskComplexity) => {
    switch (comp) {
      case TaskComplexity.VERY_HARD: return 'bg-rose-100 text-rose-700 border-rose-200';
      case TaskComplexity.HARD: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-sky-100 text-sky-700 border-sky-200';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-2xl shadow-xl border-2 border-indigo-500 mb-4 animate-in zoom-in-95">
        <textarea
          autoFocus
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px] text-sm font-medium"
        />
        <div className="mt-3 flex items-center justify-between">
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 outline-none text-xs font-bold"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700"><Check size={16} /></button>
            <button onClick={() => setEditingTaskId(null)} className="bg-slate-100 text-slate-400 p-2 rounded-lg hover:bg-slate-200"><X size={16} /></button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      draggable 
      onDragStart={(e) => onDragStart(e, task.id)}
      className="bg-white p-4 md:p-5 shadow-sm border border-slate-200 rounded-2xl mb-4 group hover:border-indigo-300 transition-all hover:shadow-md cursor-grab active:cursor-grabbing relative overflow-hidden"
    >
      <div className="absolute left-0 top-0 bottom-0 w-1 bg-slate-100 group-hover:bg-indigo-400 transition-colors"></div>

      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center space-x-2">
          <GripVertical size={14} className="text-slate-300 group-hover:text-slate-400" />
          <span className={`text-[9px] font-black px-2 py-0.5 rounded-md uppercase border ${getComplexityColor(task.complexity)}`}>
            {task.complexity}
          </span>
        </div>
        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            type="button"
            onClick={(e) => { e.stopPropagation(); handleStartEdit(task); }} 
            className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
          >
            <Edit2 size={14} />
          </button>
          <button 
            type="button"
            onClick={(e) => { e.stopPropagation(); onDeleteTask(task.id); }} 
            className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      <p className="font-bold text-slate-700 leading-snug mb-2 text-sm pl-4">{task.content}</p>

      {task.attachments && task.attachments.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-4 pl-4">
          {task.attachments.map((att, i) => (
            <button 
              key={i} 
              type="button"
              onClick={(e) => { e.stopPropagation(); onViewAttachment(att); }}
              className="p-1.5 bg-slate-50 border border-slate-100 rounded-md hover:bg-indigo-50 transition-colors"
              title={att.name}
            >
              <Paperclip size={10} className="text-slate-400" />
            </button>
          ))}
        </div>
      )}

      <div className="flex items-center justify-between pt-3 border-t border-slate-50 pl-4">
        <div className="flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-tight">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.COMPLETED 
            ? formatDuration((task.completedTime || 0) - task.startTime) 
            : formatDuration(now - task.startTime)}
        </div>
        <div className="flex space-x-2">
          {task.status === TaskStatus.TO_DO && (
            <button type="button" onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.IN_PROGRESS); }} className="text-indigo-600 hover:scale-110 transition-transform">
              <PlayCircle size={22} />
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button type="button" onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.COMPLETED); }} className="text-emerald-600 hover:scale-110 transition-transform">
              <CheckCircle2 size={22} />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [newAttachments, setNewAttachments] = useState<Attachment[]>([]);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [searchTerm, setSearchTerm] = useState('');
  const [now, setNow] = useState(Date.now());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [viewerAtt, setViewerAtt] = useState<Attachment | null>(null);
  const [dragOverStatus, setDragOverStatus] = useState<TaskStatus | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredTasks = useMemo(() => 
    tasks.filter(t => t.content.toLowerCase().includes(searchTerm.toLowerCase())), 
    [tasks, searchTerm]
  );

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;

    if (newAttachments.length + files.length > 5) {
      alert("Chỉ được phép đính kèm tối đa 5 tệp.");
      return;
    }

    const loaders = (Array.from(files) as File[]).map(file => {
      return new Promise<Attachment>((resolve) => {
        const reader = new FileReader();
        reader.onload = (ev) => {
          resolve({
            name: file.name,
            type: file.type,
            data: ev.target?.result as string
          });
        };
        reader.readAsDataURL(file);
      });
    });

    const newAtts = await Promise.all(loaders);
    setNewAttachments([...newAttachments, ...newAtts]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const removeNewAttachment = (index: number) => {
    setNewAttachments(prev => prev.filter((_, i) => i !== index));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity, undefined, undefined, newAttachments);
      setNewContent('');
      setNewAttachments([]);
    }
  };

  const handleSaveEdit = () => {
    if (editingTaskId && editContent.trim()) {
      onUpdateTask(editingTaskId, { content: editContent.trim(), complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  const handleStartEdit = (t: Task) => {
    setEditingTaskId(t.id);
    setEditContent(t.content);
    setEditComplexity(t.complexity);
  };

  // Drag and Drop Logic
  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData('taskId', taskId);
    e.dataTransfer.effectAllowed = 'move';
  };

  const handleDragOver = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    setDragOverStatus(status);
  };

  const handleDrop = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    if (taskId) {
      onUpdateStatus(taskId, status);
    }
    setDragOverStatus(null);
  };

  const columns = [
    { title: "Cần làm", status: TaskStatus.TO_DO, color: "text-slate-500", bg: "bg-slate-100/50" },
    { title: "Đang làm", status: TaskStatus.IN_PROGRESS, color: "text-indigo-600", bg: "bg-indigo-50/50" },
    { title: "Hoàn thành", status: TaskStatus.COMPLETED, color: "text-emerald-600", bg: "bg-emerald-50/50" }
  ];

  return (
    <div className="space-y-6">
      <div className="bg-white p-4 md:p-6 rounded-3xl shadow-sm border border-slate-200">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col md:flex-row gap-4">
            <div className="flex-1">
              <input
                type="text"
                value={newContent}
                onChange={(e) => setNewContent(e.target.value)}
                placeholder="Thêm nhiệm vụ mới..."
                className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-medium"
              />
            </div>
            <div className="flex gap-2">
              <select
                value={newComplexity}
                onChange={(e) => setNewComplexity(e.target.value as TaskComplexity)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none text-xs font-bold uppercase tracking-widest"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
              <button 
                type="button"
                onClick={() => fileInputRef.current?.click()}
                className="bg-slate-100 text-slate-500 p-3 rounded-2xl hover:bg-slate-200 transition-all flex items-center justify-center border border-slate-200"
                title="Đính kèm tệp"
              >
                <Paperclip size={20} />
              </button>
              <button type="submit" className="bg-indigo-600 text-white p-3 rounded-2xl hover:bg-indigo-700 transition-all flex items-center justify-center shadow-lg shadow-indigo-100">
                <Plus size={24} />
              </button>
            </div>
          </div>

          <input 
            type="file" 
            ref={fileInputRef} 
            onChange={handleFileChange} 
            className="hidden" 
            multiple 
            accept="image/*,application/pdf"
          />

          <AttachmentPreview 
            attachments={newAttachments} 
            onRemove={removeNewAttachment} 
            onView={(att) => setViewerAtt(att)}
          />
        </form>

        <div className="mt-6 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Tìm kiếm công việc..."
            className="w-full bg-slate-50/50 border border-slate-100 rounded-xl pl-12 pr-4 py-2.5 text-xs font-medium outline-none focus:bg-white transition-all"
          />
        </div>
      </div>

      <div className="flex flex-col md:flex-row gap-6 h-full overflow-x-auto pb-6 snap-x snap-mandatory hide-scrollbar min-h-[500px]">
        {columns.map(col => (
          <div 
            key={col.status} 
            onDragOver={(e) => handleDragOver(e, col.status)}
            onDragLeave={() => setDragOverStatus(null)}
            onDrop={(e) => handleDrop(e, col.status)}
            className={`flex-shrink-0 w-full md:w-1/3 min-w-[300px] snap-center rounded-[2rem] p-4 flex flex-col h-full border transition-all duration-300 ${
              dragOverStatus === col.status 
              ? 'bg-indigo-100/50 border-indigo-400 border-2 border-dashed scale-[1.01]' 
              : 'bg-slate-100/30 border-slate-100 border-transparent'
            }`}
          >
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className={`text-sm font-black uppercase tracking-widest ${col.color}`}>{col.title}</h3>
              <span className="bg-white px-2.5 py-1 rounded-lg text-[10px] font-black text-slate-400 border border-slate-200 shadow-sm">
                {filteredTasks.filter(t => t.status === col.status).length}
              </span>
            </div>
            <div className="flex-1 space-y-1 min-h-[200px]">
              {filteredTasks.filter(t => t.status === col.status).map(task => (
                <TaskCard 
                  key={task.id} 
                  task={task} 
                  now={now}
                  editingTaskId={editingTaskId}
                  editContent={editContent}
                  editComplexity={editComplexity}
                  setEditContent={setEditContent}
                  setEditComplexity={setEditComplexity}
                  handleSaveEdit={handleSaveEdit}
                  setEditingTaskId={setEditingTaskId}
                  handleStartEdit={handleStartEdit}
                  onDeleteTask={onDeleteTask}
                  onUpdateStatus={onUpdateStatus}
                  onViewAttachment={(att) => setViewerAtt(att)}
                  onDragStart={handleDragStart}
                />
              ))}
              {filteredTasks.filter(t => t.status === col.status).length === 0 && (
                <div className="py-12 text-center text-slate-300 border-2 border-dashed border-slate-200 rounded-3xl uppercase text-[10px] font-black tracking-widest">
                  Trống
                </div>
              )}
            </div>
          </div>
        ))}
      </div>

      {/* Tệp đính kèm Viewer Modal */}
      {viewerAtt && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden relative flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-white sticky top-0 z-10">
              <h2 className="text-lg font-black text-slate-800 uppercase truncate pr-4">{viewerAtt.name}</h2>
              <button type="button" onClick={() => setViewerAtt(null)} className="p-2 hover:bg-slate-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-auto p-4 flex items-center justify-center bg-slate-50">
              {viewerAtt.type.startsWith('image/') ? (
                <img src={viewerAtt.data} alt={viewerAtt.name} className="max-w-full max-h-full object-contain shadow-lg rounded-lg" />
              ) : (
                <div className="text-center py-20">
                  <FileText size={80} className="mx-auto text-indigo-200 mb-6" />
                  <p className="text-slate-500 font-bold mb-6 text-lg tracking-tight">Tài liệu không thể xem trực tiếp</p>
                  <a 
                    href={viewerAtt.data} 
                    download={viewerAtt.name}
                    className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-black uppercase text-sm tracking-widest hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100"
                  >
                    Tải về máy
                  </a>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;

export enum TaskStatus {
  TO_DO = 'Cần làm',
  IN_PROGRESS = 'Đang làm',
  COMPLETED = 'Hoàn thành'
}

export enum TaskComplexity {
  MEDIUM = 'Trung bình',
  HARD = 'Khó',
  VERY_HARD = 'Rất khó'
}

export enum Gender {
  MALE = 'Nam',
  FEMALE = 'Nữ'
}

export interface Attachment {
  name: string;
  type: string;
  data: string; // Base64 string
}

export interface User {
  id: string;
  name: string;        // Cột A
  position: string;    // Cột B
  unit: string;        // Cột C
  gender: Gender;      // Cột D
  dob: string;         // Cột E
  phone: string;       // Cột F
  email: string;       // G
  password: string;    
  delegateLevel: string; // H
  notes: string;       // I
  mustChangePassword: boolean;
}

export interface Task {
  id: string;
  userId: string;
  content: string;
  startTime: number;
  completedTime?: number;
  status: TaskStatus;
  complexity: TaskComplexity;
  leadId: string;
  collaboratorIds: string[];
  unit: string;
  attachments?: Attachment[];
}

export interface DashboardStats {
  totalTasks: number;
  completedTasks: number;
  inProgressTasks: number;
  tasksByUnit: Record<string, number>;
}

import React, { useState, useEffect, useRef } from 'react';
import { User, Task, TaskStatus, TaskComplexity, Attachment } from './types';
import { INITIAL_USERS, INITIAL_TASKS } from './constants';
import { Menu, Loader2, RefreshCw } from 'lucide-react';
import { cloudStorage } from './storage';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import ImportData from './components/ImportData';
import UserProfile from './components/UserProfile';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>(INITIAL_USERS);
  const [tasks, setTasks] = useState<Task[]>(INITIAL_TASKS);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  const initialLoadDone = useRef(false);

  useEffect(() => {
    const initData = async () => {
      try {
        const [cloudUsers, cloudTasks] = await Promise.all([
          cloudStorage.get<User[]>('gdt_users', INITIAL_USERS),
          cloudStorage.get<Task[]>('gdt_tasks', INITIAL_TASKS)
        ]);

        setUsers(cloudUsers);
        setTasks(cloudTasks);

        const savedUser = localStorage.getItem('tm_current_user');
        if (savedUser) {
          const parsedUser = JSON.parse(savedUser);
          const stillExists = cloudUsers.find(u => u.id === parsedUser.id);
          if (stillExists) setCurrentUser(stillExists);
        }
      } catch (err) {
        console.error("Failed to load initial data", err);
      } finally {
        setIsInitialLoading(false);
        initialLoadDone.current = true;
      }
    };
    initData();
  }, []);

  useEffect(() => {
    if (!initialLoadDone.current) return;

    const sync = async () => {
      setIsSyncing(true);
      await Promise.all([
        cloudStorage.set('gdt_users', users),
        cloudStorage.set('gdt_tasks', tasks)
      ]);
      setIsSyncing(false);
    };

    const timer = setTimeout(sync, 1000);
    return () => clearTimeout(timer);
  }, [users, tasks]);

  useEffect(() => {
    if (currentUser) {
      localStorage.setItem('tm_current_user', JSON.stringify(currentUser));
    } else {
      localStorage.removeItem('tm_current_user');
    }
  }, [currentUser]);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    if (!user.mustChangePassword) {
      setActiveTab('dashboard');
    }
  };

  const handleLogout = () => {
    setCurrentUser(null);
    setActiveTab('dashboard');
    setViewedUserId(null);
    setIsSidebarOpen(false);
  };

  const handleChangePassword = (newPass: string) => {
    if (!currentUser) return;
    const updatedUser = { ...currentUser, password: newPass, mustChangePassword: false };
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updatedUser : u));
    setCurrentUser(updatedUser);
  };

  const handleResetPassword = (email: string, newPass: string) => {
    setUsers(prev => prev.map(u => u.email.toLowerCase() === email.toLowerCase() ? { ...u, password: newPass, mustChangePassword: false } : u));
  };

  const addTask = (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[]) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, 
      complexity: complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit,
      attachments: attachments || []
    };
    setTasks(prev => [newTask, ...prev]);
  };

  const updateTaskStatus = (taskId: string, newStatus: TaskStatus) => {
    setTasks(prev => prev.map(t => {
      if (t.id === taskId) {
        return {
          ...t,
          status: newStatus,
          completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : t.completedTime,
          startTime: (newStatus === TaskStatus.IN_PROGRESS && t.status === TaskStatus.TO_DO) ? Date.now() : t.startTime
        };
      }
      return t;
    }));
  };

  const updateTask = (taskId: string, updates: Partial<Task>) => {
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
  };

  const deleteTask = (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setTasks(prev => prev.filter(t => t.id !== taskId));
    }
  };

  const handleImport = (newUsers: User[]) => {
    setUsers(newUsers);
    alert('Dữ liệu đã được cập nhật thành công!');
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs text-center px-4">Đang đồng bộ dữ liệu đám mây...</p>
      </div>
    );
  }

  if (!currentUser) {
    return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  }

  if (currentUser.mustChangePassword) {
    return <ChangePassword onComplete={handleChangePassword} />;
  }

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => {
          setActiveTab(tab);
          setIsSidebarOpen(false);
        }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-black text-lg">Q</div>
          <span className="font-black text-slate-800 uppercase tracking-tight text-sm">Quản lý GDT</span>
        </div>
        <div className="flex items-center space-x-2">
          {isSyncing && <RefreshCw className="text-indigo-400 animate-spin" size={18} />}
          <button 
            onClick={() => setIsSidebarOpen(true)}
            className="p-2 text-slate-500 hover:bg-slate-100 rounded-xl transition-all active:scale-95"
          >
            <Menu size={24} />
          </button>
        </div>
      </div>

      <main className="flex-1 p-4 md:p-8 lg:p-10 max-w-full">
        <header className="mb-6 md:mb-10 flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4">
          <div className="animate-in slide-in-from-left duration-500">
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3">
              {activeTab === 'dashboard' && 'Tổng quan'}
              {activeTab === 'tasks' && 'Việc của tôi'}
              {activeTab === 'search' && 'Báo cáo & Tra cứu'}
              {activeTab === 'delegate' && 'Giao nhiệm vụ'}
              {activeTab === 'import' && 'Nhập dữ liệu'}
              {activeTab === 'profile' && 'Cá nhân'}
              {isSyncing && <RefreshCw className="text-indigo-400 animate-spin hidden md:block" size={24} />}
            </h1>
            <p className="text-slate-500 text-sm font-medium mt-1">
              Đơn vị: <span className="text-indigo-600 font-bold">{currentUser.unit}</span>
            </p>
          </div>
          <div className="hidden sm:flex items-center space-x-3 bg-white p-2 rounded-2xl border border-slate-200 shadow-sm">
             <div className="w-10 h-10 rounded-xl bg-indigo-50 flex items-center justify-center text-indigo-600 font-black">
                {currentUser.name.charAt(0)}
             </div>
             <div className="pr-4">
               <p className="text-xs font-black text-slate-800 uppercase leading-none">{currentUser.name}</p>
               <p className="text-[10px] text-slate-400 font-bold uppercase mt-1 tracking-wider">{currentUser.position}</p>
             </div>
          </div>
        </header>

        <div className="w-full animate-in fade-in duration-700">
          {activeTab === 'dashboard' && (
            <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => {
              setViewedUserId(uid);
              setActiveTab('search');
            }} />
          )}

          {activeTab === 'tasks' && (
            <TaskBoard 
              tasks={tasks.filter(t => t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id))} 
              onAddTask={addTask}
              onUpdateStatus={updateTaskStatus}
              onUpdateTask={updateTask}
              onDeleteTask={deleteTask}
            />
          )}

          {activeTab === 'search' && (
            <AdminSearch 
              users={users} 
              tasks={tasks} 
              isAdmin={isAdmin}
              currentUser={currentUser}
              onUpdateTask={updateTask}
              onResetUserPassword={handleResetPassword}
              initialSelectedUserId={viewedUserId}
            />
          )}

          {activeTab === 'delegate' && (
            <Delegation 
              currentUser={currentUser} 
              users={users} 
              onAssign={addTask}
            />
          )}

          {activeTab === 'import' && (
            <ImportData currentUser={currentUser} onImport={handleImport} />
          )}

          {activeTab === 'profile' && (
            <UserProfile user={currentUser} />
          )}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Task, TaskStatus, TaskComplexity, Attachment } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, Search, X, Check, Paperclip, FileText, Image as ImageIcon, Eye, GripVertical } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[]) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
  onViewAttachment: (att: Attachment) => void;
  onDragStart: (e: React.DragEvent, taskId: string) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus, onViewAttachment,
  onDragStart
}) => {
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (comp: TaskComplexity) => {
    switch (comp) {
      case TaskComplexity.VERY_HARD: return 'bg-rose-100 text-rose-700 border-rose-200';
      case TaskComplexity.HARD: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-sky-100 text-sky-700 border-sky-200';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-2xl shadow-xl border-2 border-indigo-500 mb-4 animate-in zoom-in-95">
        <textarea
          autoFocus
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[120px] text-sm font-medium"
        />
        <div className="mt-3 flex items-center justify-between">
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 outline-none text-xs font-bold"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700"><Check size={16} /></button>
            <button onClick={() => setEditingTaskId(null)} className="bg-slate-100 text-slate-400 p-2 rounded-lg hover:bg-slate-200"><X size={16} /></button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      draggable 
      onDragStart={(e) => onDragStart(e, task.id)}
      className="bg-white p-4 md:p-5 shadow-sm border border-slate-200 rounded-2xl mb-4 group hover:border-indigo-300 transition-all hover:shadow-md cursor-grab active:cursor-grabbing relative"
    >
      <div className="flex justify-between items-start mb-3">
        <div className="flex items-center space-x-2">
          <GripVertical size={14} className="text-slate-300" />
          <span className={`text-[9px] font-black px-2 py-0.5 rounded-md uppercase border ${getComplexityColor(task.complexity)}`}>
            {task.complexity}
          </span>
        </div>
        <div className="flex items-center space-x-1 opacity-0 group-hover:opacity-100 transition-opacity">
          <button 
            type="button"
            onClick={(e) => { e.stopPropagation(); handleStartEdit(task); }} 
            className="p-1.5 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-lg transition-all"
          >
            <Edit2 size={14} />
          </button>
          <button 
            type="button"
            onClick={(e) => { e.stopPropagation(); onDeleteTask(task.id); }} 
            className="p-1.5 text-slate-400 hover:text-rose-600 hover:bg-rose-50 rounded-lg transition-all"
          >
            <Trash2 size={14} />
          </button>
        </div>
      </div>

      {/* Hiển thị đầy đủ nội dung, không cắt xén */}
      <p className="font-bold text-slate-700 leading-snug mb-3 text-sm whitespace-pre-wrap break-words">{task.content}</p>

      {task.attachments && task.attachments.length > 0 && (
        <div className="flex flex-wrap gap-1 mb-4">
          {task.attachments.map((att, i) => (
            <button 
              key={i} 
              type="button"
              onClick={(e) => { e.stopPropagation(); onViewAttachment(att); }}
              className="p-1.5 bg-slate-50 border border-slate-100 rounded-md hover:bg-indigo-50 transition-colors"
            >
              <Paperclip size={10} className="text-slate-400" />
            </button>
          ))}
        </div>
      )}

      <div className="flex items-center justify-between pt-3 border-t border-slate-50">
        <div className="flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-tight">
          <Clock size={12} className="mr-1" />
          {task.status === TaskStatus.COMPLETED 
            ? formatDuration((task.completedTime || 0) - task.startTime) 
            : formatDuration(now - task.startTime)}
        </div>
        <div className="flex space-x-2">
          {task.status === TaskStatus.TO_DO && (
            <button type="button" onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.IN_PROGRESS); }} className="text-indigo-600 hover:scale-110 transition-transform">
              <PlayCircle size={22} />
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button type="button" onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.COMPLETED); }} className="text-emerald-600 hover:scale-110 transition-transform">
              <CheckCircle2 size={22} />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

const TaskBoard: React.FC<TaskBoardProps> = ({ tasks, onAddTask, onUpdateStatus, onUpdateTask, onDeleteTask }) => {
  const [newContent, setNewContent] = useState('');
  const [newComplexity, setNewComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [newAttachments, setNewAttachments] = useState<Attachment[]>([]);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editContent, setEditContent] = useState('');
  const [editComplexity, setEditComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [searchTerm, setSearchTerm] = useState('');
  const [now, setNow] = useState(Date.now());
  const fileInputRef = useRef<HTMLInputElement>(null);
  const [viewerAtt, setViewerAtt] = useState<Attachment | null>(null);
  const [dragOverCol, setDragOverCol] = useState<TaskStatus | null>(null);

  useEffect(() => {
    const timer = setInterval(() => setNow(Date.now()), 1000);
    return () => clearInterval(timer);
  }, []);

  const filteredTasks = useMemo(() => 
    tasks.filter(t => t.content.toLowerCase().includes(searchTerm.toLowerCase())), 
    [tasks, searchTerm]
  );

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    if (newAttachments.length + files.length > 5) {
      alert("Tối đa 5 tệp đính kèm.");
      return;
    }
    const loaders = (Array.from(files) as File[]).map(file => {
      return new Promise<Attachment>((resolve) => {
        const reader = new FileReader();
        reader.onload = (ev) => resolve({ name: file.name, type: file.type, data: ev.target?.result as string });
        reader.readAsDataURL(file);
      });
    });
    const newAtts = await Promise.all(loaders);
    setNewAttachments([...newAttachments, ...newAtts]);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (newContent.trim()) {
      onAddTask(newContent.trim(), newComplexity, undefined, undefined, newAttachments);
      setNewContent('');
      setNewAttachments([]);
    }
  };

  const handleSaveEdit = () => {
    if (editingTaskId && editContent.trim()) {
      onUpdateTask(editingTaskId, { content: editContent.trim(), complexity: editComplexity });
      setEditingTaskId(null);
    }
  };

  // Drag and Drop Logic
  const handleDragStart = (e: React.DragEvent, taskId: string) => {
    e.dataTransfer.setData('taskId', taskId);
  };
  const handleDragOver = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    setDragOverCol(status);
  };
  const handleDrop = (e: React.DragEvent, status: TaskStatus) => {
    e.preventDefault();
    const taskId = e.dataTransfer.getData('taskId');
    onUpdateStatus(taskId, status);
    setDragOverCol(null);
  };

  const columns = [
    { title: "Cần làm", status: TaskStatus.TO_DO, color: "text-slate-500" },
    { title: "Đang làm", status: TaskStatus.IN_PROGRESS, color: "text-indigo-600" },
    { title: "Hoàn thành", status: TaskStatus.COMPLETED, color: "text-emerald-600" }
  ];

  return (
    <div className="space-y-6">
      <div className="bg-white p-4 md:p-6 rounded-3xl shadow-sm border border-slate-200">
        <form onSubmit={handleSubmit} className="space-y-4">
          <div className="flex flex-col md:flex-row gap-4">
            <input
              type="text"
              value={newContent}
              onChange={(e) => setNewContent(e.target.value)}
              placeholder="Thêm nhiệm vụ mới..."
              className="flex-1 bg-slate-50 border border-slate-200 rounded-2xl px-5 py-3 outline-none focus:ring-2 focus:ring-indigo-500 text-sm font-medium"
            />
            <div className="flex gap-2">
              <select
                value={newComplexity}
                onChange={(e) => setNewComplexity(e.target.value as TaskComplexity)}
                className="bg-slate-50 border border-slate-200 rounded-2xl px-4 py-3 outline-none text-xs font-bold"
              >
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
              <button 
                type="button" 
                onClick={() => fileInputRef.current?.click()}
                className="bg-slate-100 text-slate-500 p-3 rounded-2xl border border-slate-200 hover:bg-slate-200 transition-all"
              >
                <Paperclip size={20} />
              </button>
              <button type="submit" className="bg-indigo-600 text-white p-3 rounded-2xl hover:bg-indigo-700 transition-all shadow-lg shadow-indigo-100">
                <Plus size={24} />
              </button>
            </div>
          </div>
          <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" multiple accept="image/*,application/pdf" />

          {newAttachments.length > 0 && (
            <div className="flex flex-wrap gap-2">
              {newAttachments.map((att, idx) => (
                <div key={idx} className="bg-slate-100 px-2 py-1 rounded-lg text-[10px] font-bold flex items-center space-x-2 border border-slate-200">
                  <span className="truncate max-w-[100px]">{att.name}</span>
                  <button type="button" onClick={() => setNewAttachments(prev => prev.filter((_, i) => i !== idx))} className="text-rose-500"><X size={12} /></button>
                </div>
              ))}
            </div>
          )}
        </form>
        <div className="mt-4 relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300" size={16} />
          <input
            type="text"
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            placeholder="Tìm kiếm công việc..."
            className="w-full bg-slate-50/50 border border-slate-100 rounded-xl pl-12 pr-4 py-2.5 text-xs font-medium outline-none focus:bg-white transition-all"
          />
        </div>
      </div>

      {/* 
          MOBILE: flex-row + overflow-x-auto + snap-x (Vuốt ngang)
          DESKTOP: flex-row + gap-6
      */}
      <div className="flex flex-row overflow-x-auto gap-4 md:gap-6 pb-6 snap-x snap-mandatory hide-scrollbar min-h-[600px]">
        {columns.map(col => (
          <div 
            key={col.status} 
            onDragOver={(e) => handleDragOver(e, col.status)}
            onDragLeave={() => setDragOverCol(null)}
            onDrop={(e) => handleDrop(e, col.status)}
            className={`flex-shrink-0 w-[85vw] md:w-1/3 snap-center rounded-[2rem] p-4 flex flex-col h-full transition-all duration-300 ${
              dragOverCol === col.status ? 'bg-indigo-100/50 border-2 border-dashed border-indigo-400' : 'bg-slate-100/30 border border-slate-100'
            }`}
          >
            <div className="flex items-center justify-between mb-4 px-2">
              <h3 className={`text-sm font-black uppercase tracking-widest ${col.color}`}>{col.title}</h3>
              <span className="bg-white px-2.5 py-1 rounded-lg text-[10px] font-black text-slate-400 border border-slate-200">
                {filteredTasks.filter(t => t.status === col.status).length}
              </span>
            </div>
            <div className="flex-1 space-y-1 min-h-[200px]">
              {filteredTasks.filter(t => t.status === col.status).map(task => (
                <TaskCard 
                  key={task.id} 
                  task={task} 
                  now={now}
                  editingTaskId={editingTaskId}
                  editContent={editContent}
                  editComplexity={editComplexity}
                  setEditContent={setEditContent}
                  setEditComplexity={setEditComplexity}
                  handleSaveEdit={handleSaveEdit}
                  setEditingTaskId={setEditingTaskId}
                  handleStartEdit={(t) => { setEditingTaskId(t.id); setEditContent(t.content); setEditComplexity(t.complexity); }}
                  onDeleteTask={onDeleteTask}
                  onUpdateStatus={onUpdateStatus}
                  onViewAttachment={setViewerAtt}
                  onDragStart={handleDragStart}
                />
              ))}
            </div>
          </div>
        ))}
      </div>

      {viewerAtt && (
        <div className="fixed inset-0 z-[120] flex items-center justify-center p-4 bg-slate-900/80 backdrop-blur-sm">
          <div className="bg-white w-full max-w-4xl rounded-[2.5rem] shadow-2xl overflow-hidden relative flex flex-col max-h-[90vh]">
            <div className="p-6 border-b border-slate-100 flex items-center justify-between bg-white sticky top-0">
              <h2 className="text-lg font-black text-slate-800 uppercase truncate pr-4">{viewerAtt.name}</h2>
              <button type="button" onClick={() => setViewerAtt(null)} className="p-2 hover:bg-slate-50 rounded-xl transition-all"><X size={24} /></button>
            </div>
            <div className="flex-1 overflow-auto p-4 flex items-center justify-center bg-slate-50">
              {viewerAtt.type.startsWith('image/') ? (
                <img src={viewerAtt.data} alt={viewerAtt.name} className="max-w-full max-h-full object-contain shadow-lg rounded-lg" />
              ) : (
                <div className="text-center py-20">
                  <FileText size={80} className="mx-auto text-indigo-200 mb-6" />
                  <a href={viewerAtt.data} download={viewerAtt.name} className="bg-indigo-600 text-white px-8 py-3 rounded-2xl font-black uppercase text-sm tracking-widest shadow-lg">Tải về máy</a>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default TaskBoard;

import React, { useState, useMemo, useRef } from 'react';
import { User, TaskStatus, TaskComplexity, Attachment } from '../types';
import { Send, Users, UserPlus, AlertCircle, ShieldAlert, Paperclip, X } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

interface DelegationProps {
  currentUser: User;
  users: User[];
  onAssign: (content: string, complexity: TaskComplexity, leadId: string, collaboratorIds: string[], attachments?: Attachment[]) => void;
}

const Delegation: React.FC<DelegationProps> = ({ currentUser, users, onAssign }) => {
  const [content, setContent] = useState('');
  const [complexity, setComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [selectedUnit, setSelectedUnit] = useState(currentUser.unit);
  const [leadId, setLeadId] = useState('');
  const [collaboratorIds, setCollaboratorIds] = useState<string[]>([]);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const fileInputRef = useRef<HTMLInputElement>(null);

  const canDelegateTo = (targetLevel: string) => {
    const currRank = parseInt(currentUser.delegateLevel.replace(/\D/g, '')) || 99;
    const targetRank = parseInt(targetLevel.replace(/\D/g, '')) || 99;
    return targetRank > currRank;
  };

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);
  const targetEmployees = useMemo(() => users.filter(u => u.unit === selectedUnit && canDelegateTo(u.delegateLevel)), [selectedUnit, users, currentUser.delegateLevel]);
  const leadOptions = useMemo(() => targetEmployees.map(u => ({ id: u.id, label: u.name, subLabel: `${u.position} - ${u.delegateLevel}` })), [targetEmployees]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    if (attachments.length + files.length > 5) {
      alert("Tối đa 5 tệp.");
      return;
    }
    const loaders = Array.from(files).map(file => {
      return new Promise<Attachment>((resolve) => {
        const reader = new FileReader();
        reader.onload = (ev) => resolve({ name: file.name, type: file.type, data: ev.target?.result as string });
        reader.readAsDataURL(file);
      });
    });
    const newAtts = await Promise.all(loaders);
    setAttachments([...attachments, ...newAtts]);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || !leadId) {
      alert('Vui lòng nhập đầy đủ nội dung và chọn người chủ trì.');
      return;
    }
    onAssign(content, complexity, leadId, collaboratorIds, attachments);
    alert('Đã giao nhiệm vụ thành công!');
    setContent('');
    setLeadId('');
    setCollaboratorIds([]);
    setAttachments([]);
  };

  return (
    <div className="max-w-4xl mx-auto">
      <div className="bg-white rounded-3xl border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-8 bg-indigo-600 text-white relative overflow-hidden">
          <div className="relative z-10">
            <h2 className="text-2xl font-bold flex items-center space-x-3">
              <Send size={28} />
              <span>Giao nhiệm vụ công tác</span>
            </h2>
            <div className="flex items-center space-x-4 mt-3">
              <span className="bg-white/20 px-3 py-1 rounded-full text-xs font-bold backdrop-blur-sm">Cấp bậc: {currentUser.delegateLevel}</span>
            </div>
          </div>
          <Send className="absolute -right-4 -bottom-4 text-white/10 rotate-12" size={160} />
        </div>

        <form onSubmit={handleSubmit} className="p-6 md:p-10 space-y-8">
          <div>
            <label className="block text-sm font-bold text-slate-700 mb-3">Nội dung công việc</label>
            <textarea
              value={content}
              onChange={(e) => setContent(e.target.value)}
              placeholder="Nhập mô tả chi tiết nhiệm vụ..."
              rows={4}
              className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-2 focus:ring-indigo-500 shadow-inner"
            />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-3">Mức độ phức tạp</label>
              <select value={complexity} onChange={(e) => setComplexity(e.target.value as TaskComplexity)} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 font-semibold">
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <div>
              <label className="block text-sm font-bold text-slate-700 mb-3">Đơn vị tiếp nhận</label>
              <select value={selectedUnit} onChange={(e) => { setSelectedUnit(e.target.value); setLeadId(''); setCollaboratorIds([]); }} className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 font-semibold">
                {units.map(u => <option key={u} value={u}>{u}</option>)}
              </select>
            </div>
          </div>

          <div className="space-y-4">
            <div className="flex justify-between items-center">
              <label className="block text-sm font-bold text-slate-700">Tệp đính kèm (Tối đa 5)</label>
              <button type="button" onClick={() => fileInputRef.current?.click()} className="text-indigo-600 font-bold text-xs uppercase flex items-center space-x-1 hover:text-indigo-800">
                <Paperclip size={14} /> <span>Thêm file</span>
              </button>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" multiple accept="image/*,application/pdf" />
            <div className="flex flex-wrap gap-2">
              {attachments.map((att, i) => (
                <div key={i} className="bg-slate-50 border border-slate-200 p-2 rounded-xl flex items-center space-x-2 text-xs font-bold">
                  <span className="truncate max-w-[120px]">{att.name}</span>
                  <button type="button" onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="text-rose-500"><X size={14} /></button>
                </div>
              ))}
            </div>
          </div>

          <div className="space-y-4 pt-4 border-t border-slate-100">
            <label className="block text-sm font-bold text-slate-700">Lựa chọn nhân sự</label>
            {targetEmployees.length > 0 ? (
              <div className="space-y-6">
                <SearchableSelect label="Người chủ trì" options={leadOptions} value={leadId} onChange={setLeadId} placeholder="-- Chọn người chủ trì --" />
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 max-h-56 overflow-y-auto p-4 bg-slate-50 rounded-2xl border border-slate-100">
                  {targetEmployees.filter(u => u.id !== leadId).map(u => (
                    <button key={u.id} type="button" onClick={() => setCollaboratorIds(prev => prev.includes(u.id) ? prev.filter(i => i !== u.id) : [...prev, u.id])} className={`px-4 py-3 rounded-xl text-sm border font-medium transition-all ${collaboratorIds.includes(u.id) ? 'bg-indigo-600 border-indigo-600 text-white shadow-md' : 'bg-white border-slate-200 text-slate-600'}`}>
                      {u.name}
                    </button>
                  ))}
                </div>
              </div>
            ) : (
              <div className="p-8 bg-amber-50 border border-amber-100 rounded-3xl text-center">
                <ShieldAlert size={40} className="mx-auto text-amber-500 mb-3" />
                <p className="text-amber-800 font-bold">Không tìm thấy nhân sự phù hợp (Cấp bậc thấp hơn bạn)</p>
              </div>
            )}
          </div>

          <button type="submit" disabled={!leadId} className={`w-full py-5 rounded-2xl font-bold text-xl shadow-xl transition-all ${leadId ? 'bg-indigo-600 text-white hover:bg-indigo-700' : 'bg-slate-200 text-slate-400 cursor-not-allowed'}`}>
            Xác nhận giao nhiệm vụ
          </button>
        </form>
      </div>
    </div>
  );
};

