export const cloudStorage = {
  async getUsers(): Promise<any[]> {
    const { data, error } = await supabase.from('users').select('*');
    if (error) {
      console.error('Error fetching users:', error);
      return [];
    }
    return data || [];
  },

  async getTasks(): Promise<any[]> {
    const { data, error } = await supabase.from('tasks').select('*').order('startTime', { ascending: false });
    if (error) {
      console.error('Error fetching tasks:', error);
      return [];
    }
    return data || [];
  },

  async upsertUser(user: any) {
    const { error } = await supabase.from('users').upsert(user);
    if (error) console.error('Error upserting user:', error);
  },

  async insertTask(task: any) {
    const { error } = await supabase.from('tasks').insert(task);
    if (error) console.error('Error inserting task:', error);
  },

  async updateTask(taskId: string, updates: any) {
    const { error } = await supabase.from('tasks').update(updates).eq('id', taskId);
    if (error) console.error('Error updating task:', error);
  },

  async deleteTask(taskId: string) {
    const { error } = await supabase.from('tasks').delete().eq('id', taskId);
    if (error) console.error('Error deleting task:', error);
  }
};

import React, { useState, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity, Attachment } from './types';
import { INITIAL_USERS, INITIAL_TASKS } from './constants';
import { Menu, Loader2, RefreshCw } from 'lucide-react';
import { cloudStorage } from './storage';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import ImportData from './components/ImportData';
import UserProfile from './components/UserProfile';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const initData = async () => {
      try {
        const [dbUsers, dbTasks] = await Promise.all([
          cloudStorage.getUsers(),
          cloudStorage.getTasks()
        ]);

        if (dbUsers.length === 0) {
          for (const u of INITIAL_USERS) await cloudStorage.upsertUser(u);
          setUsers(INITIAL_USERS);
        } else {
          setUsers(dbUsers);
        }

        setTasks(dbTasks.length > 0 ? dbTasks : INITIAL_TASKS);

        const savedUserStr = localStorage.getItem('tm_current_user');
        if (savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          const stillExists = (dbUsers.length > 0 ? dbUsers : INITIAL_USERS).find(u => u.id === parsedUser.id);
          if (stillExists) setCurrentUser(stillExists);
        }
      } catch (err) {
        console.error("Supabase Error:", err);
      } finally {
        setIsInitialLoading(false);
      }
    };
    initData();
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('tm_current_user', JSON.stringify(user));
    if (!user.mustChangePassword) setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('tm_current_user');
    setActiveTab('dashboard');
    setIsSidebarOpen(false);
  };

  const handleChangePassword = async (newPass: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, password: newPass, mustChangePassword: false };
    setIsSyncing(true);
    await cloudStorage.upsertUser(updated);
    setUsers(prev => prev.map(u => u.id === currentUser.id ? updated : u));
    setCurrentUser(updated);
    setIsSyncing(false);
  };

  const handleResetPassword = async (email: string, newPass: string) => {
    const target = users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (target) {
      const updated = { ...target, password: newPass, mustChangePassword: false };
      setIsSyncing(true);
      await cloudStorage.upsertUser(updated);
      setUsers(prev => prev.map(u => u.email.toLowerCase() === email.toLowerCase() ? updated : u));
      setIsSyncing(false);
    }
  };

  const addTask = async (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[]) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, 
      complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit,
      attachments: attachments || []
    };
    setIsSyncing(true);
    await cloudStorage.insertTask(newTask);
    setTasks(prev => [newTask, ...prev]);
    setIsSyncing(false);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates = {
      status: newStatus,
      completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : task.completedTime,
      startTime: (newStatus === TaskStatus.IN_PROGRESS && task.status === TaskStatus.TO_DO) ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    await cloudStorage.updateTask(taskId, updates);
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setIsSyncing(true);
    await cloudStorage.updateTask(taskId, updates);
    setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const deleteTask = async (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setIsSyncing(true);
      await cloudStorage.deleteTask(taskId);
      setTasks(prev => prev.filter(t => t.id !== taskId));
      setIsSyncing(false);
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Kết nối Supabase Cloud...</p>
      </div>
    );
  }

  if (!currentUser) return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  if (currentUser.mustChangePassword) return <ChangePassword onComplete={handleChangePassword} />;

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setIsSidebarOpen(false); }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-black text-lg">Q</div>
          <span className="font-black text-slate-800 uppercase tracking-tight text-sm">Quản lý GDT</span>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500"><Menu size={24} /></button>
      </div>

      <main className="flex-1 p-4 md:p-8 lg:p-10 max-w-full">
        <header className="mb-6 md:mb-10 flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4">
          <div>
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3">
              {activeTab === 'dashboard' && 'Tổng quan'}
              {activeTab === 'tasks' && 'Việc của tôi'}
              {activeTab === 'search' && 'Báo cáo & Tra cứu'}
              {activeTab === 'delegate' && 'Giao nhiệm vụ'}
              {activeTab === 'import' && 'Nhập dữ liệu'}
              {activeTab === 'profile' && 'Cá nhân'}
              {isSyncing && <RefreshCw className="text-indigo-400 animate-spin" size={24} />}
            </h1>
            <p className="text-slate-500 text-sm font-medium mt-1 uppercase tracking-widest">Hệ thống: <span className="text-indigo-600 font-bold">Supabase</span></p>
          </div>
        </header>

        <div className="w-full">
          {activeTab === 'dashboard' && <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => { setViewedUserId(uid); setActiveTab('search'); }} />}
          {activeTab === 'tasks' && <TaskBoard tasks={tasks.filter(t => t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id))} onAddTask={addTask} onUpdateStatus={updateTaskStatus} onUpdateTask={updateTask} onDeleteTask={deleteTask} />}
          {activeTab === 'search' && <AdminSearch users={users} tasks={tasks} isAdmin={isAdmin} currentUser={currentUser} onUpdateTask={updateTask} onResetUserPassword={handleResetPassword} initialSelectedUserId={viewedUserId} />}
          {activeTab === 'delegate' && <Delegation currentUser={currentUser} users={users} onAssign={addTask} />}
          {activeTab === 'import' && <ImportData currentUser={currentUser} onImport={async (us) => { setIsSyncing(true); for (const u of us) await cloudStorage.upsertUser(u); setUsers(us); setIsSyncing(false); }} />}
          {activeTab === 'profile' && <UserProfile user={currentUser} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useState, useEffect, useMemo, useRef } from 'react';
import { Task, TaskStatus, TaskComplexity, Attachment } from '../types';
import { Clock, CheckCircle2, PlayCircle, Plus, Edit2, Trash2, Search, X, Check, Paperclip, FileText, Image as ImageIcon, Eye } from 'lucide-react';

interface TaskBoardProps {
  tasks: Task[];
  onAddTask: (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[]) => void;
  onUpdateStatus: (taskId: string, status: TaskStatus) => void;
  onUpdateTask: (taskId: string, updates: Partial<Task>) => void;
  onDeleteTask: (taskId: string) => void;
}

const TaskCard: React.FC<{ 
  task: Task; 
  now: number;
  editingTaskId: string | null;
  editContent: string;
  editComplexity: TaskComplexity;
  setEditContent: (v: string) => void;
  setEditComplexity: (v: TaskComplexity) => void;
  handleSaveEdit: () => void;
  setEditingTaskId: (v: string | null) => void;
  handleStartEdit: (t: Task) => void;
  onDeleteTask: (id: string) => void;
  onUpdateStatus: (id: string, s: TaskStatus) => void;
  onViewAttachment: (att: Attachment) => void;
  onDragStart: (e: React.DragEvent, taskId: string) => void;
}> = ({ 
  task, now, editingTaskId, editContent, editComplexity, 
  setEditContent, setEditComplexity, handleSaveEdit, 
  setEditingTaskId, handleStartEdit, onDeleteTask, onUpdateStatus, onViewAttachment,
  onDragStart
}) => {
  const [isDraggable, setIsDraggable] = useState(true);
  const isEditing = editingTaskId === task.id;

  const formatDuration = (ms: number) => {
    const seconds = Math.floor(ms / 1000);
    const minutes = Math.floor(seconds / 60);
    const hours = Math.floor(minutes / 60);
    if (hours > 0) return `${hours}h ${minutes % 60}m`;
    if (minutes > 0) return `${minutes}m ${seconds % 60}s`;
    return `${seconds}s`;
  };

  const getComplexityColor = (comp: TaskComplexity) => {
    switch (comp) {
      case TaskComplexity.VERY_HARD: return 'bg-rose-100 text-rose-700 border-rose-200';
      case TaskComplexity.HARD: return 'bg-amber-100 text-amber-700 border-amber-200';
      default: return 'bg-sky-100 text-sky-700 border-sky-200';
    }
  };

  if (isEditing) {
    return (
      <div className="bg-white p-4 rounded-2xl shadow-xl border-2 border-indigo-500 mb-4 animate-in zoom-in-95">
        <textarea
          autoFocus
          value={editContent}
          onChange={(e) => setEditContent(e.target.value)}
          className="w-full bg-slate-50 border border-slate-200 rounded-xl px-3 py-2 outline-none focus:ring-2 focus:ring-indigo-500 min-h-[80px] text-sm font-medium"
        />
        <div className="mt-3 flex items-center justify-between">
          <select
            value={editComplexity}
            onChange={(e) => setEditComplexity(e.target.value as TaskComplexity)}
            className="bg-slate-50 border border-slate-200 rounded-lg px-2 py-1 outline-none text-xs font-bold"
          >
            {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
          </select>
          <div className="flex space-x-2">
            <button onClick={handleSaveEdit} className="bg-indigo-600 text-white p-2 rounded-lg hover:bg-indigo-700 transition-all active:scale-90"><Check size={16} /></button>
            <button onClick={() => setEditingTaskId(null)} className="bg-slate-100 text-slate-400 p-2 rounded-lg hover:bg-slate-200 transition-all"><X size={16} /></button>
          </div>
        </div>
      </div>
    );
  }

  return (
    <div 
      draggable={isDraggable} 
      onDragStart={(e) => onDragStart(e, task.id)}
      className="bg-white p-4 md:p-5 shadow-sm border border-slate-200 rounded-[1.5rem] mb-4 group hover:border-indigo-300 transition-all hover:shadow-md cursor-grab active:cursor-grabbing relative"
    >
      <div className="flex justify-between items-start mb-4">
        <div className="flex items-center space-x-3">
          <div className="grid grid-cols-2 gap-0.5 opacity-20 group-hover:opacity-40 transition-opacity">
            {[...Array(6)].map((_, i) => <div key={i} className="w-1 h-1 bg-slate-900 rounded-full"></div>)}
          </div>
          <span className={`text-[10px] font-black px-3 py-1.5 rounded-lg uppercase border tracking-wider ${getComplexityColor(task.complexity)}`}>
            {task.complexity}
          </span>
        </div>

        <div className="flex items-center space-x-1">
          <button 
            type="button"
            onMouseEnter={() => setIsDraggable(false)}
            onMouseLeave={() => setIsDraggable(true)}
            onClick={(e) => { e.stopPropagation(); handleStartEdit(task); }} 
            className="p-2 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-xl transition-all"
          >
            <Edit2 size={16} />
          </button>
          <button 
            type="button"
            onMouseEnter={() => setIsDraggable(false)}
            onMouseLeave={() => setIsDraggable(true)}
            onClick={(e) => { 
              e.stopPropagation(); 
              onDeleteTask(task.id); 
            }} 
            className="p-2 bg-rose-50 text-rose-500 hover:bg-rose-100 hover:text-rose-600 rounded-xl transition-all border border-rose-100/50"
          >
            <Trash2 size={18} />
          </button>
        </div>
      </div>

      <div className="pl-1 mb-5">
        <p className="font-bold text-slate-700 leading-relaxed text-lg whitespace-pre-wrap">{task.content}</p>
      </div>

      {task.attachments && task.attachments.length > 0 && (
        <div className="flex flex-wrap gap-1.5 mb-4 pl-1">
          {task.attachments.map((att, i) => (
            <button 
              key={i} 
              onMouseEnter={() => setIsDraggable(false)}
              onMouseLeave={() => setIsDraggable(true)}
              onClick={(e) => { e.stopPropagation(); onViewAttachment(att); }}
              className="p-2 bg-slate-50 border border-slate-100 rounded-xl hover:bg-indigo-50 transition-colors"
              title={att.name}
            >
              <Paperclip size={12} className="text-slate-400" />
            </button>
          ))}
        </div>
      )}

      <div className="flex items-center justify-between pt-4 border-t border-slate-100 pl-1">
        <div className="flex items-center text-xs font-bold text-slate-400 uppercase tracking-widest">
          <Clock size={16} className="mr-2 text-slate-300" />
          {task.status === TaskStatus.COMPLETED 
            ? formatDuration((task.completedTime || 0) - task.startTime) 
            : formatDuration(now - task.startTime)}
        </div>
        <div className="flex space-x-2">
          {task.status === TaskStatus.TO_DO && (
            <button 
              onMouseEnter={() => setIsDraggable(false)}
              onMouseLeave={() => setIsDraggable(true)}
              onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.IN_PROGRESS); }} 
              className="text-indigo-600 hover:scale-110 transition-transform"
            >
              <PlayCircle size={32} />
            </button>
          )}
          {task.status === TaskStatus.IN_PROGRESS && (
            <button 
              onMouseEnter={() => setIsDraggable(false)}
              onMouseLeave={() => setIsDraggable(true)}
              onClick={(e) => { e.stopPropagation(); onUpdateStatus(task.id, TaskStatus.COMPLETED); }} 
              className="text-emerald-600 hover:scale-110 transition-transform"
            >
              <CheckCircle2 size={32} />
            </button>
          )}
        </div>
      </div>
    </div>
  );
};

