import { supabase } from './supabase';
import { Task, User } from './types';

export const cloudStorage = {
  async getUsers(): Promise<User[]> {
    try {
      const { data, error } = await supabase.from('users').select('*');
      if (error) throw error;
      return (data || []).map(u => ({
        id: u.id,
        name: u.name,
        position: u.position,
        unit: u.unit,
        gender: u.gender,
        dob: u.dob,
        phone: u.phone,
        email: u.email,
        password: u.password,
        delegateLevel: u.delegateLevel,
        notes: u.notes,
        mustChangePassword: u.mustChangePassword
      })) as User[];
    } catch (error) {
      console.error('Error fetching users:', error);
      return [];
    }
  },

  async getTasks(): Promise<Task[]> {
    try {
      const { data, error } = await supabase.from('tasks').select('*').order('startTime', { ascending: false });
      if (error) throw error;
      return (data || []).map(t => ({
        id: t.id,
        userId: t.userId,
        content: t.content,
        startTime: Number(t.startTime),
        completedTime: t.completedTime ? Number(t.completedTime) : undefined,
        status: t.status,
        complexity: t.complexity,
        leadId: t.leadId,
        collaboratorIds: t.collaboratorIds || [],
        unit: t.unit,
        attachments: t.attachments || []
      })) as Task[];
    } catch (error) {
      console.error('Error fetching tasks:', error);
      return [];
    }
  },

  async upsertUser(user: User): Promise<{ success: boolean; error?: any }> {
    try {
      // Ánh xạ tường minh các trường khớp với SQL "delegateLevel", "mustChangePassword"
      const { error } = await supabase.from('users').upsert({
        id: user.id,
        name: user.name,
        position: user.position,
        unit: user.unit,
        gender: user.gender,
        dob: user.dob,
        phone: user.phone,
        email: user.email,
        password: user.password,
        delegateLevel: user.delegateLevel,
        notes: user.notes,
        mustChangePassword: user.mustChangePassword
      });
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error upserting user:', error);
      return { success: false, error };
    }
  },

  async insertTask(task: Task): Promise<{ success: boolean; error?: any }> {
    try {
      // Ánh xạ tường minh các trường khớp với SQL "userId", "startTime", "leadId"...
      const { error } = await supabase.from('tasks').insert({
        id: task.id,
        userId: task.userId, 
        content: task.content,
        startTime: task.startTime,
        completedTime: task.completedTime || null,
        status: task.status,
        complexity: task.complexity,
        leadId: task.leadId,
        collaboratorIds: task.collaboratorIds || [],
        unit: task.unit,
        attachments: task.attachments || []
      });
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error inserting task:', error);
      return { success: false, error };
    }
  },

  async updateTask(taskId: string, updates: Partial<Task>): Promise<{ success: boolean; error?: any }> {
    try {
      const { error } = await supabase.from('tasks').update(updates).eq('id', taskId);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error updating task:', error);
      return { success: false, error };
    }
  },

  async deleteTask(taskId: string): Promise<{ success: boolean; error?: any }> {
    try {
      const { error } = await supabase.from('tasks').delete().eq('id', taskId);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error deleting task:', error);
      return { success: false, error };
    }
  }
};

import React, { useState, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity, Attachment } from './types';
import { INITIAL_USERS, INITIAL_TASKS } from './constants';
import { Menu, Loader2, RefreshCw, AlertTriangle } from 'lucide-react';
import { cloudStorage } from './storage';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import ImportData from './components/ImportData';
import UserProfile from './components/UserProfile';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'import' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const initData = async () => {
      try {
        // 1. Lấy danh sách users từ DB
        let dbUsers = await cloudStorage.getUsers();

        // 2. Nếu DB trống, tiến hành seed dữ liệu khởi tạo
        if (dbUsers.length === 0) {
          console.log("Database empty, seeding initial users...");
          // Thực hiện seed tuần tự để đảm bảo dữ liệu được ghi xong
          for (const u of INITIAL_USERS) {
            await cloudStorage.upsertUser(u);
          }
          dbUsers = await cloudStorage.getUsers();
        }
        setUsers(dbUsers);

        // 3. Lấy danh sách tasks
        const dbTasks = await cloudStorage.getTasks();
        setTasks(dbTasks.length > 0 ? dbTasks : INITIAL_TASKS);

        // 4. Kiểm tra login session
        const savedUserStr = localStorage.getItem('tm_current_user');
        if (savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          // Quan trọng: Chỉ set user nếu user đó THỰC SỰ tồn tại trong DB
          const stillExists = dbUsers.find(u => u.id === parsedUser.id);
          if (stillExists) {
            setCurrentUser(stillExists);
          } else {
            console.warn("Session user not found in DB, logging out...");
            localStorage.removeItem('tm_current_user');
          }
        }
      } catch (err) {
        console.error("Initialization Error:", err);
        setSyncError("Lỗi kết nối hệ thống.");
      } finally {
        setIsInitialLoading(false);
      }
    };
    initData();
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('tm_current_user', JSON.stringify(user));
    if (!user.mustChangePassword) setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('tm_current_user');
    setActiveTab('dashboard');
    setIsSidebarOpen(false);
  };

  const handleChangePassword = async (newPass: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, password: newPass, mustChangePassword: false };
    setIsSyncing(true);
    setSyncError(null);
    const result = await cloudStorage.upsertUser(updated);
    if (result.success) {
      setUsers(prev => prev.map(u => u.id === currentUser.id ? updated : u));
      setCurrentUser(updated);
    } else {
      setSyncError("Lỗi khi đổi mật khẩu.");
    }
    setIsSyncing(false);
  };

  const handleResetPassword = async (email: string, newPass: string) => {
    const target = users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (target) {
      const updated = { ...target, password: newPass, mustChangePassword: false };
      setIsSyncing(true);
      const result = await cloudStorage.upsertUser(updated);
      if (result.success) {
        setUsers(prev => prev.map(u => u.email.toLowerCase() === email.toLowerCase() ? updated : u));
      }
      setIsSyncing(false);
    }
  };

  const addTask = async (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[]) => {
    if (!currentUser) return;

    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      status: TaskStatus.TO_DO, 
      complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit,
      attachments: attachments || []
    };

    setIsSyncing(true);
    setSyncError(null);
    const result = await cloudStorage.insertTask(newTask);

    if (result.success) {
      setTasks(prev => [newTask, ...prev]);
    } else {
      const errorMsg = result.error?.message || "Lỗi khóa ngoại hoặc kết nối.";
      setSyncError(`Lỗi lưu: ${errorMsg}`);
      alert(`Không thể lưu! Vui lòng thử F5 lại trang. (Chi tiết: ${errorMsg})`);
    }
    setIsSyncing(false);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates = {
      status: newStatus,
      completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : null,
      startTime: (newStatus === TaskStatus.IN_PROGRESS && task.status === TaskStatus.TO_DO) ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    }
    setIsSyncing(false);
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    }
    setIsSyncing(false);
  };

  const deleteTask = async (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setIsSyncing(true);
      const result = await cloudStorage.deleteTask(taskId);
      if (result.success) {
        setTasks(prev => prev.filter(t => t.id !== taskId));
      }
      setIsSyncing(false);
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Đang đồng bộ dữ liệu...</p>
      </div>
    );
  }

  if (!currentUser) return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  if (currentUser.mustChangePassword) return <ChangePassword onComplete={handleChangePassword} />;

  const isAdmin = currentUser.notes === 'AD';

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setIsSidebarOpen(false); }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="flex items-center space-x-2">
          <div className="w-8 h-8 bg-indigo-600 rounded-lg flex items-center justify-center text-white font-black text-lg">Q</div>
          <span className="font-black text-slate-800 uppercase tracking-tight text-sm">Quản lý GDT</span>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500"><Menu size={24} /></button>
      </div>

      <main className="flex-1 p-4 md:p-8 lg:p-10 max-w-full">
        <header className="mb-6 md:mb-10 flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4">
