const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<'dashboard' | 'tasks' | 'search' | 'delegate' | 'profile'>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const initData = async () => {
      try {
        const dbUsers = await cloudStorage.getUsers();
        setUsers(dbUsers);

        const dbTasks = await cloudStorage.getTasks();
        setTasks(dbTasks);

        const savedUserStr = localStorage.getItem('tm_current_user');
        if (savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          const stillExists = dbUsers.find(u => u.id === parsedUser.id);
          if (stillExists) {
            setCurrentUser(stillExists);
          } else {
            localStorage.removeItem('tm_current_user');
          }
        }
      } catch (err) {
        console.error("Initialization Error:", err);
        setSyncError("Lỗi kết nối cơ sở dữ liệu Cloud.");
      } finally {
        setIsInitialLoading(false);
      }
    };
    initData();
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('tm_current_user', JSON.stringify(user));
    if (!user.mustChangePassword) setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('tm_current_user');
    setActiveTab('dashboard');
    setIsSidebarOpen(false);
  };

  const handleChangePassword = async (newPass: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, password: newPass, mustChangePassword: false };
    setIsSyncing(true);
    setSyncError(null);
    const result = await cloudStorage.upsertUser(updated);
    if (result.success) {
      setUsers(prev => prev.map(u => u.id === currentUser.id ? updated : u));
      setCurrentUser(updated);
      localStorage.setItem('tm_current_user', JSON.stringify(updated));
    } else {
      setSyncError("Lỗi khi cập nhật mật khẩu mới.");
    }
    setIsSyncing(false);
  };

  const handleResetPassword = async (email: string, newPass: string) => {
    const target = users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (target) {
      const updated = { ...target, password: newPass, mustChangePassword: true };
      setIsSyncing(true);
      const result = await cloudStorage.upsertUser(updated);
      if (result.success) {
        setUsers(prev => prev.map(u => u.id === target.id ? updated : u));
      }
      setIsSyncing(false);
    }
  };

  const addTask = async (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[], deadline?: number) => {
    if (!currentUser) return;

    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      deadline: deadline,
      status: TaskStatus.TO_DO, 
      complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      unit: currentUser.unit,
      attachments: attachments || []
    };

    setIsSyncing(true);
    setSyncError(null);
    const result = await cloudStorage.insertTask(newTask);
    if (result.success) {
      setTasks(prev => [newTask, ...prev]);
    } else {
      setSyncError("Lỗi khóa ngoại hoặc kết nối: " + (result.error?.message || ""));
    }
    setIsSyncing(false);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;

    const updates: Partial<Task> = {
      status: newStatus,
      completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : undefined,
      startTime: (newStatus === TaskStatus.IN_PROGRESS && task.status === TaskStatus.TO_DO) ? Date.now() : task.startTime
    };

    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    }
    setIsSyncing(false);
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) {
      setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    }
    setIsSyncing(false);
  };

  const deleteTask = async (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setIsSyncing(true);
      const result = await cloudStorage.deleteTask(taskId);
      if (result.success) {
        setTasks(prev => prev.filter(t => t.id !== taskId));
      }
      setIsSyncing(false);
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Đang tải dữ liệu từ Cloud...</p>
      </div>
    );
  }

  if (!currentUser) return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  if (currentUser.mustChangePassword) return <ChangePassword onComplete={handleChangePassword} />;

  const isAdmin = currentUser.notes === 'AD1' || currentUser.notes === 'AD2';
  const canDelegate = currentUser.delegateLevel === 'X1' || currentUser.delegateLevel === 'X2';

  const logoUrl = "https://lh3.googleusercontent.com/d/1FUb404uLq8ton8azidI9UrR1DLs7Byds";

  // Lọc công việc cho Tab "Việc của tôi": Thuộc sở hữu/tham gia VÀ trong vòng 2 tháng (60 ngày)
  const myRecentTasks = tasks.filter(t => {
    const isRelated = t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id);
    const twoMonthsAgo = Date.now() - (60 * 24 * 60 * 60 * 1000);
    const isRecent = t.startTime >= twoMonthsAgo;
    return isRelated && isRecent;
  });

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setIsSidebarOpen(false); }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <div className="md:hidden flex items-center justify-between px-4 py-3 bg-white border-b border-slate-200 sticky top-0 z-40 shadow-sm">
        <div className="flex items-center space-x-2">
          <div className="w-9 h-9 rounded-full overflow-hidden border border-amber-400 shadow-sm bg-white shrink-0 p-0.5 flex items-center justify-center">
            <img 
              src={logoUrl}
              alt="Logo" 
              className="w-full h-full object-contain scale-125"
              onError={(e) => {
                e.currentTarget.src = "https://www.gdt.gov.vn/wps/themes/html/V_GDT_Theme/images/logo.png";
              }}
            />
          </div>
          <span className="font-black text-slate-800 uppercase tracking-tight text-xs">Quản lý công việc</span>
        </div>
        <button onClick={() => setIsSidebarOpen(true)} className="p-2 text-slate-500"><Menu size={24} /></button>
      </div>

      <main className="flex-1 min-w-0 p-4 md:p-8 lg:p-10">
        <header className="mb-6 md:mb-10 flex flex-col sm:flex-row sm:justify-between sm:items-start gap-4">
          <div>
            <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3">
              {activeTab === 'dashboard' && 'Tổng quan'}
              {activeTab === 'tasks' && 'Việc của tôi'}
              {activeTab === 'search' && 'Báo cáo & Tra cứu'}
              {activeTab === 'delegate' && 'Giao nhiệm vụ'}
              {activeTab === 'profile' && 'Cá nhân'}
              {isSyncing && <RefreshCw className="text-indigo-400 animate-spin" size={24} />}
            </h1>
            <div className="flex items-center mt-1 space-x-2">
               {syncError && (
                 <div className="flex items-center text-rose-500 text-[10px] font-black uppercase bg-rose-50 px-2 py-0.5 rounded border border-rose-100">
                   <AlertTriangle size={12} className="mr-1" /> {syncError}
                 </div>
               )}
               {activeTab === 'tasks' && (
                 <span className="text-[9px] font-bold text-slate-400 uppercase tracking-tighter bg-slate-100 px-2 py-0.5 rounded italic">Hiển thị 60 ngày gần nhất</span>
               )}
            </div>
          </div>
        </header>

        <div className="w-full">
          {activeTab === 'dashboard' && <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => { setViewedUserId(uid); setActiveTab('search'); }} />}
          {activeTab === 'tasks' && <TaskBoard tasks={myRecentTasks} onAddTask={addTask} onUpdateStatus={updateTaskStatus} onUpdateTask={updateTask} onDeleteTask={deleteTask} />}
          {activeTab === 'search' && <AdminSearch users={users} tasks={tasks} isAdmin={isAdmin} currentUser={currentUser} onUpdateTask={updateTask} onResetUserPassword={handleResetPassword} initialSelectedUserId={viewedUserId} />}
          {activeTab === 'delegate' && (canDelegate ? <Delegation currentUser={currentUser} users={users} onAssign={addTask} /> : <div className="p-10 text-center font-bold text-slate-400 uppercase tracking-widest bg-white rounded-3xl border border-slate-100 shadow-sm">Bạn không có quyền truy cập chức năng này.</div>)}
          {activeTab === 'profile' && <UserProfile user={currentUser} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo, useState, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity } from '../types';
import { BarChart, Bar, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer, PieChart, Pie, Cell, Legend } from 'recharts';
import { Calendar, List, X, Trophy, Target, Clock, CheckCircle2, AlertCircle, User as UserIcon } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

const SmartDateInput: React.FC<{
  label: string;
  value: string; 
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');

  useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) {
      setDisplayText('');
    }
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, ''); 
    if (raw.length > 8) raw = raw.slice(0, 8);

    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    } else if (raw.length >= 5) {
      formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    }

    setDisplayText(formatted);

    if (raw.length === 8) {
      const d = raw.slice(0, 2);
      const m = raw.slice(2, 4);
      const y = raw.slice(4, 8);
      // Kiểm tra ngày hợp lệ đơn giản
      const dayNum = parseInt(d);
      const monthNum = parseInt(m);
      if (dayNum >= 1 && dayNum <= 31 && monthNum >= 1 && monthNum <= 12) {
        const dateObj = new Date(`${y}-${m}-${d}`);
        if (!isNaN(dateObj.getTime())) {
          onChange(`${y}-${m}-${d}`);
        }
      }
    }
  };

  return (
    <div className="flex-1 w-full min-w-[140px]">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input
          type="text"
          value={displayText}
          onChange={handleTextChange}
          placeholder="DD/MM/YYYY"
          className="w-full bg-white border border-slate-200 rounded-xl pl-4 pr-10 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
        />
        <div className="absolute right-3 top-1/2 -translate-y-1/2 flex items-center h-full">
          <div className="relative">
            <Calendar size={18} className="text-slate-400 group-hover:text-indigo-500 transition-colors pointer-events-none" />
            <input
              type="date"
              value={value}
              onChange={(e) => onChange(e.target.value)}
              className="absolute inset-0 w-full h-full opacity-0 cursor-pointer"
            />
          </div>
        </div>
      </div>
    </div>
  );
};

interface DashboardProps {
  users: User[];
  tasks: Task[];
  currentUser: User;
  onUserClick: (id: string) => void;
}

const Dashboard: React.FC<DashboardProps> = ({ users, tasks, currentUser, onUserClick }) => {
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');
  const [selectedUnit, setSelectedUnit] = useState('');
  const [selectedStaffId, setSelectedStaffId] = useState('');
  const [detailModal, setDetailModal] = useState<{ isOpen: boolean; title: string; tasks: Task[] }>({
    isOpen: false,
    title: '',
    tasks: []
  });

  const isAD1 = currentUser.notes === 'AD1';
  const isAD2 = currentUser.notes === 'AD2';
  const isRegularUser = !isAD1 && !isAD2;

  const units = useMemo(() => Array.from(new Set(users.map(u => u.unit))), [users]);

  const accessibleUsers = useMemo(() => {
    if (isAD1) {
      return selectedUnit ? users.filter(u => u.unit === selectedUnit) : users;
    }
    if (isAD2) {
      return users.filter(u => u.unit === currentUser.unit);
    }
    return [currentUser];
  }, [users, currentUser, isAD1, isAD2, selectedUnit]);

  const getPoints = (task: Task) => {
    // Nếu quá hạn thì không được tính điểm
    if (task.status === TaskStatus.COMPLETED && task.deadline && task.completedTime && task.completedTime > task.deadline) {
      return 0;
    }
    if (task.status !== TaskStatus.COMPLETED) return 0;

    switch (task.complexity) {
      case TaskComplexity.MEDIUM: return 1;
      case TaskComplexity.HARD: return 3;
      case TaskComplexity.VERY_HARD: return 5;
      default: return 0;
    }
  };

  const staffOptions = useMemo(() => {
    const opts = accessibleUsers.map(u => ({
      id: u.id,
      label: u.name,
      subLabel: u.unit
    }));
    return [{ id: '', label: 'Tất cả nhân sự' }, ...opts];
  }, [accessibleUsers]);

  const stats = useMemo(() => {
    const now = Date.now();
    const filtered = tasks.filter(t => {
      let hasAccess = false;
      if (isAD1) hasAccess = true;
      else if (isAD2) hasAccess = t.unit === currentUser.unit;
      else hasAccess = (t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id));

      if (!hasAccess) return false;

      const matchesUnit = isAD1 && selectedUnit ? t.unit === selectedUnit : true;
      const matchesStaff = selectedStaffId 
        ? (t.userId === selectedStaffId || t.leadId === selectedStaffId || t.collaboratorIds.includes(selectedStaffId)) 
        : true;

      const taskTime = t.startTime;
      const matchesStart = startDate ? taskTime >= new Date(startDate).getTime() : true;
      const matchesEnd = endDate ? taskTime <= new Date(endDate).getTime() + 86400000 : true;

      return matchesUnit && matchesStaff && matchesStart && matchesEnd;
    });

    const todoTasks = filtered.filter(t => t.status === TaskStatus.TO_DO);
    const inProgressTasks = filtered.filter(t => t.status === TaskStatus.IN_PROGRESS);
    const completedTasks = filtered.filter(t => t.status === TaskStatus.COMPLETED);
    const overdueTasks = filtered.filter(t => t.status !== TaskStatus.COMPLETED && t.deadline && now > t.deadline);

    const performanceData = (isRegularUser ? [currentUser] : accessibleUsers)
      .map(u => {
        const leadTasks = filtered.filter(t => t.leadId === u.id);
        const score = leadTasks.reduce((acc, t) => acc + getPoints(t), 0);

        return {
          name: u.name,
          score: score,
          count: leadTasks.length
        };
      })
      .sort((a, b) => b.score - a.score)
      .slice(0, 8);

    const complexityChartData = [
      { name: TaskComplexity.MEDIUM, value: filtered.filter(t => t.complexity === TaskComplexity.MEDIUM).length },
      { name: TaskComplexity.HARD, value: filtered.filter(t => t.complexity === TaskComplexity.HARD).length },
      { name: TaskComplexity.VERY_HARD, value: filtered.filter(t => t.complexity === TaskComplexity.VERY_HARD).length },
    ].filter(d => d.value > 0);

    return {
      total: filtered,
      todo: todoTasks,
      inProgress: inProgressTasks,
      completed: completedTasks,
      overdue: overdueTasks,
      complexityChartData,
      performanceData
    };
  }, [tasks, users, currentUser, isAD1, isAD2, isRegularUser, startDate, endDate, selectedUnit, selectedStaffId, accessibleUsers]);

  const COLORS = ['#6366f1', '#f59e0b', '#ef4444'];

  const openDetails = (title: string, taskList: Task[]) => {
    setDetailModal({ isOpen: true, title, tasks: taskList });
  };

  return (
    <div className="space-y-6 pb-12">
      <div className="bg-white p-4 md:p-6 rounded-3xl border border-slate-200 shadow-sm flex flex-col lg:flex-row items-end gap-4">

        {isAD1 && (
          <div className="w-full lg:w-64">
            <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Lọc theo đơn vị</label>
            <select
              value={selectedUnit}
              onChange={(e) => { setSelectedUnit(e.target.value); setSelectedStaffId(''); }}
              className="w-full bg-white border border-slate-200 rounded-xl px-4 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium"
            >
              <option value="">Tất cả đơn vị</option>
              {units.map(u => <option key={u} value={u}>{u}</option>)}
            </select>
          </div>
        )}

        {(isAD1 || isAD2) && (
          <div className="w-full lg:w-72">
            <SearchableSelect
              label="Lọc theo nhân sự"
              options={staffOptions}
              value={selectedStaffId}
              onChange={setSelectedStaffId}
              placeholder="Tất cả nhân sự"
            />
          </div>
        )}

        <div className="flex flex-col sm:flex-row gap-3 w-full lg:flex-1">
          <SmartDateInput label="Từ ngày" value={startDate} onChange={setStartDate} />
          <SmartDateInput label="Đến ngày" value={endDate} onChange={setEndDate} />
        </div>

        <button 
          onClick={() => { setStartDate(''); setEndDate(''); setSelectedStaffId(''); setSelectedUnit(''); }}
          className="w-full sm:w-auto bg-slate-50 text-slate-500 px-6 py-2.5 rounded-xl hover:bg-slate-100 transition-colors text-xs font-black uppercase tracking-widest border border-slate-200"
        >
          Xóa
        </button>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-3 lg:grid-cols-5 gap-4">
        {[
          { label: 'Tổng số', count: stats.total.length, icon: List, color: 'indigo', list: stats.total },
          { label: 'Cần làm', count: stats.todo.length, icon: Target, color: 'slate', list: stats.todo },
          { label: 'Đang làm', count: stats.inProgress.length, icon: Clock, color: 'amber', list: stats.inProgress },
          { label: 'Hoàn thành', count: stats.completed.length, icon: CheckCircle2, color: 'emerald', list: stats.completed },
          { label: 'Quá hạn', count: stats.overdue.length, icon: AlertCircle, color: 'rose', list: stats.overdue },
        ].map((item, idx) => {
          const Icon = item.icon;
          return (
            <button
              key={idx}
              onClick={() => openDetails(item.label, item.list)}
              className="bg-white p-5 rounded-3xl border border-slate-200 shadow-sm hover:border-indigo-300 hover:shadow-md transition-all group text-left"
            >
              <div className="flex items-center justify-between mb-3">
                <div className={`w-10 h-10 bg-${item.color}-50 text-${item.color}-600 rounded-xl flex items-center justify-center`}>
                  <Icon size={20} />
                </div>
                <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">{item.label}</span>
              </div>
              <p className="text-3xl font-black text-slate-800 tracking-tighter">{item.count}</p>
            </button>
          );
        })}
      </div>

      <div className="grid grid-cols-1 xl:grid-cols-2 gap-6">
        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center">
            <Trophy className="mr-2 text-amber-500" size={18} /> Hiệu năng nhân sự
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <BarChart data={stats.performanceData} layout="vertical" margin={{ left: -10, right: 30 }}>
                <CartesianGrid strokeDasharray="3 3" horizontal={true} vertical={false} stroke="#f1f5f9" />
                <XAxis type="number" hide />
                <YAxis dataKey="name" type="category" axisLine={false} tickLine={false} width={80} fontSize={10} fontWeight="700" />
                <Tooltip cursor={{ fill: '#f8fafc' }} contentStyle={{ borderRadius: '12px', border: 'none', boxShadow: '0 10px 15px -3px rgb(0 0 0 / 0.1)' }} />
                <Bar dataKey="score" fill="#6366f1" radius={[0, 4, 4, 0]} barSize={20} />
              </BarChart>
            </ResponsiveContainer>
          </div>
        </div>

        <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
          <h3 className="text-sm font-black text-slate-800 uppercase tracking-widest mb-6 flex items-center">
            <Target className="mr-2 text-indigo-500" size={18} /> Phân loại mức độ
          </h3>
          <div className="h-[300px] w-full">
            <ResponsiveContainer width="100%" height="100%">
              <PieChart>
                <Pie data={stats.complexityChartData} cx="50%" cy="50%" innerRadius={60} outerRadius={80} paddingAngle={5} dataKey="value">
                  {stats.complexityChartData.map((entry, index) => <Cell key={`cell-${index}`} fill={COLORS[index % COLORS.length]} />)}
                </Pie>
                <Tooltip />
                <Legend iconType="circle" />
              </PieChart>
            </ResponsiveContainer>
          </div>
        </div>
      </div>

      {detailModal.isOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-sm" onClick={() => setDetailModal({ ...detailModal, isOpen: false })}></div>
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl relative z-10 overflow-hidden flex flex-col max-h-[90vh]">
            <div className="p-6 md:p-8 border-b border-slate-100 flex items-center justify-between">
              <h2 className="text-xl font-black text-slate-800 uppercase tracking-tight">{detailModal.title}</h2>
              <button onClick={() => setDetailModal({ ...detailModal, isOpen: false })} className="p-2 hover:bg-slate-50 rounded-xl transition-all"><X size={20} /></button>
            </div>
            <div className="flex-1 overflow-y-auto p-4 md:p-6 space-y-4">
              {detailModal.tasks.map(task => {
