import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import UserProfile from './components/UserProfile';
import DocumentEntry from './components/DocumentEntry';
import DocumentSearch from './components/DocumentSearch';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const initData = async () => {
      try {
        const [dbUsers, dbTasks, dbDocs] = await Promise.all([
          cloudStorage.getUsers(),
          cloudStorage.getTasks(),
          cloudStorage.getDocuments()
        ]);
        setUsers(dbUsers);
        setTasks(dbTasks);
        setDocuments(dbDocs);

        const savedUserStr = localStorage.getItem('tm_current_user');
        if (savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          const stillExists = dbUsers.find(u => u.id === parsedUser.id);
          if (stillExists) {
            setCurrentUser(stillExists);
          } else {
            localStorage.removeItem('tm_current_user');
          }
        }
      } catch (err) {
        console.error("Initialization Error:", err);
        setSyncError("Lỗi kết nối cơ sở dữ liệu Cloud.");
      } finally {
        setIsInitialLoading(false);
      }
    };
    initData();
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('tm_current_user', JSON.stringify(user));
    if (!user.mustChangePassword) setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('tm_current_user');
    setActiveTab('dashboard');
    setIsSidebarOpen(false);
  };

  const handleChangePassword = async (newPass: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, password: newPass, mustChangePassword: false };
    setIsSyncing(true);
    const result = await cloudStorage.upsertUser(updated);
    if (result.success) {
      setUsers(prev => prev.map(u => u.id === currentUser.id ? updated : u));
      setCurrentUser(updated);
      localStorage.setItem('tm_current_user', JSON.stringify(updated));
    }
    setIsSyncing(false);
  };

  const handleResetPassword = async (email: string, newPass: string) => {
    const target = users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (target) {
      const updated = { ...target, password: newPass, mustChangePassword: true };
      setIsSyncing(true);
      await cloudStorage.upsertUser(updated);
      setUsers(prev => prev.map(u => u.id === target.id ? updated : u));
      setIsSyncing(false);
    }
  };

  const handleAddDocument = async (doc: Document) => {
    setIsSyncing(true);
    const result = await cloudStorage.insertDocument(doc);
    if (result.success) {
      setDocuments(prev => [doc, ...prev]);
    }
    setIsSyncing(false);
  };

  const addTask = async (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[], deadline?: number, documentId?: string) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      deadline: deadline,
      status: TaskStatus.TO_DO, 
      complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      forwarderIds: [],
      unit: currentUser.unit,
      attachments: attachments || [],
      documentId
    };
    setIsSyncing(true);
    const result = await cloudStorage.insertTask(newTask);
    if (result.success) setTasks(prev => [newTask, ...prev]);
    setIsSyncing(false);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates: Partial<Task> = {
      status: newStatus,
      completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : undefined,
      startTime: (newStatus === TaskStatus.IN_PROGRESS && task.status === TaskStatus.TO_DO) ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const handleForwardTask = async (taskId: string, newLeadId: string, newCollaboratorIds: string[]) => {
    if (!currentUser) return;
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates: Partial<Task> = {
      leadId: newLeadId,
      collaboratorIds: newCollaboratorIds,
      forwarderIds: [...(task.forwarderIds || []), currentUser.id],
      status: TaskStatus.IN_PROGRESS,
      startTime: task.status === TaskStatus.TO_DO ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const deleteTask = async (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setIsSyncing(true);
      const result = await cloudStorage.deleteTask(taskId);
      if (result.success) setTasks(prev => prev.filter(t => t.id !== taskId));
      setIsSyncing(false);
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Đang tải dữ liệu Cloud...</p>
      </div>
    );
  }

  if (!currentUser) return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  if (currentUser.mustChangePassword) return <ChangePassword onComplete={handleChangePassword} />;

  const isAdmin = currentUser.notes === 'AD1' || currentUser.notes === 'AD2';
  const isVT = currentUser.notes === 'VT';
  const canDelegate = currentUser.delegateLevel === 'X1' || currentUser.delegateLevel === 'X2';

  const myRecentTasks = tasks.filter(t => {
    const isRelated = t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id) || (t.forwarderIds && t.forwarderIds.includes(currentUser.id));
    const twoMonthsAgo = Date.now() - (60 * 24 * 60 * 60 * 1000);
    return isRelated && t.startTime >= twoMonthsAgo;
  });

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setIsSidebarOpen(false); }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 min-w-0 p-4 md:p-8 lg:p-10">
        <header className="mb-6 flex justify-between items-center">
          <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3 uppercase">
            {activeTab === 'dashboard' && 'Tổng quan'}
            {activeTab === 'tasks' && 'Việc của tôi'}
            {activeTab === 'search' && 'Tra cứu & Báo cáo'}
            {activeTab === 'delegate' && 'Giao việc'}
            {activeTab === 'doc-entry' && 'Nhập văn bản'}
            {activeTab === 'doc-search' && 'Tra cứu văn bản'}
            {isSyncing && <RefreshCw className="text-indigo-400 animate-spin" size={24} />}
          </h1>
        </header>

        <div className="w-full">
          {activeTab === 'dashboard' && <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => { setViewedUserId(uid); setActiveTab('search'); }} />}
          {activeTab === 'tasks' && <TaskBoard tasks={myRecentTasks} onAddTask={addTask} onUpdateStatus={updateTaskStatus} onUpdateTask={updateTask} onDeleteTask={deleteTask} onForwardTask={handleForwardTask} currentUser={currentUser} allUsers={users} />}
          {activeTab === 'search' && <AdminSearch users={users} tasks={tasks} isAdmin={isAdmin} currentUser={currentUser} onUpdateTask={updateTask} onResetUserPassword={handleResetPassword} initialSelectedUserId={viewedUserId} />}
          {activeTab === 'delegate' && <Delegation currentUser={currentUser} users={users} documents={documents} onAssign={addTask} />}
          {activeTab === 'doc-entry' && isVT && <DocumentEntry onAdd={handleAddDocument} />}
          {activeTab === 'doc-search' && isVT && <DocumentSearch documents={documents} tasks={tasks} users={users} />}
          {activeTab === 'profile' && <UserProfile user={currentUser} />}
        </div>
      </main>
    </div>
  );
};

export default App;

import React, { useMemo } from 'react';
import { User } from '../types';
import { 
  LayoutDashboard, 
  ListTodo, 
  Search, 
  Send, 
  UserCircle, 
  LogOut,
  X,
  FilePlus,
  FileSearch
} from 'lucide-react';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: any) => void;
  isAdmin: boolean;
  currentUser: User;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isAdmin, currentUser, onLogout, isOpen, onClose }) => {
  const menuItems = useMemo(() => {
    const items = [
      { id: 'dashboard', label: 'Tổng quan', icon: LayoutDashboard },
      { id: 'tasks', label: 'Việc của tôi', icon: ListTodo },
      { id: 'search', label: 'Tra cứu & Báo cáo', icon: Search },
      { id: 'delegate', label: 'Giao việc', icon: Send },
      { id: 'doc-entry', label: 'Nhập văn bản', icon: FilePlus, roles: ['VT'] },
      { id: 'doc-search', label: 'Tra cứu văn bản', icon: FileSearch, roles: ['VT'] },
      { id: 'profile', label: 'Hồ sơ cá nhân', icon: UserCircle },
    ];

    return items.filter(item => {
      if (item.id === 'delegate') {
        return currentUser.delegateLevel === 'X1' || currentUser.delegateLevel === 'X2';
      }
      if (item.roles) {
        return item.roles.includes(currentUser.notes);
      }
      return true;
    });
  }, [currentUser.delegateLevel, currentUser.notes]);

  const logoUrl = "https://lh3.googleusercontent.com/d/1FUb404uLq8ton8azidI9UrR1DLs7Byds";

  return (
    <>
      <div className={`fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 md:hidden transition-opacity duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} onClick={onClose} />
      <aside className={`fixed inset-y-0 left-0 w-72 bg-white border-r border-slate-200 flex flex-col z-[60] transition-all duration-300 ease-in-out md:translate-x-0 md:static md:h-screen md:w-64 lg:w-72 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-amber-400 shadow-md bg-white p-0.5 flex items-center justify-center">
              <img src={logoUrl} alt="Logo" className="w-full h-full object-contain scale-125" />
            </div>
            <span className="text-sm font-black tracking-tight text-slate-800 uppercase">Quản lý<br/>công việc</span>
          </div>
          <button onClick={onClose} className="md:hidden p-2 text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl transition-all ${activeTab === item.id ? 'bg-indigo-600 text-white font-bold shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <Icon size={20} />
                <span className="text-sm">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="mb-4 p-4 bg-slate-50 rounded-2xl flex items-center space-x-3">
            <img src={`https://picsum.photos/seed/${currentUser.id}/100`} alt="Ava" className="w-10 h-10 rounded-xl object-cover" />
            <div className="flex-1 min-w-0">
              <p className="text-xs font-black text-slate-800 truncate uppercase">{currentUser.name}</p>
              <p className="text-[10px] text-slate-400 font-bold truncate uppercase tracking-tighter">{currentUser.unit}</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl text-rose-500 hover:bg-rose-50 font-bold text-sm">
            <LogOut size={18} />
            <span>Đăng xuất</span>
          </button>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState } from 'react';
import { Document } from '../types';
import { Calendar, Save, FileText, AlertCircle } from 'lucide-react';

const SmartDateInput: React.FC<{
  label: string;
  value: string; 
  onChange: (val: string) => void;
  required?: boolean;
}> = ({ label, value, onChange, required }) => {
  const [displayText, setDisplayText] = useState('');
  React.useEffect(() => {
    if (value && value.includes('-')) {
      const [y, m, d] = value.split('-');
      setDisplayText(`${d}/${m}/${y}`);
    } else if (!value) setDisplayText('');
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, '').slice(0, 8);
    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    else if (raw.length >= 5) formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    setDisplayText(formatted);
    if (raw.length === 8) {
      const d = raw.slice(0, 2), m = raw.slice(2, 4), y = raw.slice(4, 8);
      const ds = `${y}-${m}-${d}`;
      if (!isNaN(new Date(ds).getTime())) onChange(ds);
    }
  };

  return (
    <div className="w-full">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label} {required && '*'}</label>
      <div className="relative group">
        <input type="text" value={displayText} onChange={handleTextChange} placeholder="DD/MM/YYYY" className="w-full bg-slate-50 border border-slate-200 rounded-xl pl-4 pr-12 py-3 text-sm outline-none focus:ring-2 focus:ring-indigo-500 transition-all font-medium" />
        <div className="absolute right-3 top-1/2 -translate-y-1/2"><Calendar size={18} className="text-slate-300" /></div>
        <input type="date" value={value} onChange={(e) => onChange(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer" />
      </div>
    </div>
  );
};

const DocumentEntry: React.FC<{ onAdd: (doc: Document) => void }> = ({ onAdd }) => {
