    refCode: '', docNumber: '', docDate: '', arrivalDate: '', senderUnit: '', taxCode: '', summary: '', deadline: '', notes: ''
  });

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    const doc: Document = {
      ...formData as Document,
      id: Math.random().toString(36).substr(2, 9),
      createdAt: Date.now()
    };
    onAdd(doc);
    alert('Đã lưu văn bản thành công!');
    setFormData({ refCode: '', docNumber: '', docDate: '', arrivalDate: '', senderUnit: '', taxCode: '', summary: '', deadline: '', notes: '' });
  };

  return (
    <div className="max-w-4xl mx-auto bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
      <div className="p-8 bg-indigo-600 text-white flex items-center space-x-3">
        <FileText size={28} />
        <h2 className="text-2xl font-black uppercase tracking-tight">Tiếp nhận văn bản đến</h2>
      </div>
      <form onSubmit={handleSubmit} className="p-8 grid grid-cols-1 md:grid-cols-2 gap-6">
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Số ký hiệu *</label>
          <input required type="text" value={formData.refCode} onChange={e => setFormData({...formData, refCode: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Số văn bản đến *</label>
          <input required type="text" value={formData.docNumber} onChange={e => setFormData({...formData, docNumber: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <SmartDateInput label="Ngày văn bản" value={formData.docDate!} onChange={v => setFormData({...formData, docDate: v})} required />
        <SmartDateInput label="Ngày đến" value={formData.arrivalDate!} onChange={v => setFormData({...formData, arrivalDate: v})} required />
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Đơn vị gửi</label>
          <input type="text" value={formData.senderUnit} onChange={e => setFormData({...formData, senderUnit: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <div>
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Mã số thuế</label>
          <input type="text" value={formData.taxCode} onChange={e => setFormData({...formData, taxCode: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <div className="md:col-span-2">
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Trích yếu *</label>
          <textarea required value={formData.summary} onChange={e => setFormData({...formData, summary: e.target.value})} rows={3} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <SmartDateInput label="Hạn xử lý" value={formData.deadline!} onChange={v => setFormData({...formData, deadline: v})} />
        <div className="md:col-span-2">
          <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">Ghi chú</label>
          <input type="text" value={formData.notes} onChange={e => setFormData({...formData, notes: e.target.value})} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-indigo-500" />
        </div>
        <div className="md:col-span-2 pt-4">
          <button type="submit" className="w-full bg-indigo-600 text-white py-4 rounded-xl font-black uppercase tracking-widest text-sm hover:bg-indigo-700 shadow-xl transition-all flex items-center justify-center space-x-2">
            <Save size={20} /> <span>Lưu văn bản hệ thống</span>
          </button>
        </div>
      </form>
    </div>
  );
};

export default DocumentEntry;

import React, { useState, useMemo } from 'react';
import { Document, Task, User, TaskStatus } from '../types';
import { Search, FileText, User as UserIcon, CheckCircle, Clock, AlertCircle } from 'lucide-react';

const formatDate = (ds: string) => ds ? ds.split('-').reverse().join('/') : '-';

const DocumentSearch: React.FC<{ documents: Document[], tasks: Task[], users: User[] }> = ({ documents, tasks, users }) => {
  const [keyword, setKeyword] = useState('');

  const filteredDocs = useMemo(() => {
    return documents.filter(d => 
      d.refCode.toLowerCase().includes(keyword.toLowerCase()) || 
      d.summary.toLowerCase().includes(keyword.toLowerCase()) ||
      d.taxCode.toLowerCase().includes(keyword.toLowerCase())
    );
  }, [documents, keyword]);

  return (
    <div className="space-y-6">
      <div className="bg-white p-6 rounded-3xl border border-slate-200 shadow-sm">
        <div className="relative">
          <Search className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
          <input 
            type="text" 
            placeholder="Tìm theo số ký hiệu, trích yếu hoặc mã số thuế..." 
            value={keyword}
            onChange={e => setKeyword(e.target.value)}
            className="w-full pl-12 pr-4 py-4 bg-slate-50 border border-slate-200 rounded-2xl outline-none focus:ring-2 focus:ring-indigo-500 font-medium"
          />
        </div>
      </div>

      <div className="bg-white rounded-[2rem] border border-slate-200 shadow-sm overflow-hidden overflow-x-auto">
        <table className="w-full text-left text-xs whitespace-nowrap">
          <thead className="bg-slate-50 border-b border-slate-100 uppercase font-black text-slate-400 tracking-widest">
            <tr>
              <th className="px-6 py-4">Ký hiệu/Số đến</th>
              <th className="px-6 py-4">Ngày VB/Đến</th>
              <th className="px-6 py-4">Đơn vị/MST</th>
              <th className="px-6 py-4">Trích yếu</th>
              <th className="px-6 py-4">Cán bộ xử lý</th>
              <th className="px-6 py-4">Trạng thái</th>
              <th className="px-6 py-4">Hạn/Ghi chú</th>
            </tr>
          </thead>
          <tbody>
            {filteredDocs.map(doc => {
              const linkedTask = tasks.find(t => t.documentId === doc.id);
              const leadUser = linkedTask ? users.find(u => u.id === linkedTask.leadId) : null;

              return (
                <tr key={doc.id} className="border-b border-slate-50 hover:bg-slate-50/50 transition-colors">
                  <td className="px-6 py-4">
                    <div className="font-bold text-slate-800">{doc.refCode}</div>
                    <div className="text-[10px] text-slate-400">Đến: {doc.docNumber}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-medium text-slate-600">{formatDate(doc.docDate)}</div>
                    <div className="text-[10px] text-slate-400">{formatDate(doc.arrivalDate)}</div>
                  </td>
                  <td className="px-6 py-4">
                    <div className="font-medium text-slate-700">{doc.senderUnit || '-'}</div>
                    <div className="text-[10px] font-black text-indigo-500 uppercase">{doc.taxCode || '-'}</div>
                  </td>
                  <td className="px-6 py-4 max-w-xs whitespace-normal">
                    <p className="font-medium text-slate-600 line-clamp-2">{doc.summary}</p>
