import { supabase } from './supabase';
import { Task, User, Document } from './types';

export const cloudStorage = {
  async getUsers(): Promise<User[]> {
    try {
      const { data, error } = await supabase.from('users').select('*');
      if (error) throw error;
      return (data || []).map((u: any) => ({
        id: String(u.id),
        name: String(u.name),
        position: String(u.position),
        unit: String(u.unit),
        gender: u.gender,
        dob: String(u.dob),
        phone: String(u.phone),
        email: String(u.email),
        password: String(u.password),
        delegateLevel: String(u.delegateLevel),
        notes: String(u.notes),
        mustChangePassword: Boolean(u.mustChangePassword)
      })) as User[];
    } catch (error) {
      console.error('Error fetching users:', error);
      return [];
    }
  },

  async getTasks(): Promise<Task[]> {
    try {
      const { data, error } = await supabase.from('tasks').select('*').order('startTime', { ascending: false });
      if (error) throw error;
      return (data || []).map((t: any) => ({
        id: String(t.id),
        userId: String(t.userId),
        content: String(t.content),
        startTime: Number(t.startTime),
        deadline: t.deadline ? Number(t.deadline) : undefined,
        completedTime: t.completedTime ? Number(t.completedTime) : undefined,
        status: t.status,
        complexity: t.complexity,
        leadId: String(t.leadId),
        collaboratorIds: t.collaboratorIds || [],
        forwarderIds: t.forwarderIds || [],
        unit: String(t.unit),
        attachments: t.attachments || [],
        documentId: t.documentId ? String(t.documentId) : undefined
      })) as Task[];
    } catch (error) {
      console.error('Error fetching tasks:', error);
      return [];
    }
  },

  async getDocuments(): Promise<Document[]> {
    try {
      const { data, error } = await supabase.from('documents').select('*').order('createdAt', { ascending: false });
      if (error) throw error;
      return (data || []).map((d: any) => ({
        ...d,
        createdAt: Number(d.createdAt)
      })) as Document[];
    } catch (error) {
      console.error('Error fetching documents:', error);
      return [];
    }
  },

  async insertDocument(doc: Document): Promise<{ success: boolean; error?: any }> {
    try {
      const { error } = await supabase.from('documents').insert(doc);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error inserting document:', error);
      return { success: false, error };
    }
  },

  async insertTask(task: Task): Promise<{ success: boolean; error?: any }> {
    try {
      // QUAN TRỌNG: Nếu documentId là chuỗi rỗng hoặc undefined, phải gửi NULL để không vi phạm khóa ngoại
      const dbTask = {
        id: task.id,
        userId: task.userId, 
        content: task.content,
        startTime: task.startTime,
        deadline: task.deadline || null,
        completedTime: task.completedTime || null,
        status: task.status,
        complexity: task.complexity,
        leadId: task.leadId,
        collaboratorIds: task.collaboratorIds || [],
        forwarderIds: task.forwarderIds || [],
        unit: task.unit,
        attachments: task.attachments || [],
        documentId: (task.documentId && task.documentId.trim() !== '') ? task.documentId : null
      };

      const { error } = await supabase.from('tasks').insert(dbTask);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error inserting task:', error);
      return { success: false, error };
    }
  },

  async updateTask(taskId: string, updates: Partial<Task>): Promise<{ success: boolean; error?: any }> {
    try {
      const dataToUpdate = { ...updates };
      if ('completedTime' in dataToUpdate && dataToUpdate.completedTime === undefined) {
        (dataToUpdate as any).completedTime = null;
      }
      if ('deadline' in dataToUpdate && dataToUpdate.deadline === undefined) {
        (dataToUpdate as any).deadline = null;
      }
      // Xử lý documentId khi update
      if ('documentId' in dataToUpdate) {
        dataToUpdate.documentId = (dataToUpdate.documentId && dataToUpdate.documentId.trim() !== '') ? dataToUpdate.documentId : (null as any);
      }

      const { error } = await supabase.from('tasks').update(dataToUpdate).eq('id', taskId);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error updating task:', error);
      return { success: false, error };
    }
  },

  async deleteTask(taskId: string): Promise<{ success: boolean; error?: any }> {
    try {
      const { error } = await supabase.from('tasks').delete().eq('id', taskId);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      console.error('Error deleting task:', error);
      return { success: false, error };
    }
  },

  async upsertUser(user: User): Promise<{ success: boolean; error?: any }> {
    try {
      const { error } = await supabase.from('users').upsert(user);
      if (error) throw error;
      return { success: true };
    } catch (error) {
      return { success: false, error };
    }
  }
};

import React, { useState, useMemo, useRef, useEffect } from 'react';
import { User, TaskStatus, TaskComplexity, Attachment, Document, Task } from '../types';
import { Send, Users, UserPlus, AlertCircle, ShieldAlert, Paperclip, X, Calendar, Clock, FileText, Search } from 'lucide-react';
import SearchableSelect from './SearchableSelect';

const SmartDateTimeInput: React.FC<{
  label: string;
  value: string; 
  onChange: (val: string) => void;
}> = ({ label, value, onChange }) => {
  const [displayText, setDisplayText] = useState('');
  useEffect(() => {
    if (value) {
      const [datePart, timePart] = value.split('T');
      const [y, m, d] = datePart.split('-');
      setDisplayText(`${d}/${m}/${y} ${timePart || '00:00'}:00`);
    } else setDisplayText('');
  }, [value]);

  const handleTextChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    let raw = e.target.value.replace(/\D/g, '').slice(0, 14);
    let formatted = raw;
    if (raw.length >= 3 && raw.length <= 4) formatted = `${raw.slice(0, 2)}/${raw.slice(2)}`;
    else if (raw.length >= 5 && raw.length <= 8) formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4)}`;
    else if (raw.length >= 9) formatted = `${raw.slice(0, 2)}/${raw.slice(2, 4)}/${raw.slice(4, 8)} ${raw.slice(8, 10)}:${raw.slice(10, 12)}`;
    setDisplayText(formatted);
    if (raw.length >= 12) {
      const d = raw.slice(0, 2), m = raw.slice(2, 4), y = raw.slice(4, 8), hh = raw.slice(8, 10), min = raw.slice(10, 12);
      const ds = `${y}-${m}-${d}T${hh}:${min}`;
      if (!isNaN(new Date(ds).getTime())) onChange(ds);
    }
  };

  return (
    <div className="w-full">
      <label className="block text-[10px] font-black text-slate-400 uppercase mb-1.5 tracking-widest">{label}</label>
      <div className="relative group">
        <input type="text" value={displayText} onChange={handleTextChange} placeholder="DD/MM/YYYY HH:mm:ss" className="w-full bg-slate-50 border border-slate-200 rounded-2xl px-5 py-4 outline-none focus:ring-2 focus:ring-indigo-500 font-bold text-sm" />
        <div className="absolute right-4 top-1/2 -translate-y-1/2"><Clock size={18} className="text-slate-300" /></div>
        <input type="datetime-local" value={value} onChange={(e) => onChange(e.target.value)} className="absolute inset-0 opacity-0 cursor-pointer" />
      </div>
    </div>
  );
};

interface DelegationProps {
  currentUser: User;
  users: User[];
  documents: Document[];
  tasks: Task[];
  onAssign: (content: string, complexity: TaskComplexity, leadId: string, collaboratorIds: string[], attachments?: Attachment[], deadline?: number, documentId?: string) => void;
}

const Delegation: React.FC<DelegationProps> = ({ currentUser, users, documents, tasks, onAssign }) => {
  const [content, setContent] = useState('');
  const [complexity, setComplexity] = useState<TaskComplexity>(TaskComplexity.MEDIUM);
  const [deadline, setDeadline] = useState('');
  const [selectedUnit, setSelectedUnit] = useState(currentUser.unit);
  const [leadId, setLeadId] = useState('');
  const [collaboratorIds, setCollaboratorIds] = useState<string[]>([]);
  const [attachments, setAttachments] = useState<Attachment[]>([]);
  const [selectedDocId, setSelectedDocId] = useState('');
  const fileInputRef = useRef<HTMLInputElement>(null);

  // 1. Logic lọc và sắp xếp văn bản
  const docOptions = useMemo(() => {
    // Chỉ lấy văn bản chưa có Task nào liên kết
    const assignedDocIds = new Set(tasks.map(t => t.documentId).filter(id => !!id));
    const unassignedDocs = documents.filter(d => !assignedDocIds.has(d.id));

    // Sắp xếp: có hạn hoàn thành gần nhất -> xa nhất -> không có hạn xử lý xếp cuối
    const sortedDocs = [...unassignedDocs].sort((a, b) => {
      // Trường hợp cả hai đều không có hạn
      if (!a.deadline && !b.deadline) return b.createdAt - a.createdAt;
      // Ưu tiên bản có hạn lên đầu
      if (!a.deadline) return 1;
      if (!b.deadline) return -1;
      // So sánh ngày (YYYY-MM-DD)
      return a.deadline.localeCompare(b.deadline);
    });

    return sortedDocs.map(d => ({
      id: d.id,
      label: d.refCode || `Số đến: ${d.docNumber}`,
      subLabel: d.summary
    }));
  }, [documents, tasks]);

  const handleDocSelect = (docId: string) => {
    setSelectedDocId(docId);
    const doc = documents.find(d => d.id === docId);
    if (doc) {
      setContent(doc.summary);
      if (doc.deadline) {
        setDeadline(`${doc.deadline}T23:59`);
      }
    }
  };

  // 2. Logic sắp xếp nhân sự: Phó trưởng phòng lên trước
  const targetEmployees = useMemo(() => {
    const canDelegateTo = (targetLevel: string) => {
      const currRank = parseInt(currentUser.delegateLevel.replace(/\D/g, '')) || 99;
      const targetRank = parseInt(targetLevel.replace(/\D/g, '')) || 99;
      return targetRank > currRank;
    };

    const pool = users.filter(u => u.unit === selectedUnit && canDelegateTo(u.delegateLevel));

    return [...pool].sort((a, b) => {
      const isViceA = a.position.toLowerCase().includes('phó trưởng phòng');
      const isViceB = b.position.toLowerCase().includes('phó trưởng phòng');

      if (isViceA && !isViceB) return -1;
      if (!isViceA && isViceB) return 1;

      // Nếu cùng cấp thì xếp theo tên
      return a.name.localeCompare(b.name, 'vi');
    });
  }, [selectedUnit, users, currentUser.delegateLevel]);

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = e.target.files;
    if (!files) return;
    const newAtts = await Promise.all(Array.from(files).map(file => new Promise<Attachment>((resolve) => {
      const reader = new FileReader();
      reader.onload = (ev) => resolve({ name: file.name, type: file.type, data: ev.target?.result as string });
      reader.readAsDataURL(file);
    })));
    setAttachments([...attachments, ...newAtts]);
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!content.trim() || !leadId) return;
    const deadlineTs = deadline ? new Date(deadline).getTime() : undefined;
    onAssign(content, complexity, leadId, collaboratorIds, attachments, deadlineTs, selectedDocId);
    alert('Đã giao nhiệm vụ thành công!');
    setContent(''); setLeadId(''); setDeadline(''); setCollaboratorIds([]); setAttachments([]); setSelectedDocId('');
  };

  return (
    <div className="max-w-4xl mx-auto pb-20">
      <div className="bg-white rounded-[2.5rem] border border-slate-200 shadow-sm overflow-hidden">
        <div className="p-10 bg-indigo-600 text-white"><h2 className="text-3xl font-black flex items-center space-x-4"><Send size={32} /> <span>Giao nhiệm vụ công tác</span></h2></div>
        <form onSubmit={handleSubmit} className="p-10 space-y-8">
          <div className="bg-indigo-50 p-6 rounded-[1.5rem] border border-indigo-100 space-y-4">
            <SearchableSelect 
              label="Căn cứ vào văn bản gốc (Chỉ hiển thị VB chưa giao)" 
              options={docOptions} 
              value={selectedDocId} 
              onChange={handleDocSelect} 
              placeholder="Chọn văn bản căn cứ..." 
            />
          </div>

          <div>
            <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">Nội dung công việc *</label>
            <textarea value={content} onChange={e => setContent(e.target.value)} required rows={4} className="w-full bg-slate-50 border border-slate-200 rounded-[1.5rem] px-6 py-5 outline-none focus:ring-2 focus:ring-indigo-500 font-medium text-lg" />
          </div>

          <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">Mức độ</label>
              <select value={complexity} onChange={e => setComplexity(e.target.value as TaskComplexity)} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-4 font-bold uppercase text-xs">
                {Object.values(TaskComplexity).map(c => <option key={c} value={c}>{c}</option>)}
              </select>
            </div>
            <SmartDateTimeInput label="Hạn chót" value={deadline} onChange={setDeadline} />
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase tracking-widest mb-3 ml-1">Đơn vị nhận</label>
              <select value={selectedUnit} onChange={e => { setSelectedUnit(e.target.value); setLeadId(''); setCollaboratorIds([]); }} className="w-full bg-slate-50 border border-slate-200 rounded-xl px-4 py-4 font-bold text-sm">
                {Array.from(new Set(users.map(u => u.unit))).map(u => <option key={u} value={u}>{u}</option>)}
              </select>
            </div>
          </div>

          <div>
            <div className="flex justify-between items-center mb-3 ml-1">
              <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest">Tệp đính kèm</label>
              <button type="button" onClick={() => fileInputRef.current?.click()} className="text-indigo-600 text-xs font-black uppercase flex items-center hover:underline"><Paperclip size={14} className="mr-1" /> Thêm tệp</button>
            </div>
            <input type="file" ref={fileInputRef} onChange={handleFileChange} className="hidden" multiple />
            {attachments.length > 0 && (
              <div className="flex flex-wrap gap-2 p-4 bg-slate-50 rounded-2xl">
                {attachments.map((att, i) => (
                  <div key={i} className="flex items-center space-x-2 bg-white px-3 py-1.5 rounded-lg border border-slate-200 text-[10px] font-bold">
                    <span className="truncate max-w-[120px]">{att.name}</span>
                    <button type="button" onClick={() => setAttachments(prev => prev.filter((_, idx) => idx !== i))} className="text-rose-500"><X size={12} /></button>
                  </div>
                ))}
              </div>
            )}
          </div>

          <div className="space-y-6">
            <SearchableSelect label="Người chủ trì * (Ưu tiên PTP)" options={targetEmployees.map(u => ({ id: u.id, label: u.name, subLabel: u.position }))} value={leadId} onChange={setLeadId} placeholder="Chọn nhân sự..." />
            <div>
              <label className="block text-[10px] font-black text-slate-400 uppercase mb-3 tracking-widest">Phối hợp thực hiện</label>
              <div className="grid grid-cols-2 md:grid-cols-3 gap-2">
                {targetEmployees.filter(u => u.id !== leadId).map(u => (
                  <button key={u.id} type="button" onClick={() => setCollaboratorIds(prev => prev.includes(u.id) ? prev.filter(id => id !== u.id) : [...prev, u.id])} className={`px-4 py-2 rounded-xl text-[10px] font-black uppercase border transition-all ${collaboratorIds.includes(u.id) ? 'bg-indigo-600 text-white border-indigo-600' : 'bg-white text-slate-500 border-slate-200 hover:border-indigo-300'}`}>
                    {u.name}
                  </button>
                ))}
              </div>
            </div>
          </div>

          <button type="submit" disabled={!leadId} className={`w-full py-5 rounded-2xl font-black uppercase tracking-widest text-sm shadow-xl transition-all ${leadId ? 'bg-indigo-600 text-white hover:bg-indigo-700 active:scale-[0.98]' : 'bg-slate-200 text-slate-400'}`}>Xác nhận giao nhiệm vụ</button>
        </form>
      </div>
    </div>
  );
};

export default Delegation;

import React, { useMemo } from 'react';
import { User } from '../types';
import { 
  LayoutDashboard, 
  ListTodo, 
  Search, 
  Send, 
  UserCircle, 
  LogOut,
  X,
  FilePlus,
  FileSearch
} from 'lucide-react';

interface SidebarProps {
  activeTab: string;
  setActiveTab: (tab: any) => void;
  isAdmin: boolean;
  currentUser: User;
  onLogout: () => void;
  isOpen: boolean;
  onClose: () => void;
}

const Sidebar: React.FC<SidebarProps> = ({ activeTab, setActiveTab, isAdmin, currentUser, onLogout, isOpen, onClose }) => {
  const menuItems = useMemo(() => {
    const items = [
      { id: 'dashboard', label: 'Tổng quan', icon: LayoutDashboard },
      { id: 'tasks', label: 'Việc của tôi', icon: ListTodo },
      { id: 'search', label: 'Tra cứu & Báo cáo', icon: Search },
      { id: 'delegate', label: 'Giao việc', icon: Send },
      { id: 'doc-entry', label: 'Nhập văn bản', icon: FilePlus, roles: ['VT'] },
      { id: 'doc-search', label: 'Tra cứu văn bản', icon: FileSearch },
      { id: 'profile', label: 'Hồ sơ cá nhân', icon: UserCircle },
    ];

    return items.filter(item => {
      // Tab Giao việc
      if (item.id === 'delegate') {
        return currentUser.delegateLevel === 'X1' || currentUser.delegateLevel === 'X2';
      }
      // Tab Nhập văn bản (Chỉ dành cho Văn thư)
      if (item.id === 'doc-entry') {
        return currentUser.notes === 'VT';
      }
      // Tab Tra cứu văn bản (Văn thư HOẶC cấp X1)
      if (item.id === 'doc-search') {
        return currentUser.notes === 'VT' || currentUser.delegateLevel === 'X1';
      }
      // Các tab khác có định nghĩa roles cố định
      if (item.roles) {
        return item.roles.includes(currentUser.notes);
      }
      return true;
    });
  }, [currentUser.delegateLevel, currentUser.notes]);

  const logoUrl = "https://lh3.googleusercontent.com/d/1FUb404uLq8ton8azidI9UrR1DLs7Byds";

  return (
    <>
      <div className={`fixed inset-0 bg-slate-900/60 backdrop-blur-sm z-50 md:hidden transition-opacity duration-300 ${isOpen ? 'opacity-100 pointer-events-auto' : 'opacity-0 pointer-events-none'}`} onClick={onClose} />
      <aside className={`fixed inset-y-0 left-0 w-72 bg-white border-r border-slate-200 flex flex-col z-[60] transition-all duration-300 ease-in-out md:translate-x-0 md:static md:h-screen md:w-64 lg:w-72 ${isOpen ? 'translate-x-0' : '-translate-x-full'}`}>
        <div className="p-6 border-b border-slate-100 flex items-center justify-between">
          <div className="flex items-center space-x-3">
            <div className="w-12 h-12 rounded-full overflow-hidden border-2 border-amber-400 shadow-md bg-white p-0.5 flex items-center justify-center">
              <img src={logoUrl} alt="Logo" className="w-full h-full object-contain scale-125" />
            </div>
            <span className="text-sm font-black tracking-tight text-slate-800 uppercase">Quản lý<br/>công việc</span>
          </div>
          <button onClick={onClose} className="md:hidden p-2 text-slate-400"><X size={24} /></button>
        </div>

        <nav className="flex-1 p-4 space-y-2 overflow-y-auto">
          {menuItems.map((item) => {
            const Icon = item.icon;
            return (
              <button
                key={item.id}
                onClick={() => setActiveTab(item.id)}
                className={`w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl transition-all ${activeTab === item.id ? 'bg-indigo-600 text-white font-bold shadow-lg' : 'text-slate-500 hover:bg-slate-50'}`}
              >
                <Icon size={20} />
                <span className="text-sm">{item.label}</span>
              </button>
            );
          })}
        </nav>

        <div className="p-4 border-t border-slate-100">
          <div className="mb-4 p-4 bg-slate-50 rounded-2xl flex items-center space-x-3">
            <img src={`https://picsum.photos/seed/${currentUser.id}/100`} alt="Ava" className="w-10 h-10 rounded-xl object-cover" />
            <div className="flex-1 min-w-0">
              <p className="text-xs font-black text-slate-800 truncate uppercase">{currentUser.name}</p>
              <p className="text-[10px] text-slate-400 font-bold truncate uppercase tracking-tighter">{currentUser.unit}</p>
            </div>
          </div>
          <button onClick={onLogout} className="w-full flex items-center space-x-3 px-4 py-3.5 rounded-2xl text-rose-500 hover:bg-rose-50 font-bold text-sm">
            <LogOut size={18} />
            <span>Đăng xuất</span>
          </button>
        </div>
      </aside>
    </>
  );
};

export default Sidebar;

import React, { useState, useEffect } from 'react';
import { User, Task, TaskStatus, TaskComplexity, Attachment, Document } from './types';
import { Menu, Loader2, RefreshCw, AlertTriangle } from 'lucide-react';
import { cloudStorage } from './storage';
import Login from './components/Login';
import ChangePassword from './components/ChangePassword';
import Sidebar from './components/Sidebar';
import Dashboard from './components/Dashboard';
import TaskBoard from './components/TaskBoard';
import AdminSearch from './components/AdminSearch';
import Delegation from './components/Delegation';
import UserProfile from './components/UserProfile';
import DocumentEntry from './components/DocumentEntry';
import DocumentSearch from './components/DocumentSearch';

const App: React.FC = () => {
  const [users, setUsers] = useState<User[]>([]);
  const [tasks, setTasks] = useState<Task[]>([]);
  const [documents, setDocuments] = useState<Document[]>([]);
  const [currentUser, setCurrentUser] = useState<User | null>(null);
  const [isInitialLoading, setIsInitialLoading] = useState(true);
  const [isSyncing, setIsSyncing] = useState(false);
  const [syncError, setSyncError] = useState<string | null>(null);

  const [activeTab, setActiveTab] = useState<string>('dashboard');
  const [viewedUserId, setViewedUserId] = useState<string | null>(null);
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);

  useEffect(() => {
    const initData = async () => {
      try {
        const [dbUsers, dbTasks, dbDocs] = await Promise.all([
          cloudStorage.getUsers(),
          cloudStorage.getTasks(),
          cloudStorage.getDocuments()
        ]);
        setUsers(dbUsers);
        setTasks(dbTasks);
        setDocuments(dbDocs);

        const savedUserStr = localStorage.getItem('tm_current_user');
        if (savedUserStr) {
          const parsedUser = JSON.parse(savedUserStr);
          const stillExists = dbUsers.find(u => u.id === parsedUser.id);
          if (stillExists) {
            setCurrentUser(stillExists);
          } else {
            localStorage.removeItem('tm_current_user');
          }
        }
      } catch (err) {
        console.error("Initialization Error:", err);
        setSyncError("Lỗi kết nối cơ sở dữ liệu Cloud.");
      } finally {
        setIsInitialLoading(false);
      }
    };
    initData();
  }, []);

  const handleLogin = (user: User) => {
    setCurrentUser(user);
    localStorage.setItem('tm_current_user', JSON.stringify(user));
    if (!user.mustChangePassword) setActiveTab('dashboard');
  };

  const handleLogout = () => {
    setCurrentUser(null);
    localStorage.removeItem('tm_current_user');
    setActiveTab('dashboard');
    setIsSidebarOpen(false);
  };

  const handleChangePassword = async (newPass: string) => {
    if (!currentUser) return;
    const updated = { ...currentUser, password: newPass, mustChangePassword: false };
    setIsSyncing(true);
    const result = await cloudStorage.upsertUser(updated);
    if (result.success) {
      setUsers(prev => prev.map(u => u.id === currentUser.id ? updated : u));
      setCurrentUser(updated);
      localStorage.setItem('tm_current_user', JSON.stringify(updated));
    }
    setIsSyncing(false);
  };

  const handleResetPassword = async (email: string, newPass: string) => {
    const target = users.find(u => u.email.toLowerCase() === email.toLowerCase());
    if (target) {
      const updated = { ...target, password: newPass, mustChangePassword: true };
      setIsSyncing(true);
      await cloudStorage.upsertUser(updated);
      setUsers(prev => prev.map(u => u.id === target.id ? updated : u));
      setIsSyncing(false);
    }
  };

  const handleAddDocument = async (doc: Document): Promise<boolean> => {
    setIsSyncing(true);
    const result = await cloudStorage.insertDocument(doc);
    if (result.success) {
      setDocuments(prev => [doc, ...prev]);
      setIsSyncing(false);
      return true;
    } else {
      console.error("Lỗi khi lưu văn bản:", result.error);
      setIsSyncing(false);
      return false;
    }
  };

  const addTask = async (content: string, complexity: TaskComplexity, leadId?: string, collaboratorIds?: string[], attachments?: Attachment[], deadline?: number, documentId?: string) => {
    if (!currentUser) return;
    const newTask: Task = {
      id: Math.random().toString(36).substr(2, 9),
      userId: currentUser.id,
      content,
      startTime: Date.now(),
      deadline: deadline,
      status: TaskStatus.TO_DO, 
      complexity,
      leadId: leadId || currentUser.id,
      collaboratorIds: collaboratorIds || [],
      forwarderIds: [],
      unit: currentUser.unit,
      attachments: attachments || [],
      documentId
    };

    setIsSyncing(true);
    const result = await cloudStorage.insertTask(newTask);
    if (result.success) {
      setTasks(prev => [newTask, ...prev]);
    } else {
      console.error("Lỗi lưu Task:", result.error);
      alert("Không thể lưu công việc vào Database. Vui lòng kiểm tra kết nối mạng hoặc cấu hình bảng tasks trên Supabase.");
    }
    setIsSyncing(false);
  };

  const updateTaskStatus = async (taskId: string, newStatus: TaskStatus) => {
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates: Partial<Task> = {
      status: newStatus,
      completedTime: newStatus === TaskStatus.COMPLETED ? Date.now() : undefined,
      startTime: (newStatus === TaskStatus.IN_PROGRESS && task.status === TaskStatus.TO_DO) ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const handleForwardTask = async (taskId: string, newLeadId: string, newCollaboratorIds: string[]) => {
    if (!currentUser) return;
    const task = tasks.find(t => t.id === taskId);
    if (!task) return;
    const updates: Partial<Task> = {
      leadId: newLeadId,
      collaboratorIds: newCollaboratorIds,
      forwarderIds: [...(task.forwarderIds || []), currentUser.id],
      status: TaskStatus.IN_PROGRESS,
      startTime: task.status === TaskStatus.TO_DO ? Date.now() : task.startTime
    };
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const updateTask = async (taskId: string, updates: Partial<Task>) => {
    setIsSyncing(true);
    const result = await cloudStorage.updateTask(taskId, updates);
    if (result.success) setTasks(prev => prev.map(t => t.id === taskId ? { ...t, ...updates } : t));
    setIsSyncing(false);
  };

  const deleteTask = async (taskId: string) => {
    if (window.confirm('Bạn có chắc chắn muốn xóa công việc này?')) {
      setIsSyncing(true);
      const result = await cloudStorage.deleteTask(taskId);
      if (result.success) setTasks(prev => prev.filter(t => t.id !== taskId));
      setIsSyncing(false);
    }
  };

  if (isInitialLoading) {
    return (
      <div className="min-h-screen flex flex-col items-center justify-center bg-slate-50">
        <Loader2 className="w-12 h-12 text-indigo-600 animate-spin mb-4" />
        <p className="text-slate-500 font-bold uppercase tracking-widest text-xs">Đang tải dữ liệu Cloud...</p>
      </div>
    );
  }

  if (!currentUser) return <Login users={users} onLogin={handleLogin} onResetPassword={handleResetPassword} />;
  if (currentUser.mustChangePassword) return <ChangePassword onComplete={handleChangePassword} />;

  const isAdmin = currentUser.notes === 'AD1' || currentUser.notes === 'AD2';
  const isVT = currentUser.notes === 'VT';
  const isX1 = currentUser.delegateLevel === 'X1';
  const canDelegate = currentUser.delegateLevel === 'X1' || currentUser.delegateLevel === 'X2';

  const myRecentTasks = tasks.filter(t => {
    const isRelated = t.userId === currentUser.id || t.leadId === currentUser.id || t.collaboratorIds.includes(currentUser.id) || (t.forwarderIds && t.forwarderIds.includes(currentUser.id));
    const twoMonthsAgo = Date.now() - (60 * 24 * 60 * 60 * 1000);
    return isRelated && t.startTime >= twoMonthsAgo;
  });

  return (
    <div className="flex min-h-screen bg-slate-50 flex-col md:flex-row overflow-x-hidden">
      <Sidebar 
        activeTab={activeTab} 
        setActiveTab={(tab) => { setActiveTab(tab); setIsSidebarOpen(false); }} 
        isAdmin={isAdmin} 
        currentUser={currentUser}
        onLogout={handleLogout}
        isOpen={isSidebarOpen}
        onClose={() => setIsSidebarOpen(false)}
      />

      <main className="flex-1 min-w-0 p-4 md:p-8 lg:p-10">
        <header className="mb-6 flex justify-between items-center">
          <h1 className="text-2xl md:text-3xl font-black text-slate-800 tracking-tight flex items-center gap-3 uppercase">
            {activeTab === 'dashboard' && 'Tổng quan'}
            {activeTab === 'tasks' && 'Việc của tôi'}
            {activeTab === 'search' && 'Tra cứu & Báo cáo'}
            {activeTab === 'delegate' && 'Giao việc'}
            {activeTab === 'doc-entry' && 'Nhập văn bản'}
            {activeTab === 'doc-search' && 'Tra cứu văn bản'}
            {isSyncing && <RefreshCw className="text-indigo-400 animate-spin" size={24} />}
          </h1>
        </header>

        <div className="w-full">
          {activeTab === 'dashboard' && <Dashboard users={users} tasks={tasks} currentUser={currentUser} onUserClick={(uid) => { setViewedUserId(uid); setActiveTab('search'); }} />}
          {activeTab === 'tasks' && <TaskBoard tasks={myRecentTasks} onAddTask={addTask} onUpdateStatus={updateTaskStatus} onUpdateTask={updateTask} onDeleteTask={deleteTask} onForwardTask={handleForwardTask} currentUser={currentUser} allUsers={users} />}
          {activeTab === 'search' && <AdminSearch users={users} tasks={tasks} isAdmin={isAdmin} currentUser={currentUser} onUpdateTask={updateTask} onResetUserPassword={handleResetPassword} initialSelectedUserId={viewedUserId} />}
          {activeTab === 'delegate' && <Delegation currentUser={currentUser} users={users} documents={documents} tasks={tasks} onAssign={addTask} />}
          {activeTab === 'doc-entry' && isVT && <DocumentEntry onAdd={handleAddDocument} />}
          {activeTab === 'doc-search' && (isVT || isX1) && <DocumentSearch documents={documents} tasks={tasks} users={users} />}
          {activeTab === 'profile' && <UserProfile user={currentUser} />}
        </div>
      </main>
    </div>
  );
};

