}

export interface Task {
  id: string;
  userId: string;
  content: string;
  startTime: number;
  deadline?: number; // Hạn chót (timestamp)
  completedTime?: number; 
  status: TaskStatus;
  complexity: TaskComplexity;
  category: TaskCategory; // Nhóm công việc
  leadId: string;
  collaboratorIds: string[];
  forwarderIds?: string[]; 
  unit: string;
